  ui_story_5033_50330101_1_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5033_50330101_2_dialog_content = "¡Mira, mamá! ¡Esa persona de allí se cayó mientras caminaba!",
  ui_story_5033_50330101_3_dialog_content = "Espera aquí. Déjame ir a echar un vistazo.",
  ui_story_5033_50330101_4_dialog_content = "¿Q-Qué es esto...?",
  ui_story_5033_50330101_5_dialog_content = "<size=45>¡Aaaagh!</size>",
  ui_story_5033_50330101_6_dialog_content = "<color=#e8d9bb>Una calle desconocida en Umbraton</color>",
  ui_story_5033_50330101_7_dialog_content = "(Llego muy tarde...)",
  ui_story_5033_50330101_8_dialog_content = "¿Estás seguro de que no viste a nadie más alrededor?",
  ui_story_5033_50330101_9_dialog_content = "No... Y mi hijo solo vio caer a la víctima.",
  ui_story_5033_50330101_10_dialog_content = "Se tambaleó un poco antes de colapsar.",
  ui_story_5033_50330101_11_dialog_content = "Cuando lo alcancé, ya estaba...",
  ui_story_5033_50330101_12_dialog_content = "Muy bien, lo tengo.",
  ui_story_5033_50330101_13_dialog_content = "Yo manejaré esto. Usted puede irse ahora.",
  ui_story_5033_50330101_14_dialog_content = "No es realmente seguro en Umbraton últimamente, así que trata de no tomar caminos apartados.",
  ui_story_5033_50330101_15_dialog_content = "Ah...",
  ui_story_5033_50330101_16_dialog_content = "OK gracias...",
  ui_story_5033_50330101_17_dialog_content = "Vamos, hijo. Y deja de mirar.",
  ui_story_5033_50330101_18_dialog_content = "*Suspira*",
  ui_story_5033_50330101_19_dialog_content = "(Otro callejón sin salida. Todavía no puedo alcanzar al delincuente).",
  ui_story_5033_50330101_20_dialog_content = "(Lo único seguro es que este tipo murió de la misma manera que las <color=#FFB400>víctimas anteriores</color>).",
  ui_story_5033_50330101_21_dialog_content = "¡Esp. un segundo!",
  ui_story_5033_50330101_22_dialog_content = "(Todavía hay respiraciones débiles saliendo de él, podría él...)",
  ui_story_5033_50330101_23_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_5033_50330101_24_dialog_content = "Lo siento, Señor de las Sombras, todo lo que quedó fue la víctima. Los testigos no vieron a nadie más.",
  ui_story_5033_50330101_25_dialog_content = "¿Quién fue la savia desafortunada?",
  ui_story_5033_50330101_26_dialog_content = "El forastero que hizo su fortuna con las apuestas de caballos. Se cayó justo afuera de su casa. Parecía que estaba en camino a alguna parte. Pero...",
  ui_story_5033_50330101_27_dialog_content = "Basado en mi inspección preliminar, creo que aún puede ser salvado.",
  ui_story_5033_50330101_28_dialog_content = "Deberíamos aprovechar esta oportunidad.",
  ui_story_5033_50330101_29_dialog_content = "Enviaré a alguien a resucitarlo ahora mismo. Quédate en el caso.",
  ui_story_5033_50330101_30_dialog_content = "¿Algo sobre el perpetrador esta vez?",
  ui_story_5033_50330101_31_dialog_content = "Si relacionamos este crimen con casos anteriores, las heridas de la víctima son idénticas a las del <color=#FFB400>asesinato de la monja</color> hace varios años.",
  ui_story_5033_50330101_32_dialog_content = "Un detalle crucial se pasó por alto en todas las investigaciones anteriores.",
  ui_story_5033_50330101_33_dialog_content = "Todas las víctimas sufrieron un pequeño corte en el cuerpo antes de colapsar repentinamente por una razón que aún no se ha determinado.",
  ui_story_5033_50330101_34_dialog_content = "Los cortes son siempre casi demasiado pequeños para que los vea el ojo desnudo y no parecen letales.",
  ui_story_5033_50330101_35_dialog_content = "Pero tras una inspección más cercana de nuestra víctima más reciente, estoy bastante seguro de que es una herida de cuchillo.",
  ui_story_5033_50330101_36_dialog_content = "El culpable es muy hábil. El cuchillo entra con rapidez y precisión, golpeando justo en el lugar correcto.",
  ui_story_5033_50330101_37_dialog_content = "Corax, te puse en el caso para traer vivo al perpetrador.",
  ui_story_5033_50330101_38_dialog_content = "Eres médico. Deberías saber qué hacer.",
  ui_story_5033_50330101_39_dialog_content = "... Por favor, deme más tiempo, señor.",
  ui_story_5033_50330101_40_dialog_content = "¿Cuáles son tus planes?",
  ui_story_5033_50330101_41_dialog_content = "Seguiré el plan original y mantendré los ojos abiertos.",
  ui_story_5033_50330101_42_dialog_content = "Actúe con rapidez y precaución.",
  ui_story_5033_50330101_43_dialog_content = "Yo debo.",
  ui_story_5033_50330101_44_dialog_content = "<color=#e8d9bb>Un mes después, en la Convención de artículos para el hogar en Umbraton</color>",
  ui_story_5033_50330101_45_dialog_content = "<size=45>¡Extra, extra!</size>",
  ui_story_5033_50330101_46_dialog_content = "¡Novedades de Umbraton recién salidas del horno! ¡Consigue ya tu deliciosa prensa!",
  ui_story_5033_50330101_47_dialog_content = "(¡¿Quién describe un periódico así?!)",
  ui_story_5033_50330101_48_dialog_content = "¡Oye!",
  ui_story_5033_50330101_49_dialog_content = "PlayerName! ¡Qué vista tan rara! ¿Estás solo en Umbraton?",
  ui_story_5033_50330101_50_dialog_content = "(¡Oh no, me atraparon!)",
  ui_story_5033_50330101_51_dialog_content = "Entonces, ¿qué hay de recoger una copia? ¡No querrás perderte esto recién llegado!",
  ui_story_5033_50330101_52_dialog_content = "\"Umbraton ha estado plagado de <color=#FFB400>misteriosos asesinatos en serie</color> en las últimas semanas\"...",
  ui_story_5033_50330101_53_dialog_content = "\"Varias personas vinculadas al <color=#FFB400>mercado negro</color> han sido encontradas muertas en sus casas\"...",
  ui_story_5033_50330101_54_dialog_content = "\"Las víctimas mostraron <color=#FFB400>peculiares signos de lucha</color>, y el asesino sigue prófugo\"...",
  ui_story_5033_50330101_55_dialog_content = "¿Cómo es eso? ¿Estás sintiendo la necesidad de arrebatar el papel ahora mismo?",
  ui_story_5033_50330101_56_dialog_content = "¡No, soy bueno! No estoy aquí para comprar un periódico hoy.",
  ui_story_5033_50330101_57_dialog_content = "Vamos, PlayerName, ya estás aquí. ¡Tienes que comprar algo!",
  ui_story_5033_50330101_58_dialog_content = "En realidad...",
  ui_story_5033_50330101_59_dialog_content = "<color=#e8d9bb>Hace varios días en Cloud Gardens</color>",
  ui_story_5033_50330101_60_dialog_content = "(Uf, finalmente, Cloud Gardens está más presentable ahora).",
  ui_story_5033_50330101_61_dialog_content = "(He estado trabajando en el proyecto durante tanto tiempo que merezco un descanso).",
  ui_story_5033_50330101_62_dialog_content = "Pero esto no es lo suficientemente bueno todavía.",
  ui_story_5033_50330101_63_dialog_content = "¡¿Qué?! ¿Cómo supiste lo que era?",
  ui_story_5033_50330101_64_dialog_content = "Tu cara me dijo que estabas a punto de rendirte, PlayerName.",
  ui_story_5033_50330101_65_dialog_content = "Tenemos los muebles básicos en su lugar, pero todavía está demasiado vacío y simple.",
  ui_story_5033_50330101_66_dialog_content = "¡Aquí!",
  ui_story_5033_50330101_67_dialog_content = "Vaya, ¿qué es esta pila?",
  ui_story_5033_50330101_68_dialog_content = "¡Catálogos de expositores para la convención anual de artículos para el hogar de Umbraton!",
  ui_story_5033_50330101_69_dialog_content = "¡No querrás saber por cuántas conexiones tuve que pasar para recolectarlos todos!",
  ui_story_5033_50330101_70_dialog_content = "... Has estado planeando esto desde siempre, ¿no es así?",
  ui_story_5033_50330101_71_dialog_content = "¡No nos detengamos en los pequeños detalles!",
  ui_story_5033_50330101_72_dialog_content = "De todos modos, la renovación no es un asunto baladí. Esta es tu casa, después de todo.",
  ui_story_5033_50330101_73_dialog_content = "Ahora imagínese finalmente llegar a casa y relajarse después de un largo viaje. ¿Que ves?",
  ui_story_5033_50330101_74_dialog_content = "Oh, me gustaría acurrucarme en un sillón reclinable.",
  ui_story_5033_50330101_75_dialog_content = "¿Qué le parece el sillón reclinable? ¿Está hecho de satén suave o de cuero fresco?",
  ui_story_5033_50330101_76_dialog_content = "¡Cuero para un sillón reclinable, por supuesto! Y se vería más genial.",
  ui_story_5033_50330101_77_dialog_content = "¿Ver? Los muebles y la decoración no solo ayudan con la satisfacción, sino que también son una buena manera de mostrar su estilo.",
  ui_story_5033_50330101_78_dialog_content = "Todas las cosas que entran en su hogar deben elegirse con cuidado.",
  ui_story_5033_50330101_79_dialog_content = "WW-¡Espera un momento!",
  ui_story_5033_50330101_80_dialog_content = "No estarás intentando que lea todos estos folletos, ¿verdad?",
  ui_story_5033_50330101_81_dialog_content = "¡No es como si tuvieras algo que hacer en los próximos días!",
  ui_story_5033_50330101_82_dialog_content = "Y tienes que manejar cada paso en la renovación personalmente, de todos modos.",
  ui_story_5033_50330101_83_dialog_content = "Muy bien, ahora no hay tiempo para charlas.",
  ui_story_5033_50330101_84_dialog_content = "Tenemos que prepararnos. Ir de compras es la guerra, ya sabes!",
  ui_story_5033_50330101_85_dialog_content = "Recuerde el material, el acabado y el estilo de cada artículo.",
  ui_story_5033_50330101_86_dialog_content = "Examine y evalúe todo a fondo antes de hacer la lista final, ¡así estará preparado para la convención!",
  ui_story_5033_50330101_87_dialog_content = "¡Sí, Oficial Vice!",
  ui_story_5033_50330101_88_dialog_content = "Así, hojeamos los folletos durante cuatro días enteros con muy poco sueño.",
  ui_story_5033_50330101_89_dialog_content = "¡Wow impresionante!",
  ui_story_5033_50330101_90_dialog_content = "Sí. Vice estaba tan centrado en el láser que podía atravesarlos con los ojos.",
  ui_story_5033_50330101_91_dialog_content = "Pensé que todo lo que tenía que hacer era seguir a Vice por la convención.",
  ui_story_5033_50330101_92_dialog_content = "Sin embargo...",
  ui_story_5033_50330101_93_dialog_content = "<color=#e8d9bb>Justo antes de la salida</color>",
  ui_story_5033_50330101_94_dialog_content = "Oh Dios, lo siento mucho, PlayerName!!!",
  ui_story_5033_50330101_95_dialog_content = "Acabo de recibir una tarea urgente del Comandante Hiiro...",
  ui_story_5033_50330101_96_dialog_content = "Entonces, terminé viniendo solo sin ninguna pista o presupuesto en mente.",
  ui_story_5033_50330101_97_dialog_content = "Aunque que pena, PlayerName. La convención fue <color=#FFB400>cancelada</color> en el último minuto.",
  ui_story_5033_50330101_98_dialog_content = "¡¿Qué?!",
  ui_story_5033_50330101_99_dialog_content = "Es debido a los asesinatos en serie que pusieron nerviosos a todos.",
  ui_story_5033_50330101_100_dialog_content = "Debido a preocupaciones de seguridad, Umbraton canceló todas las grandes reuniones por el momento.",
  ui_story_5033_50330101_101_dialog_content = "Re... ¿En serio?!",
  ui_story_5033_50330101_102_dialog_content = "Que mala suerte...",
  ui_story_5033_50330101_103_dialog_content = "No estés todo deprimido. Umbraton tiene un montón de cosas a la venta.",
  ui_story_5033_50330101_104_dialog_content = "¡Mira a tu alrededor y es posible que encuentres algo genial!",
  ui_story_5033_50330101_105_dialog_content = "Bueno, ¡tengo que correr ahora!",
  ui_story_5033_50330101_106_dialog_content = "¡Gracias, Wendy!",
  ui_story_5033_50330101_107_dialog_content = "¿Dónde debo ir entonces?",
  ui_story_5033_50330101_108_dialog_content = "¿Mmm? ¿Es este un puesto especializado en... postales?",
  ui_story_5033_50330101_109_dialog_content = "Este color es muy bonito.",
  ui_story_5033_50330101_110_dialog_content = "Las postales también pueden ser decoración para el hogar, ya sabes.",
  ui_story_5033_50330101_111_dialog_content = "Siéntase libre de mirar a través de ellos. Destacan diferentes pueblos y lugares alrededor de Umbraton.",
  ui_story_5033_50330101_112_dialog_content = "(Bueno, al menos tengo suficiente para comprar una postal...)",
  ui_story_5033_50330101_113_dialog_content = "Supongo que tomaré el que estoy sosteniendo entonces.",
  ui_story_5033_50330101_114_dialog_content = "¡Gracias, y por favor ven de nuevo!",
  ui_story_5033_50330101_115_dialog_content = "(La ciudad de esta postal se llama... <color=#FFB400>Euphoria</color>?)",
  ui_story_5033_50330101_116_dialog_content = "(Y la escritura en la parte posterior: \"Bienvenido a <color=#FFB400>Wonderland</color>\"...)",
  ui_story_5033_50330101_117_dialog_content = "(Nunca he estado allí. Sería bueno echarle un vistazo en algún momento).",
  ui_story_5033_50330101_118_dialog_content = "(Después de todo, la terapia de compras moderada mejora el estado de ánimo).",
  ui_story_5033_50330101_119_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5033_50330101_120_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5033_50330101_121_dialog_content = "Mi postal!!!",
  ui_story_5033_50330101_122_dialog_content = "Cielos... ¿Adónde fue?",
  ui_story_5033_50330101_123_dialog_content = "¡Deténganse ahí, ustedes dos!",
  ui_story_5033_50330101_124_dialog_content = "Huff... Huff...",
  ui_story_5033_50330101_125_dialog_content = "...",
  ui_story_5033_50330101_126_dialog_content = "(Qué hombre tan extraño. ¿Es este tipo de apariencia la última moda en Umbraton?)",
  ui_story_5033_50330101_127_dialog_content = "(Espera, ¿por qué se ve familiar?)",
  ui_story_5033_50330101_128_dialog_content = "No tengo idea de por qué nos detuviste...",
  ui_story_5033_50330101_129_dialog_content = "Pero gracias de todos modos, PlayerName.",
  ui_story_5033_50330101_130_dialog_content = "Bueno, ya que el hombre está atrapado...",
  ui_story_5033_50330101_131_dialog_content = "Puedo tomarlo desde aquí.",
  ui_story_5033_50330101_132_dialog_content = "¡¿Corax?! ¿Por qué estás vestido así?",
  ui_story_5033_50330101_133_dialog_content = "¡Por favor, señor, se lo ruego, no tengo nada que ver con eso!",
  ui_story_5033_50330101_134_dialog_content = "A menos que me des algo que valga la pena...",
  ui_story_5033_50330101_135_dialog_content = "Te llevaré directamente al Señor de las Sombras.",
  ui_story_5033_50330101_136_dialog_content = "¡Pero yo no sé nada!",
  ui_story_5033_50330101_137_dialog_content = "¿En serio?",
  ui_story_5033_50330101_138_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5033_50330101_139_dialog_content = "¡No, no lo hagas! Está bien, hablaré, ¡solo guarda eso!",
  ui_story_5033_50330101_140_dialog_content = "Hice negocios con ellos seguro, ¡pero no maté a nadie!",
  ui_story_5033_50330101_141_dialog_content = "¡Todos comenzaron haciendo negocios turbios y usaron su dinero para explotar la parte más vulnerable criminal de Umbraton!",
  ui_story_5033_50330101_142_dialog_content = "Esas son todas noticias viejas. ¿Algo más?",
  ui_story_5033_50330101_143_dialog_content = "Y-Y...",
  ui_story_5033_50330101_144_dialog_content = "¡Antes de morir, todos visitaron <color=#FFB400>Euphoria</color>!",
  ui_story_5033_50330101_145_dialog_content = "¡Supuestamente, el <color=#FFB400>Grim Reaper</color> aparece allí!",
  ui_story_5033_50330101_146_dialog_content = "¿Parca?",
  ui_story_5033_50330101_147_dialog_content = "E-Así es... Cualquiera que no obedezca a Grim Reaper...",
  ui_story_5033_50330101_148_dialog_content = "¡Les arrebata la vida unos días después!",
  ui_story_5033_50330101_149_dialog_content = "¡Deben haber muerto a causa del Grim Reaper, de quien no se hablará!",
  ui_story_5033_50330101_150_dialog_content = "Pero Euphoria no es ya...",
  ui_story_5033_50330101_151_dialog_content = "Será mejor que estés diciendo la verdad.",
  ui_story_5033_50330101_152_dialog_content = "¡Lo soy, lo juro!",
  ui_story_5033_50330101_153_dialog_content = "...",
  ui_story_5033_50330101_154_option_content = "¡Potencia de fuerza!",
  ui_story_5033_50330101_155_dialog_content = "Está diciendo la verdad, Corax.",
  ui_story_5033_50330101_156_dialog_content = "No siento nada más que estrés y miedo.",
  ui_story_5033_50330101_157_dialog_content = "Gracias por la gran ayuda, PlayerName.",
  ui_story_5033_50330101_158_dialog_content = "¡¿Q-Qué estás haciendo ahora?!",
  ui_story_5033_50330101_159_dialog_content = "Me gustaría que fueras a Euphoria conmigo.",
  ui_story_5033_50330101_160_dialog_content = "¡¿En este momento?!",
  ui_story_5033_50330101_161_dialog_content = "Estoy bajo la orden del Señor de las Sombras de ir allí e investigar los asesinatos en serie en Umbraton.",
  ui_story_5033_50330101_162_dialog_content = "Te explicaré el resto en el camino.",
  ui_story_5033_50330101_163_dialog_content = "Para evitar que tu Colossus llame innecesariamente la atención, tomaremos una aeronave.",
  ui_story_5033_50330101_164_dialog_content = "Te veré en el Shuttle Hub mañana por la mañana.",
  ui_story_5033_50330101_165_dialog_content = "Quiero decir, claro, quería ver Euphoria, pero...",
  ui_story_5033_50330101_166_dialog_content = "Bueno, entonces, nos vemos mañana.",
  ui_story_5033_50330101_167_dialog_content = "¡Espera, déjame terminar!",
  ui_story_5033_50330101_168_dialog_content = "Al menos podrías dejarme pensar en ello...",
  ui_story_5033_50330201_1_dialog_content = "<color=#e8d9bb>Centro de transporte</color>",
  ui_story_5033_50330201_2_dialog_content = "(Bueno, aquí estoy. Incluso llegué antes de lo prometido...)",
  ui_story_5033_50330201_3_dialog_content = "(Rara vez vengo aquí ya que viajo por Soroz).",
  ui_story_5033_50330201_4_dialog_content = "(Ojalá pudiera enviarle una postal a Eraveil... Ojalá no hubiera perdido la que tenía ayer).",
  ui_story_5033_50330201_5_dialog_content = "Mi postal... Uf...",
  ui_story_5033_50330201_6_dialog_content = "Perdóname por escuchar tu lamento.",
  ui_story_5033_50330201_7_dialog_content = "Si es una postal lo que te molesta,",
  ui_story_5033_50330201_8_dialog_content = "Resulta que tengo uno sobre mí. Aquí tomaló.",
  ui_story_5033_50330201_9_dialog_content = "¡Vaya, de ninguna manera! ¡Es la misma imagen, incluso!",
  ui_story_5033_50330201_10_dialog_content = "No puedo tomar esto. Ni siquiera te conozco...",
  ui_story_5033_50330201_11_dialog_content = "Te conviene más. Tómalo, y puedo llamarlo mi buena acción del día.",
  ui_story_5033_50330201_12_dialog_content = "De verdad, quédatelo. Ya no lo necesito.",
  ui_story_5033_50330201_13_dialog_content = "tu no?",
  ui_story_5033_50330201_14_dialog_content = "Sí, porque voy a volver.",
  ui_story_5033_50330201_15_dialog_content = "Han pasado catorce años desde la última vez que estuve en Euphoria.",
  ui_story_5033_50330201_16_dialog_content = "Lo siento por divagar.",
  ui_story_5033_50330201_17_dialog_content = "Es genial, todavía estoy esperando a que alguien aparezca. Entonces, ¿cómo debo llamarte?",
  ui_story_5033_50330201_18_dialog_content = "...",
  ui_story_5033_50330201_19_dialog_content = "Ana está bien.",
  ui_story_5033_50330201_20_dialog_content = "estoy PlayerName. Esta sería mi primera vez en Euphoria.",
  ui_story_5033_50330201_21_dialog_content = "Suenas como si lo supieras bien. ¿Te importaría contarme un poco al respecto?",
  ui_story_5033_50330201_22_dialog_content = "Noté que la postal se llamaba \"<color=#FFB400>Wonderland</color>\".",
  ui_story_5033_50330201_23_dialog_content = "Eso es correcto. Para los forasteros en ese entonces, sin duda podría considerarse una especie de país de las maravillas.",
  ui_story_5033_50330201_24_dialog_content = "Vinieron en busca de la felicidad que no podían encontrar en ningún otro lugar.",
  ui_story_5033_50330201_25_dialog_content = "Sin embargo, lo más atractivo no fue el ambiente acogedor o el paisaje",
  ui_story_5033_50330201_26_dialog_content = "sino más bien, el próspero <color=#FFB400>mercado negro</color> dentro de las sombras de sus edificios únicos.",
  ui_story_5033_50330201_27_dialog_content = "¡¿Mercado negro?!",
  ui_story_5033_50330201_28_dialog_content = "¿Umbraton no tiene uno también? ¿Por qué ir a Euforia?",
  ui_story_5033_50330201_29_dialog_content = "Comenzó bastante similar a Umbraton, pero Euphoria era legalmente propiedad privada.",
  ui_story_5033_50330201_30_dialog_content = "Como probablemente puedas adivinar, cruzar los límites para obtener ganancias y deseos personales era común allí.",
  ui_story_5033_50330201_31_dialog_content = "Grandes casinos, fabricantes privados de armas... Todo lo que puedas imaginar estaba ahí.",
  ui_story_5033_50330201_32_dialog_content = "Eso suena aún más liberal que Umbraton.",
  ui_story_5033_50330201_33_dialog_content = "Gracias por la cartilla. Estoy deseando que llegue la visita.",
  ui_story_5033_50330201_34_dialog_content = "Pero me temo que solo te decepcionarás si vas a Euphoria con ideas preconcebidas.",
  ui_story_5033_50330201_35_dialog_content = "¿Qué quieres decir?",
  ui_story_5033_50330201_36_dialog_content = "Algún tiempo después de que me fui, Euphoria de repente desapareció.",
  ui_story_5033_50330201_37_dialog_content = "Ni siquiera he oído a nadie mencionar el nombre desde entonces.",
  ui_story_5033_50330201_38_dialog_content = "Como si el pueblo hubiera sido olvidado a propósito.",
  ui_story_5033_50330201_39_dialog_content = "Un pueblo olvidado, eh...",
  ui_story_5033_50330201_40_dialog_content = "¡PlayerName!",
  ui_story_5033_50330201_41_dialog_content = "Perdón por la espera.",
  ui_story_5033_50330201_42_dialog_content = "Está bien. He estado hablando con esta monja que también va a Euphoria.",
  ui_story_5033_50330201_43_dialog_content = "Ana, habla Corax. Él está viajando conmigo.",
  ui_story_5033_50330201_44_dialog_content = "El dirigible está a punto de despegar. Deberíamos abordar ahora.",
  ui_story_5033_50330201_45_dialog_content = "Es raro encontrar un vuelo a Euphoria, así que no lo perdamos.",
  ui_story_5033_50330201_46_dialog_content = "E-Está bien...",
  ui_story_5033_50330201_47_dialog_content = "<color=#e8d9bb>En la aeronave</color>",
  ui_story_5033_50330201_48_dialog_content = "De todos modos, oficialmente tomé el caso del Señor de las Sombras hace un mes.",
  ui_story_5033_50330201_49_dialog_content = "Umbraton ha visto crímenes violentos últimamente dirigidos a varios lugares de comercio clandestino, así como a aquellos involucrados en el comercio.",
  ui_story_5033_50330201_50_dialog_content = "Los acontecimientos están perjudicando a la economía.",
  ui_story_5033_50330201_51_dialog_content = "Tiene que ser una investigación encubierta por varias razones.",
  ui_story_5033_50330201_52_dialog_content = "Por el testimonio de ese hombre ayer, solo tengo que ir allí.",
  ui_story_5033_50330201_53_dialog_content = "¿Estás diciendo que todas las pistas apuntan a Euphoria?",
  ui_story_5033_50330201_54_dialog_content = "Oh, hablando del <color=#FFB400>asesinato de la monja</color> que comenzó todo, tenemos a alguien antes que nosotros que podría ayudar.",
  ui_story_5033_50330201_55_dialog_content = "...",
  ui_story_5033_50330201_56_dialog_content = "No hay problema, puedo cooperar.",
  ui_story_5033_50330201_57_dialog_content = "Relájese, solo quiero hacerle algunas preguntas sencillas.",
  ui_story_5033_50330201_58_dialog_content = "¿Conoces a una monja llamada <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330201_59_dialog_content = "Yo sé de ella, sí.",
  ui_story_5033_50330201_60_dialog_content = "Pero todo lo que sé es que la transfirieron de Euphoria a Umbraton. Hizo ella...?",
  ui_story_5033_50330201_61_dialog_content = "Ella fue una de las primeras víctimas.",
  ui_story_5033_50330201_62_dialog_content = "... Que descanse en paz.",
  ui_story_5033_50330201_63_dialog_content = "Tal vez ese sea el destino de nosotras las monjas.",
  ui_story_5033_50330201_64_dialog_content = "Supongo que no podría escapar ni siquiera dejando Euphoria.",
  ui_story_5033_50330201_65_dialog_content = "No intento ser grosero, pero no pareces particularmente sorprendido.",
  ui_story_5033_50330201_66_dialog_content = "Las monjas ya no tienen cabida en Euphoria.",
  ui_story_5033_50330201_67_dialog_content = "Si te pillan solo en la calle y no tienes suficiente dinero,",
  ui_story_5033_50330201_68_dialog_content = "incluso cómo mueres depende del destino para decidir.",
  ui_story_5033_50330201_69_dialog_content = "Suena como un lugar tranquilo...",
  ui_story_5033_50330201_70_dialog_content = "Sin embargo, estás montando un dirigible a Euphoria como nosotros.",
  ui_story_5033_50330201_71_dialog_content = "Traté de alejarme de todo yéndome.",
  ui_story_5033_50330201_72_dialog_content = "Pero hay algo que me llama ahora.",
  ui_story_5033_50330201_73_dialog_content = "... ¿Sabes qué? No tengo nada que ocultar. Voy a volver a <color=#FFB400>ver a un amigo</color>.",
  ui_story_5033_50330201_74_dialog_content = "Supongo que no iremos por el mismo camino.",
  ui_story_5033_50330201_75_dialog_content = "Creo que ya casi llegamos, a juzgar por el paisaje de abajo.",
  ui_story_5033_50330201_76_dialog_content = "<color=#e8d9bb>Una calle en Euforia</color>",
  ui_story_5033_50330201_77_dialog_content = "Supongo que aquí es donde nos despedimos.",
  ui_story_5033_50330201_78_dialog_content = "Buena suerte con tu caso.",
  ui_story_5033_50330201_79_dialog_content = "Gracias. Cuídate tú también.",
  ui_story_5033_50330201_80_dialog_content = "(Se fue a toda prisa. Tampoco parecía tan preocupada por su seguridad...)",
  ui_story_5033_50330201_81_dialog_content = "<color=#e8d9bb>Graznido, graznido—</color>",
  ui_story_5033_50330201_82_dialog_content = "Está desolado aquí, tal como dijo Anne.",
  ui_story_5033_50330201_83_dialog_content = "Los edificios están en mal estado o vandalizados, y no hay una persona a la vista...",
  ui_story_5033_50330201_84_dialog_content = "Supongo que este llamado País de las Maravillas no es más que un pueblo abandonado después de todo.",
  ui_story_5033_50330201_85_dialog_content = "Así que también has oído hablar del apodo de Euphoria, ¿eh?",
  ui_story_5033_50330201_86_dialog_content = "No te decepciones. Recibí información útil de Taki antes de irme.",
  ui_story_5033_50330201_87_dialog_content = "Bueno, entonces, pongamos este espectáculo en marcha...",
  ui_story_5033_50330201_88_dialog_content = "¿Mmm?",
  ui_story_5033_50330201_89_dialog_content = "¿Qué pasa?",
  ui_story_5033_50330201_90_dialog_content = "Siento algo raro en el aire...",
  ui_story_5033_50330201_91_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330201_92_dialog_content = "<size=45>Grah!!!</size>",
  ui_story_5033_50330201_93_dialog_content = "Tal como dice el informe, los cielos perpetuos nublados y la densa niebla del área lo convierten en un patio de recreo natural para los Eclipsites...",
  ui_story_5033_50330201_94_dialog_content = "Sea cual sea el tipo de Eclipsites que sean, ¡tendremos que luchar contra ellos!",
  ui_story_5033_50330201_95_dialog_content = "¡Hoja de hielo!",
  ui_story_5033_50330202_1_dialog_content = "<size=45>¡¡Hoja de hielo!!</size>",
  ui_story_5033_50330202_2_dialog_content = "alejate de ahi, PlayerName!",
  ui_story_5033_50330202_3_dialog_content = "<size=45>¡Graaah!</size>",
  ui_story_5033_50330202_4_dialog_content = "(¡Ya he pasado por este mismo escenario un millón de veces!)",
  ui_story_5033_50330202_5_dialog_content = "(Hay una garra gigante de Eclipsite sobre mi cabeza).",
  ui_story_5033_50330202_6_dialog_content = "(Si no me agacho, mi cabeza se abrirá en dos en un segundo).",
  ui_story_5033_50330202_7_dialog_content = "¡¡Mantente alejado!!",
  ui_story_5033_50330202_8_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5033_50330202_9_dialog_content = "...",
  ui_story_5033_50330202_10_dialog_content = "¿Eso es un hacha? ¿Están realmente luchando contra los eclipses con hachas?",
  ui_story_5033_50330202_11_dialog_content = "<color=#e8d9bb>*Corte de hacha*</color>",
  ui_story_5033_50330202_12_dialog_content = "<color=#e8d9bb>*Hacha balanceándose y cortando*</color>",
  ui_story_5033_50330202_13_dialog_content = "Parecen oscilaciones fortuitas, pero de todos modos golpean los órganos vitales.",
  ui_story_5033_50330202_14_dialog_content = "Obviamente, estos muchachos saben cómo lidiar con los eclipses.",
  ui_story_5033_50330202_15_dialog_content = "Estás bien, PlayerName? No pareces herido.",
  ui_story_5033_50330202_16_dialog_content = "Estoy bien, solo un poco asustado.",
  ui_story_5033_50330202_17_dialog_content = "¿Son Euforianos locales?",
  ui_story_5033_50330202_18_dialog_content = "Ten cuidado con cómo los despellejas. La piel del cofre tiene que ser de una sola pieza.",
  ui_story_5033_50330202_19_dialog_content = "Saca las uñas, corta los cuernos. Ah, y los ojos también...",
  ui_story_5033_50330202_20_dialog_content = "¡Ay!",
  ui_story_5033_50330202_21_dialog_content = "¡Te dije que tuvieras cuidado, bastardo! ¡Dame ese cuchillo!",
  ui_story_5033_50330202_22_dialog_content = "El ojo está arruinado. Ponlo en la pila de chatarra y quémalo.",
  ui_story_5033_50330202_23_dialog_content = "¿Están diseccionando el Eclipsite? ¿Qué quieren con todo eso?",
  ui_story_5033_50330202_24_dialog_content = "...",
  ui_story_5033_50330202_25_dialog_content = "Hora de irse, PlayerName.",
  ui_story_5033_50330202_26_dialog_content = "¿Ahora? Pero me salvaron, ¿no debería agradecerles?",
  ui_story_5033_50330202_27_dialog_content = "Escucha cuidadosamente.",
  ui_story_5033_50330202_28_dialog_content = "Mire de cerca lo que están haciendo.",
  ui_story_5033_50330202_29_dialog_content = "No estaban tratando de salvarte. Para empezar, su enfoque no estaba en ti.",
  ui_story_5033_50330202_30_dialog_content = "La piel y los órganos de Eclipsite, eso es lo que buscan. Probablemente para vender a precios muy bajos: uno por 200, dos por 300.",
  ui_story_5033_50330202_31_dialog_content = "Probablemente hayan estado siguiendo a los Eclipsites por un tiempo. Sólo éramos transeúntes colaterales.",
  ui_story_5033_50330202_32_dialog_content = "Euphoria, ciudad olvidada como es, claramente se rige por un conjunto de reglas completamente diferente.",
  ui_story_5033_50330202_33_dialog_content = "<size=33>Si no vamos ahora, este lugar nos absorberá y nos tragará enteros.</size>",
  ui_story_5033_50330202_34_dialog_content = "Bueno. Entonces vamos-",
  ui_story_5033_50330202_35_dialog_content = "Espera, forasteros.",
  ui_story_5033_50330202_36_dialog_content = "No puedes ir y venir como quieras aquí.",
  ui_story_5033_50330202_37_dialog_content = "<size=45>¡No recordamos haberte dado permiso para irte!</size>",
  ui_story_5033_50330202_38_dialog_content = "<color=#e8d9bb>¡Clank!</color>",
  ui_story_5033_50330202_39_dialog_content = "No me digas que no conoces las reglas de Euphoria.",
  ui_story_5033_50330202_40_dialog_content = "Él acaba de abrir un agujero en el suelo...",
  ui_story_5033_50330202_41_dialog_content = "<size=33>Supongo que ya es demasiado tarde.</size>",
  ui_story_5033_50330202_42_dialog_content = "Se dice que Euphoria es un lugar hospitalario que hace que todos se sientan bienvenidos.",
  ui_story_5033_50330202_43_dialog_content = "Por supuesto, esta hospitalidad debe ser recíproca.",
  ui_story_5033_50330202_44_dialog_content = "Aquí tienes. Haz tu conteo.",
  ui_story_5033_50330202_45_dialog_content = "Ven aquí.",
  ui_story_5033_50330202_46_dialog_content = "¿Quién, yo?",
  ui_story_5033_50330202_47_dialog_content = "¿Quién más? <size=33>Cuenta esto allí atrás.</size>",
  ui_story_5033_50330202_48_dialog_content = "En cuanto a ti... Habla, ¿de dónde vienes?",
  ui_story_5033_50330202_49_dialog_content = "Estamos...",
  ui_story_5033_50330202_50_dialog_content = "(¿Por qué Corax solo me miró? Probablemente ahora no sea el momento de decir la verdad).",
  ui_story_5033_50330202_51_dialog_content = "(Pero este es un municipio de Umbraton, por lo que podríamos hacer que retrocedan si se enteran de que somos de allí).",
  ui_story_5033_50330202_52_dialog_content = "Somos de Eraveil, al norte de Lumopolis. Es un pequeño pueblo aislado del resto del mundo.",
  ui_story_5033_50330202_53_dialog_content = "¿Ah?",
  ui_story_5033_50330202_54_dialog_content = "Eraveil...",
  ui_story_5033_50330202_55_dialog_content = "¿A quién diablos estás tratando de engañar?",
  ui_story_5033_50330202_56_dialog_content = "Es verdad.",
  ui_story_5033_50330202_57_dialog_content = "(Seguro que lo está vendiendo con cara seria).",
  ui_story_5033_50330202_58_dialog_content = "(Probablemente también esté tratando de dar a entender que son súper incultos...)",
  ui_story_5033_50330202_59_dialog_content = "Eh, jefe, creo que Eraveil es un lugar real.",
  ui_story_5033_50330202_60_dialog_content = "Multa. Siguiente pregunta: ¿a qué te dedicas y por qué estás aquí?",
  ui_story_5033_50330202_61_dialog_content = "Estamos aquí por negocios, vendiendo chatarra, ya sabes cómo funciona. Solo tratando de sobrevivir.",
  ui_story_5033_50330202_62_dialog_content = "Entonces, ¿por qué no tienes nada contigo?",
  ui_story_5033_50330202_63_dialog_content = "Solo estamos explorando el lugar. Y trajimos ofrendas, ¿no?",
  ui_story_5033_50330202_64_dialog_content = "En cuanto a quiénes somos, él es mi conductor. Y yo, soy—",
  ui_story_5033_50330202_65_dialog_content = "<size=45>¡Terminé de contar!</size>",
  ui_story_5033_50330202_66_dialog_content = "¡Obtuve 1,235 en total! <size=33>Eso es mucho dinero, jefe. Estos dos son ricos.</size>",
  ui_story_5033_50330202_67_dialog_content = "Está bien.",
  ui_story_5033_50330202_68_dialog_content = "Ya que hemos dado nuestra ofrenda, creo que podemos cancelar esta pequeña ceremonia de bienvenida.",
  ui_story_5033_50330202_69_dialog_content = "Estaremos en nuestro camino ahora. No hay necesidad de acompañarnos.",
  ui_story_5033_50330202_70_dialog_content = "Tosiste el dinero, pero no lo suficiente.",
  ui_story_5033_50330202_71_dialog_content = "¿Qué quieres decir?",
  ui_story_5033_50330202_72_dialog_content = "El precio acaba de subir.",
  ui_story_5033_50330202_73_dialog_content = "¿Cuánto cuesta?",
  ui_story_5033_50330202_74_dialog_content = "20.000.",
  ui_story_5033_50330202_75_dialog_content = "¿Y eso servirá?",
  ui_story_5033_50330202_76_dialog_content = "Veámoslo primero.",
  ui_story_5033_50330202_77_dialog_content = "¡Nos están robando, Corax! No nos dejarán ir aunque les demos todo nuestro dinero.",
  ui_story_5033_50330202_78_dialog_content = "Relax.",
  ui_story_5033_50330202_79_dialog_content = "Tengo 20.000 en mí. Incluso puedes pedir más, pero tendrás que venir a buscarlo tú mismo.",
  ui_story_5033_50330202_80_dialog_content = "Solo somos dos y una docena de ustedes. No hay razón para que tengas miedo.",
  ui_story_5033_50330202_81_dialog_content = "<color=#e8d9bb>¡Chasquido!</color>",
  ui_story_5033_50330202_82_dialog_content = "<size=45>¡Uf!</size>",
  ui_story_5033_50330202_83_dialog_content = "¡¡¡¡Jefe!!!!",
  ui_story_5033_50330202_84_dialog_content = "¿Tienes un maldito deseo de muerte?",
  ui_story_5033_50330202_85_dialog_content = "(¡Pero su brazo estaba roto!)",
  ui_story_5033_50330202_86_dialog_content = "(Colgaba como un fideo húmedo.)",
  ui_story_5033_50330202_87_dialog_content = "(Sin embargo, se regeneró en un segundo).",
  ui_story_5033_50330202_88_dialog_content = "Deja de gritar tan fuerte. Tu brazo está bien.",
  ui_story_5033_50330202_89_dialog_content = "Ver por ti mismo.",
  ui_story_5033_50330202_90_dialog_content = "¡Pero estaba roto, y lo sentí!",
  ui_story_5033_50330202_91_dialog_content = "T-tú—",
  ui_story_5033_50330202_92_dialog_content = "Guarda el dinero. Son exactamente 20.000. ¿No querías saber a qué me gano la vida?",
  ui_story_5033_50330202_93_dialog_content = "Soy doctor.",
  ui_story_5033_50330202_94_dialog_content = "Puedo curarte, y también puedo destrozar cada hueso de tu cuerpo.",
  ui_story_5033_50330202_95_dialog_content = "No solo tú, sino también todos los que están detrás de ti.",
  ui_story_5033_50330202_96_dialog_content = "...",
  ui_story_5033_50330202_97_dialog_content = "Entonces, ¿somos libres de irnos ahora?",
  ui_story_5033_50330202_98_dialog_content = "¡Solo espera! ¡Te arrepentirás de esto!",
  ui_story_5033_50330301_1_dialog_content = "(Finalmente nos deshicimos de ellos...)",
  ui_story_5033_50330301_2_dialog_content = "¿Por qué perdiste tanto tiempo con ellos, Corax?",
  ui_story_5033_50330301_3_dialog_content = "Podrías haber dejado caer el nombre de Istvan.",
  ui_story_5033_50330301_4_dialog_content = "Pueden parecer malvados, pero son solo un grupo de rufianes callejeros.",
  ui_story_5033_50330301_5_dialog_content = "De ninguna manera desafiarían al Señor de las Sombras de Umbraton.",
  ui_story_5033_50330301_6_dialog_content = "Esa habría sido la salida más fácil, pero habría habido repercusiones.",
  ui_story_5033_50330301_7_dialog_content = "Umbraton es poderoso, pero Shadowlord prefiere mantener las cosas discretas.",
  ui_story_5033_50330301_8_dialog_content = "Mencionarlo habría sido visto como una provocación.",
  ui_story_5033_50330301_9_dialog_content = "¿Es por eso que me estabas señalando antes?",
  ui_story_5033_50330301_10_dialog_content = "Sí. Pero es por nuestra propia seguridad, así como por la privacidad del Señor de las Sombras.",
  ui_story_5033_50330301_11_dialog_content = "... ¿En realidad es tan serio?",
  ui_story_5033_50330301_12_dialog_content = "Muchos Euforianos odian a Umbraton. \"Muchos\" es un eufemismo, realmente.",
  ui_story_5033_50330301_13_dialog_content = "Los dos no han llevado a cabo ningún negocio adecuado entre sí durante años.",
  ui_story_5033_50330301_14_dialog_content = "<color=#FFB400>Hace doce años</color>, el Darkover arrasó Umbraton y todas las regiones circundantes.",
  ui_story_5033_50330301_15_dialog_content = "Pueblos de todos los tamaños cayeron, lo que obligó a Umbraton a someterse a una reestructuración.",
  ui_story_5033_50330301_16_dialog_content = "Había caos por todas partes, y Euphoria fue uno de los pueblos más golpeados.",
  ui_story_5033_50330301_17_dialog_content = "Los Eclipsites que venció Umbraton se abrieron camino hacia Euphoria.",
  ui_story_5033_50330301_18_dialog_content = "Pero el Señor de las Sombras no tenía fuerzas en ese entonces, por lo que no podía ayudar a nadie.",
  ui_story_5033_50330301_19_dialog_content = "Después de que la guerra terminó, la teoría de la conspiración \"Umbraton usó Darkover para arruinar Euphoria\" comenzó a circular.",
  ui_story_5033_50330301_20_dialog_content = "Pero pensé que Anne dijo que Euphoria era de propiedad privada.",
  ui_story_5033_50330301_21_dialog_content = "¿El dueño lo abandonó?",
  ui_story_5033_50330301_22_dialog_content = "Eso era cierto, pero se convirtió en tierra de nadie después de la invasión de Eclipsite.",
  ui_story_5033_50330301_23_dialog_content = "Los sobrevivientes se unieron y formaron muchas <color=#FFB400>pequeñas cooperativas</color>.",
  ui_story_5033_50330301_24_dialog_content = "Algunas de las instalaciones de suministro pudieron recuperarse después de reparaciones básicas.",
  ui_story_5033_50330301_25_dialog_content = "Una vez que la población circundante comenzó a crecer, ciertos lugares volvieron a funcionar.",
  ui_story_5033_50330301_26_dialog_content = "Las cooperativas también se convirtieron gradualmente en <color=#FFB400>pandillas</color>.",
  ui_story_5033_50330301_27_dialog_content = "Euphoria seguro pasó por cambios drásticos...",
  ui_story_5033_50330301_28_dialog_content = "Entonces, este paisaje que tenemos ante nosotros es el resultado de una ciudad atrapada en estasis después de una guerra.",
  ui_story_5033_50330301_29_dialog_content = "Las calles pueden estar vacías ahora, pero definitivamente hay ojos en las sombras observándonos.",
  ui_story_5033_50330301_30_dialog_content = "Está bien, tenemos que movernos y tratar de pasar desapercibidos.",
  ui_story_5033_50330301_31_dialog_content = "Antes de irme, Taki me dio dos opciones y contactó a sus contactos para ambas.",
  ui_story_5033_50330301_32_dialog_content = "La opción A es hacerle una visita a <color=#FFB400>Gustav</color> en Euphoria's Odd Jobs.",
  ui_story_5033_50330301_33_dialog_content = "La opción B es encontrar a <color=#FFB400>Nekoyashiki</color>, un Odd Jobs itinerante.",
  ui_story_5033_50330301_34_dialog_content = "Eso suena como una elección entre algo \"oficial\" y algo \"informal\".",
  ui_story_5033_50330301_35_dialog_content = "¿Qué opinas, nombre del jugador?",
  ui_story_5033_50330301_36_option_content = "Gustav de Odd Jobs en Euphoria.",
  ui_story_5033_50330301_37_dialog_content = "Un Odd Jobs local de buena reputación, como Taki, tendría información más confiable.",
  ui_story_5033_50330301_38_dialog_content = "Además, un Odd Jobs oficial tendría más conexiones, por lo tanto, más clientes potenciales.",
  ui_story_5033_50330301_39_dialog_content = "Eso tiene sentido, pero...",
  ui_story_5033_50330301_40_dialog_content = "Estaremos expuestos una vez que vayamos allí.",
  ui_story_5033_50330301_41_dialog_content = "Todas las demás pandillas con conexiones allí se enterarán de nosotros.",
  ui_story_5033_50330301_42_dialog_content = "Eso suena bastante peligroso...",
  ui_story_5033_50330301_43_option_content = "Nekoyashiki, los Odd Jobs itinerantes.",
  ui_story_5033_50330301_44_dialog_content = "Suena enigmático y nadie se dará cuenta si tratamos de encontrarlo.",
  ui_story_5033_50330301_45_dialog_content = "Y un Odd Jobs itinerante podría tener información privada.",
  ui_story_5033_50330301_46_dialog_content = "Estás en lo correcto.",
  ui_story_5033_50330301_47_dialog_content = "Los contactos como ese son en realidad más seguros.",
  ui_story_5033_50330301_48_dialog_content = "Vayamos a buscar a este Nekoyashiki, entonces.",
  ui_story_5033_50330301_49_dialog_content = "¿Es confiable sin embargo?",
  ui_story_5033_50330301_50_dialog_content = "No es una cuestión de fiabilidad, sino de honradez, con Odd Jobs.",
  ui_story_5033_50330301_51_dialog_content = "¿Porque solo nosotros podemos determinar qué es digno de confianza?",
  ui_story_5033_50330301_52_dialog_content = "Muy inteligente.",
  ui_story_5033_50330301_53_dialog_content = "Para Gustav, Nekoyashiki es solo un pequeño alevín.",
  ui_story_5033_50330301_54_dialog_content = "Si terminas yendo con él, será difícil localizarlo.",
  ui_story_5033_50330301_55_dialog_content = "Su paradero es impredecible, pero deja símbolos, generalmente en algún lugar de un edificio en el que se encuentra...",
  ui_story_5033_50330301_56_dialog_content = "Eso es lo que Taki me dijo. En cuanto al símbolo...",
  ui_story_5033_50330301_57_dialog_content = "¿Es un <color=#FFB400>graffiti con forma de cicatriz</color>?",
  ui_story_5033_50330301_58_dialog_content = "Cómo lo sabes, PlayerName?",
  ui_story_5033_50330301_59_dialog_content = "Acabo de ver uno. Mira, está en el letrero de ese restaurante.",
  ui_story_5033_50330301_60_dialog_content = "Como si nos hiciera señas para que viniéramos.",
  ui_story_5033_50330301_61_dialog_content = "Sabía que nada se les escapaba a estos vendedores ambulantes de inteligencia.",
  ui_story_5033_50330301_62_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_5033_50330301_63_dialog_content = "¿Alguien dentro?",
  ui_story_5033_50330301_64_dialog_content = "Está tan tranquilo aquí. ¿Este restaurante está abandonado?",
  ui_story_5033_50330301_65_dialog_content = "... ¡No!",
  ui_story_5033_50330301_66_dialog_content = "¡Agáchate, Corax!",
  ui_story_5033_50330301_67_dialog_content = "<color=#e8d9bb>Whoosh... ¡Bang!</color>",
  ui_story_5033_50330301_68_dialog_content = "Maldita sea, los extrañé.",
  ui_story_5033_50330301_69_dialog_content = "Fuera del camino. ¡Mi turno!",
  ui_story_5033_50330301_70_dialog_content = "<color=#e8d9bb>Whoosh... ¡Bang!</color>",
  ui_story_5033_50330301_71_dialog_content = "¡¿Tú otra vez?! ¡Venimos en paz!",
  ui_story_5033_50330301_72_dialog_content = "Fuimos lentos en el sorteo la última vez.",
  ui_story_5033_50330301_73_dialog_content = "Molestaste a la gente equivocada cuando le rompiste el brazo al jefe.",
  ui_story_5033_50330301_74_dialog_content = "<size=33>¿No estamos en el lugar correcto?</size>",
  ui_story_5033_50330301_75_dialog_content = "<size=33>De ninguna manera, la información de Taki nunca se equivoca.</size>",
  ui_story_5033_50330301_76_dialog_content = "<size=33>Probablemente hay más en esta situación de lo que pensamos.</size>",
  ui_story_5033_50330301_77_dialog_content = "No importa. Vamos, tenemos que defendernos.",
  ui_story_5033_50330301_78_dialog_content = "¿Ah?",
  ui_story_5033_50330301_79_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5033_50330301_80_dialog_content = "¿Te atreves a contraatacar?",
  ui_story_5033_50330301_81_dialog_content = "Graah...",
  ui_story_5033_50330301_82_dialog_content = "Eclipsites, encima de la pandilla? Que desastre.",
  ui_story_5033_50330301_83_dialog_content = "¡Deberíamos deshacernos de los eclipses primero!",
  ui_story_5033_50330302_1_dialog_content = "Graah...",
  ui_story_5033_50330302_2_dialog_content = "Hay demasiados de ellos. Tenemos que hacer un descanso para ello, PlayerName!",
  ui_story_5033_50330302_3_dialog_content = "¡¿A donde?!",
  ui_story_5033_50330302_4_dialog_content = "¡Vamos a salir de aquí primero!",
  ui_story_5033_50330302_5_dialog_content = "¡Se están escapando, jefe!",
  ui_story_5033_50330302_6_dialog_content = "¡Consíguelos!",
  ui_story_5033_50330302_7_dialog_content = "<color=#e8d9bb>Un callejón en Euphoria</color>",
  ui_story_5033_50330302_8_dialog_content = "Resoplan...",
  ui_story_5033_50330302_9_dialog_content = "(No tengo idea de dónde estoy ahora...)",
  ui_story_5033_50330302_10_dialog_content = "Grah!!!",
  ui_story_5033_50330302_11_dialog_content = "(¡Y tengo Eclipsites en mi cola!)",
  ui_story_5033_50330302_12_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5033_50330302_13_dialog_content = "Oh...",
  ui_story_5033_50330302_14_dialog_content = "Maldiciones... ¡Atrás!",
  ui_story_5033_50330302_15_dialog_content = "Oye, ¿cómo es que los Eclipsites fueron tras ellos?",
  ui_story_5033_50330302_16_dialog_content = "<size=45><color=#e8d9bb>¡Grito!</color></size>",
  ui_story_5033_50330302_17_dialog_content = "¡¿Quién está ahí?!",
  ui_story_5033_50330302_18_dialog_content = "(Ese fue un sonido raro...)",
  ui_story_5033_50330302_19_dialog_content = "Grah...",
  ui_story_5033_50330302_20_dialog_content = "(¡Los eclipses también se han ido!)",
  ui_story_5033_50330302_21_dialog_content = "Me fui por un tiempo, pero los matones se apoderaron de mi base...",
  ui_story_5033_50330302_22_dialog_content = "Anda y dame las gracias. Cuento el rescate como tu primera petición.",
  ui_story_5033_50330302_23_dialog_content = "Sr. <color=#FFB400>Nekoyashiki</color>, ¿supongo?",
  ui_story_5033_50330302_24_dialog_content = "Si no fuera por Taki, no estaría tratando con ustedes y sus elegantes formalidades.",
  ui_story_5033_50330302_25_dialog_content = "Sólo llámame Nekoyashiki.",
  ui_story_5033_50330302_26_dialog_content = "¿Que paso ahi? ¿Qué fue ese chillido?",
  ui_story_5033_50330302_27_dialog_content = "Por supervivencia. No sé por qué, pero gritar de la manera correcta los ahuyenta.",
  ui_story_5033_50330302_28_dialog_content = "No soy bueno con las armas, pero al menos puedo defenderme con algunos gritos contra los Eclipsites.",
  ui_story_5033_50330302_29_dialog_content = "En un apuro, incluso puedo usarlos de la forma en que lo acabo de hacer.",
  ui_story_5033_50330302_30_dialog_content = "Entonces, ¿confían en mí ahora, amigos de Taki?",
  ui_story_5033_50330302_31_dialog_content = "Eso fue impresionante. Supongo que eso es algo privado solo para ti.",
  ui_story_5033_50330302_32_dialog_content = "Par para el curso. Ahora dime lo que quieres saber.",
  ui_story_5033_50330302_33_dialog_content = "Soy Corax, y esto es PlayerName. Estamos aquí para investigar una reciente cadena de asesinatos en serie en Umbraton.",
  ui_story_5033_50330302_34_dialog_content = "Sé muy poco sobre el asesino en este momento, excepto por cierto modus operandi.",
  ui_story_5033_50330302_35_dialog_content = "¿Te importaría dar más detalles?",
  ui_story_5033_50330302_36_dialog_content = "Específicamente, cada víctima murió de una laceración extraña.",
  ui_story_5033_50330302_37_dialog_content = "Un pequeño corte que no debería ser fatal. Las víctimas tropezaban como un zombi antes de morir repentinamente.",
  ui_story_5033_50330302_38_dialog_content = "(Lo descubrieron, exactamente como <color=#FFB400>ella</color> predijo).",
  ui_story_5033_50330302_39_dialog_content = "Hmm, esa es una forma difícil de hacerlo.",
  ui_story_5033_50330302_40_dialog_content = "Parece que no eres de los que no deben ser estimados, si pudiste rastrear tu camino hasta aquí solo con eso.",
  ui_story_5033_50330302_41_dialog_content = "Solo <color=#FFB400>ella</color> conocería la historia asociada con esa técnica en toda Euphoria.",
  ui_story_5033_50330302_42_dialog_content = "¡¿?!",
  ui_story_5033_50330302_43_dialog_content = "Por favor elabora.",
  ui_story_5033_50330302_44_dialog_content = "Te llevaré a ver <color=#FFB400>Raven's Blood</color>. Ellos saben más que yo.",
  ui_story_5033_50330302_45_dialog_content = "<color=#e8d9bb>Graznido, graznido...</color>",
  ui_story_5033_50330302_46_dialog_content = "Veo que los cuervos ya están aquí.",
  ui_story_5033_50330302_47_dialog_content = "Eso significa que les dan la bienvenida a ustedes dos, visitantes de Umbraton.",
  ui_story_5033_50330302_48_dialog_content = "<color=#e8d9bb>En otro callejón no hace mucho</color>",
  ui_story_5033_50330302_49_dialog_content = "(¡Oh no, un callejón sin salida!)",
  ui_story_5033_50330302_50_dialog_content = "<color=#e8d9bb>Plop, plop, plop...</color>",
  ui_story_5033_50330302_51_dialog_content = "(¡¿Pólux y Casta me siguieron?!)",
  ui_story_5033_50330302_52_dialog_content = "(¡No quiero morir aquí!)",
  ui_story_5033_50330302_53_dialog_content = "Insistes en buscar problemas, así que ahora los problemas han venido a buscarte.",
  ui_story_5033_50330302_54_dialog_content = "P-Pero no he hecho nada más que mendigar dinero a los dos visitantes...",
  ui_story_5033_50330302_55_dialog_content = "¿Qué negocio tiene Raven's Blood con ellos?",
  ui_story_5033_50330302_56_dialog_content = "¡No creas que puedes arrastrarte hasta la cima solo porque los traficantes sospechosos han estado cayendo como moscas!",
  ui_story_5033_50330302_57_dialog_content = "¡La euforia nunca se someterá a ustedes dos locas!",
  ui_story_5033_50330302_58_dialog_content = "¿Es eso lo que piensas?",
  ui_story_5033_50330302_59_dialog_content = "¡No te acerques más! ¡Tengo un cuchillo!",
  ui_story_5033_50330302_60_dialog_content = "¡Dije que no te acerques más!",
  ui_story_5033_50330302_61_dialog_content = "¡Nngh, mi cuchillo! ¡¿Q-Qué crees que estás haciendo?!",
  ui_story_5033_50330302_62_dialog_content = "Una daga no es suficiente para protegerse. Es más peligroso de lo que nunca serás.",
  ui_story_5033_50330302_63_dialog_content = "Prueba un arma más adecuada para ti la próxima vez.",
  ui_story_5033_50330302_64_dialog_content = "No entiendo lo que quieres decir en absoluto.",
  ui_story_5033_50330302_65_dialog_content = "Acabo de salvarte de todos esos eclipses. ¿Aún no entiendes la situación en la que te encuentras?",
  ui_story_5033_50330302_66_dialog_content = "¿Eres demasiado denso para darte cuenta?",
  ui_story_5033_50330302_67_dialog_content = "Los ingratos no viven mucho en Euphoria.",
  ui_story_5033_50330302_68_dialog_content = "¡Puaj! ¡Mantén ese cuchillo lejos de mí! Está bien, hablaré, ¡te diré todo lo que sé!",
  ui_story_5033_50330302_69_dialog_content = "Te engañaron para que vinieras aquí sin siquiera saber cómo sostener una daga.",
  ui_story_5033_50330302_70_dialog_content = "Te daré una pequeña idea de lo poco que tu jefe se preocupa por tu vida.",
  ui_story_5033_50330302_71_dialog_content = "Si uso tu cuello como apoyo depende de cuán cooperativo seas.",
  ui_story_5033_50330302_72_dialog_content = "¡Dije que hablaré!",
  ui_story_5033_50330302_73_dialog_content = "Muchos lugareños como yo se reunieron para tender una emboscada en la ciudad.",
  ui_story_5033_50330302_74_dialog_content = "¿Tener una emboscada?",
  ui_story_5033_50330302_75_dialog_content = "Sí, el jefe no pensó que era hora de hacer un movimiento todavía.",
  ui_story_5033_50330302_76_dialog_content = "Quería que nos infiltráramos en la pandilla y nos mezcláramos con ellos en los bares y mesas de juego.",
  ui_story_5033_50330302_77_dialog_content = "¿Es así?",
  ui_story_5033_50330302_78_dialog_content = "¿Nunca te preguntaste qué querían que hicieras a continuación?",
  ui_story_5033_50330302_79_dialog_content = "¡M-Mueve la hoja!",
  ui_story_5033_50330302_80_dialog_content = "Bien, escuché algo en la pandilla hace un par de días.",
  ui_story_5033_50330302_81_dialog_content = "Quien nos contrató quería que difundiésemos algunos <color=#FFB400>rumores</color> por la ciudad.",
  ui_story_5033_50330302_82_dialog_content = "¡Eso es todo lo que sé, lo juro! ¡Ni siquiera sé qué tipo de rumores!",
  ui_story_5033_50330302_83_dialog_content = "Comprendo.",
  ui_story_5033_50330302_84_dialog_content = "¿No me vas a dejar ir? ¡Te dije todo lo que sé!",
  ui_story_5033_50330302_85_dialog_content = "Déjame ofrecerte otra lección en la casa sobre cómo sobrevivir en Euphoria...",
  ui_story_5033_50330302_86_dialog_content = "No confíes en nadie aquí.",
  ui_story_5033_50330302_87_dialog_content = "¡Ah!",
  ui_story_5033_50330302_88_dialog_content = "Cada vez, los noqueas y los tiras a la basura.",
  ui_story_5033_50330302_89_dialog_content = "Si la gente descubriera que el estimado Pólux era realmente tan misericordioso...",
  ui_story_5033_50330302_90_dialog_content = "¿Cómo podían seguir creyendo en la reputación asociada con el nombre?",
  ui_story_5033_50330302_91_dialog_content = "No deberían. Es mejor no confiar en nadie en Euphoria. Especialmente yo.",
  ui_story_5033_50330302_92_dialog_content = "<color=#e8d9bb>Graznido, graznido...</color>",
  ui_story_5033_50330302_93_dialog_content = "Hmm, algo está pasando al final de Nekoyashiki.",
  ui_story_5033_50330302_94_dialog_content = "Sí, rastrearon a Nekoyashiki como anticipé.",
  ui_story_5033_50330302_95_dialog_content = "Aunque antes de lo que pensaba.",
  ui_story_5033_50330302_96_dialog_content = "Vayamos al <color=#FFB400>lugar de siempre</color> y esperemos a Nekoyashiki y los dos invitados de Umbraton de los que hablamos.",
  ui_story_5033_50330302_97_dialog_content = "Esto no es propio de ti en absoluto, Pólux. Una vez más, ¿por qué nos reunimos con ellos?",
  ui_story_5033_50330302_98_dialog_content = "Tengo un motivo oculto. Sé que el Señor de las Sombras los envió.",
  ui_story_5033_50330302_99_dialog_content = "¿Se trata de los <color=#FFB400>niños</color>?",
  ui_story_5033_50330302_100_dialog_content = "Los niños, y Euphoria también, por supuesto.",
  ui_story_5033_50330302_101_dialog_content = "Estoy esperando que venga una tormenta y se lleve la suciedad.",
  ui_story_5033_50330302_102_dialog_content = "casta—",
  ui_story_5033_50330302_103_dialog_content = "¿Sí?",
  ui_story_5033_50330302_104_dialog_content = "¿Cuándo el cielo de Euphoria se convirtió en un perpetuo gris fangoso?",
  ui_story_5033_50330302_105_dialog_content = "Mm...",
  ui_story_5033_50330302_106_dialog_content = "¿Cuándo comenzó, me pregunto?",
  ui_story_5033_50330401_1_dialog_content = "El Raven's Blood que mencionaste... ¿Es una de las muchas pandillas de Euphoria?",
  ui_story_5033_50330401_2_dialog_content = "En realidad, tomaste la decisión correcta al buscar mi ayuda.",
  ui_story_5033_50330401_3_dialog_content = "Si hubieras acudido a otra persona, habrías tenido que saltar a través de aros para encontrar Raven's Blood.",
  ui_story_5033_50330401_4_dialog_content = "La pandilla está compuesta por solo dos mujeres: <color=#FFB400>Pollux</color> y <color=#FFB400>Casta</color>, pero siguen siendo rivales para las pandillas principales.",
  ui_story_5033_50330401_5_dialog_content = "Pollux no es de las luchas de poder entre bandas. Solo hay un puñado de personas capaces de encontrarlos.",
  ui_story_5033_50330401_6_dialog_content = "¿Es Pólux la \"ella\" que mencionaste?",
  ui_story_5033_50330401_7_dialog_content = "Sí.",
  ui_story_5033_50330401_8_dialog_content = "Ella sabía de tu llegada a Euphoria y estaba esperando que vinieras a mí.",
  ui_story_5033_50330401_9_dialog_content = "Más oídos en el suelo es esencial para sobrevivir aquí, ¿verdad?",
  ui_story_5033_50330401_10_dialog_content = "Ja, no me vas a encontrar discutiendo en contra de eso, especialmente con visitantes de tanto prestigio.",
  ui_story_5033_50330401_11_dialog_content = "De todos modos, ella me dijo que los trajera a ustedes yo mismo. Al \"lugar habitual\", como ella lo expresó.",
  ui_story_5033_50330401_12_dialog_content = "Con suerte, ella será útil en mi investigación.",
  ui_story_5033_50330401_13_dialog_content = "¿Estás sospechando de ella?",
  ui_story_5033_50330401_14_dialog_content = "Relájate, no voy a arrestar a nadie sin una causa.",
  ui_story_5033_50330401_15_dialog_content = "Incluso si tengo un sospechoso en mente, aún querría pruebas concretas antes de arrestar a alguien.",
  ui_story_5033_50330401_16_dialog_content = "¿Por qué? ¿Qué estás esperando, otra víctima para ser cortada?",
  ui_story_5033_50330401_17_dialog_content = "Nunca desearía que más personas inocentes fueran víctimas.",
  ui_story_5033_50330401_18_dialog_content = "Este es un asunto muy serio, Sr. Nekoyashiki. Espero que puedas tratarlo con algo de respeto.",
  ui_story_5033_50330401_19_dialog_content = "Dios mío, tienes un palo en el culo, ¿no es así? Simplemente encuentro absurda tu sospecha.",
  ui_story_5033_50330401_20_dialog_content = "Eso no suena muy convincente viniendo de mí ya que soy amigo de ellos, ¿eh?",
  ui_story_5033_50330401_21_dialog_content = "De todos modos, te llevaré a donde te están esperando primero.",
  ui_story_5033_50330401_22_dialog_content = "Entonces puedes decidir por ti mismo.",
  ui_story_5033_50330401_23_dialog_content = "(Suena muy seguro de su inocencia...)",
  ui_story_5033_50330401_24_dialog_content = "Entonces, ¿dónde está ese lugar del que has estado hablando?",
  ui_story_5033_50330401_25_dialog_content = "Ah, ya casi llegamos.",
  ui_story_5033_50330401_26_dialog_content = "Vamos a una <color=#FFB400>antigua iglesia</color>. Solía ser un espectáculo para la vista, antes de que fuera abandonado.",
  ui_story_5033_50330401_27_dialog_content = "(¿Una iglesia?)",
  ui_story_5033_50330401_28_dialog_content = "Las monjas ya no tienen cabida en Euphoria.",
  ui_story_5033_50330401_29_dialog_content = "(Todas las monjas se han ido, pero la iglesia todavía está aquí, ¿eh?)",
  ui_story_5033_50330401_30_dialog_content = "<color=#e8d9bb>Euphoria: La Iglesia Vieja</color>",
  ui_story_5033_50330401_31_dialog_content = "Está tan deteriorado como todos los demás edificios.",
  ui_story_5033_50330401_32_dialog_content = "Y como todos los demás edificios, solo sirve como refugio.",
  ui_story_5033_50330401_33_dialog_content = "Euphoria nunca ha tenido un salvador, y aquí ya nadie reza al dios de la luz.",
  ui_story_5033_50330401_34_dialog_content = "La ciudad ha sido purgada de monjas en los últimos años. Esta iglesia ya no pertenece a ninguna denominación.",
  ui_story_5033_50330401_35_dialog_content = "¿Las monjas fueron purgadas? ¿Por quién?",
  ui_story_5033_50330401_36_dialog_content = "Si lo supiera, no habría vivido lo suficiente para estar aquí hoy.",
  ui_story_5033_50330401_37_dialog_content = "Tal vez era sólo su destino. No se negocia con la Muerte.",
  ui_story_5033_50330401_38_dialog_content = "¡El omnipresente Grim Reaper les arrebata la vida unos días después!",
  ui_story_5033_50330401_39_dialog_content = "¡Deben haber muerto a causa del Grim Reaper, de quien no se hablará!",
  ui_story_5033_50330401_40_dialog_content = "(Esto suena como lo que dijo ese hombre...)",
  ui_story_5033_50330401_41_dialog_content = "(Los asesinatos en serie, las monjas masacradas... ¿Podría ser todo obra de Grim Reaper?)",
  ui_story_5033_50330401_42_dialog_content = "Hablando de eso, nos encontramos con una monja de camino aquí.",
  ui_story_5033_50330401_43_dialog_content = "Nos separamos después de llegar. Me pregunto cómo estará ella ahora.",
  ui_story_5033_50330401_44_dialog_content = "¿Qué? ¡¿Es eso cierto?!",
  ui_story_5033_50330401_45_dialog_content = "Sí, vino con nosotros desde Umbraton. Ella era muy obviamente una monja.",
  ui_story_5033_50330401_46_dialog_content = "(¿Una monja de Umbraton?)",
  ui_story_5033_50330401_47_dialog_content = "Deberías avisar a Raven's Blood cuando te encuentres con ellos. Estoy seguro de que estarán felices de escucharlo.",
  ui_story_5033_50330401_48_dialog_content = "<color=#e8d9bb>Mientras tanto, en otro callejón</color>",
  ui_story_5033_50330401_49_dialog_content = "¿...?",
  ui_story_5033_50330401_50_dialog_content = "¿Qué pasa, Pólux?",
  ui_story_5033_50330401_51_dialog_content = "No me digas que esos punks todavía están por aquí.",
  ui_story_5033_50330401_52_dialog_content = "No, no son ellos.",
  ui_story_5033_50330401_53_dialog_content = "Pero eso es lo único de lo que estoy seguro. El rastro va y viene, que está más allá de ellos.",
  ui_story_5033_50330401_54_dialog_content = "Nadie en Euphoria puede hacer eso.",
  ui_story_5033_50330401_55_dialog_content = "Relax. Podría ser solo un gato.",
  ui_story_5033_50330401_56_dialog_content = "Vamos. Los niños están esperando y Nekoyashiki debería aparecer pronto.",
  ui_story_5033_50330401_57_dialog_content = "Sigue adelante. Quiero volver a ese distrito comercial.",
  ui_story_5033_50330401_58_dialog_content = "Realmente no creo que esos punks valgan la pena.",
  ui_story_5033_50330401_59_dialog_content = "¿Quién se preocupa por ellos?",
  ui_story_5033_50330401_60_dialog_content = "Solo quiero llevarles algunas sorpresas a los niños.",
  ui_story_5033_50330401_61_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330401_62_dialog_content = "...",
  ui_story_5033_50330401_63_dialog_content = "(¿Ella... sintió mi presencia?)",
  ui_story_5033_50330401_64_dialog_content = "<color=#e8d9bb>Miau...</color>",
  ui_story_5033_50330401_65_dialog_content = "¡Miau!",
  ui_story_5033_50330401_66_dialog_content = "Mata a Pólux.",
  ui_story_5033_50330401_67_dialog_content = "...",
  ui_story_5033_50330401_68_dialog_content = "(... La paciencia es una virtud olvidada, al parecer.)",
  ui_story_5033_50330401_69_dialog_content = "<color=#e8d9bb>*Rompe el papel*</color>",
  ui_story_5033_50330401_70_dialog_content = "¿Eh?",
  ui_story_5033_50330401_71_dialog_content = "<size=45>¡Grah!</size>",
  ui_story_5033_50330401_72_dialog_content = "(Tiempo perfecto.)",
  ui_story_5033_50330401_73_dialog_content = "(Te destruiré junto con este pedazo de basura.)",
  ui_story_5033_50330502_1_dialog_content = "<color=#e8d9bb>Pandilla de Istvan en Umbratón</color>",
  ui_story_5033_50330502_2_dialog_content = "<color=#e8d9bb>*Retumbar*</color>",
  ui_story_5033_50330502_3_dialog_content = "Parece que se acerca una tormenta.",
  ui_story_5033_50330502_4_dialog_content = "Un montón de nubes, lo que significa que la sombra se extenderá por todo Umbraton.",
  ui_story_5033_50330502_5_dialog_content = "Solo es cuestión de tiempo antes de que llegue también a Euphoria.",
  ui_story_5033_50330502_6_dialog_content = "¿Le preocupa la investigación de Corax?",
  ui_story_5033_50330502_7_dialog_content = "No.",
  ui_story_5033_50330502_8_dialog_content = "Estoy esperando a que cambie el tiempo.",
  ui_story_5033_50330502_9_dialog_content = "En los últimos días, obtuve una nueva perspectiva sobre el caso de Corax.",
  ui_story_5033_50330502_10_dialog_content = "Pero todavía no tengo una prueba definitiva, así que es solo una especulación personal.",
  ui_story_5033_50330502_11_dialog_content = "No hay problema. Vamos a oírlo.",
  ui_story_5033_50330502_12_dialog_content = "Solo me di cuenta mientras escaneaba periódicos viejos.",
  ui_story_5033_50330502_13_dialog_content = "Hace catorce años, sucedió algo en Euphoria que causó un gran revuelo en Umbraton.",
  ui_story_5033_50330502_14_dialog_content = "En ese momento, el lugar era más conocido como \"Wonderland\".",
  ui_story_5033_50330502_15_dialog_content = "Probablemente sepas sobre el incidente mejor que yo.",
  ui_story_5033_50330502_16_dialog_content = "Hmm, recuerdo el <color=#FFB400>incidente de Gemini</color>...",
  ui_story_5033_50330502_17_dialog_content = "Sí. Fue entonces cuando la lucha clandestina estaba de moda en Euphoria y enriqueció a mucha gente.",
  ui_story_5033_50330502_18_dialog_content = "Incluso el capitán de los mercenarios en Euphoria dejó de depender de las comisiones por dinero.",
  ui_story_5033_50330502_19_dialog_content = "Eso no es nada inusual. De todos modos, las únicas comisiones que les quedaban probablemente eran pelear en esas arenas subterráneas.",
  ui_story_5033_50330502_20_dialog_content = "Que ironía.",
  ui_story_5033_50330502_21_dialog_content = "De todos modos, alguien estaba moviendo los hilos detrás de escena y, bajo sus órdenes, el capitán entrenó a dos estrellas prometedoras.",
  ui_story_5033_50330502_22_dialog_content = "Eran dos niñas muy jóvenes entrenadas bajo dos regímenes completamente diferentes por el capitán...",
  ui_story_5033_50330502_23_dialog_content = "Uno se sometió a un entrenamiento interno de mercenarios y se especializó en su estilo de lucha.",
  ui_story_5033_50330502_24_dialog_content = "El otro se unió a otros mercenarios en el campo en combate real, entrenando su adaptabilidad para todas las situaciones.",
  ui_story_5033_50330502_25_dialog_content = "Euphoria los llamó los gemelos Géminis del grupo mercenario.",
  ui_story_5033_50330502_26_dialog_content = "Sin embargo, el primer concierto oficial que obtuvieron...",
  ui_story_5033_50330502_27_dialog_content = "Fue una <color=#FFB400>lucha a muerte</color> entre sí en una arena.",
  ui_story_5033_50330502_28_dialog_content = "Déjame adivinar. No hubo demostración de histeria emocional en absoluto y uno mató al otro a quemarropa, ¿verdad?",
  ui_story_5033_50330502_29_dialog_content = "Sí.",
  ui_story_5033_50330502_30_dialog_content = "No hay informes sobre cómo se desarrolló la pelea, pero según los chismes de los testigos presenciales...",
  ui_story_5033_50330502_31_dialog_content = "La niña que sobrevivió resultó gravemente herida con pequeñas laceraciones en todo el cuerpo. Estaba prácticamente muerta.",
  ui_story_5033_50330502_32_dialog_content = "Después de ese incidente, ella desapareció por completo, para no ser vista nunca más.",
  ui_story_5033_50330502_33_dialog_content = "De todos modos, el público perdió interés en ella en el caos que golpeó a Umbraton unos años después.",
  ui_story_5033_50330502_34_dialog_content = "Crees que la chica que murió en realidad <color=#FFB400>aún vive</color>.",
  ui_story_5033_50330502_35_dialog_content = "Sí.",
  ui_story_5033_50330502_36_dialog_content = "Eso es demasiado simple, ¿no? No tengo dudas de que no pudo haber sobrevivido, solo que...",
  ui_story_5033_50330502_37_dialog_content = "No podemos estar seguros de que ella sea la única que conoce esa técnica.",
  ui_story_5033_50330502_38_dialog_content = "Después de todo, Euphoria ya no es el lugar que solía ser.",
  ui_story_5033_50330502_39_dialog_content = "Antes de la Crisis de Darkover, esa compañía de mercenarios contaba con algunos miembros que podían ejercer esas habilidades, y les enseñaron a otros...",
  ui_story_5033_50330502_40_dialog_content = "Son muchos sospechosos potenciales.",
  ui_story_5033_50330502_41_dialog_content = "Tienes razón, por lo que esto es solo una especulación.",
  ui_story_5033_50330502_42_dialog_content = "Sin embargo, digamos que hubo un sobreviviente de ese desafortunado combate a muerte, y que ha vivido de forma anónima hasta ahora.",
  ui_story_5033_50330502_43_dialog_content = "No sería bueno ni para Umbraton ni para Euphoria.",
  ui_story_5033_50330502_44_dialog_content = "¿Sabes qué es lo más difícil para un participante habitual en la lucha clandestina?",
  ui_story_5033_50330502_45_dialog_content = "No es supervivencia, ¿verdad? Dado que la vida y la muerte son parte del curso allí.",
  ui_story_5033_50330502_46_dialog_content = "Está cortando rápidamente los tejidos podridos de tu cuerpo.",
  ui_story_5033_50330502_47_dialog_content = "¿Algo tan simple?",
  ui_story_5033_50330502_48_dialog_content = "Porque el tejido viejo impide que se forme tejido sano.",
  ui_story_5033_50330502_49_dialog_content = "Con el tiempo, arruina tu físico y te roba el privilegio de competir.",
  ui_story_5033_50330502_50_dialog_content = "Eso sería un trabajo para un médico, ¿verdad?",
  ui_story_5033_50330502_51_dialog_content = "Haría que el médico en el que más confiaba lo manejara.",
  ui_story_5033_50330502_52_dialog_content = "Pero, de nuevo, ¿no sobrevivió supuestamente la otra chica?",
  ui_story_5033_50330502_53_dialog_content = "Como mínimo, esto prueba que no todos los que están sujetos a esa técnica de espada mueren.",
  ui_story_5033_50330502_54_dialog_content = "<color=#e8d9bb>Toc, toc, toc—</color>",
  ui_story_5033_50330502_55_dialog_content = "¿Tío István? La víctima que encontró Corax... Ahora está despierto.",
  ui_story_5033_50330502_56_dialog_content = "Ah, habla del diablo.",
  ui_story_5033_50330601_1_dialog_content = "Adelante.",
  ui_story_5033_50330601_2_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_5033_50330601_3_dialog_content = "¡Mirad, todos! ¡Nekoyashiki ha vuelto!",
  ui_story_5033_50330601_4_dialog_content = "Cállate. No tan fuerte, Latan. Busco a Casta, la has visto?",
  ui_story_5033_50330601_5_dialog_content = "Casta salió a buscar el pan. ¿Quieres que vaya a buscarla?",
  ui_story_5033_50330601_6_dialog_content = "Dile que tenemos invitados de Umbraton.",
  ui_story_5033_50330601_7_dialog_content = "¡De acuerdo! ¡Puedes jugar con los demás mientras voy a buscarla!",
  ui_story_5033_50330601_8_dialog_content = "¿Nos trajiste alguna golosina, Nekoyashiki?",
  ui_story_5033_50330601_9_dialog_content = "Por supuesto.",
  ui_story_5033_50330601_10_dialog_content = "¡Ven aquí, Nekoyashiki! ¡Agáchate, encontré algo lindo para ti!",
  ui_story_5033_50330601_11_dialog_content = "H-Oye, no me jalees así, chico...",
  ui_story_5033_50330601_12_dialog_content = "Wow... ¿Por qué hay tantos niños aquí?",
  ui_story_5033_50330601_13_dialog_content = "Raven's Blood se llevó a todos estos niños y... ¡Ay! Oye, ¿por qué me tiras del pelo?",
  ui_story_5033_50330601_14_dialog_content = "¡Jejeje! ¡Mira, encontré esta cucaracha el otro día! No fue fácil de atrapar... ¿Te gusta?",
  ui_story_5033_50330601_15_dialog_content = "¡Pequeño bribón, ven aquí!",
  ui_story_5033_50330601_16_dialog_content = "¡Oh no, Nekoyashiki está loco! ¡¡Huir!!",
  ui_story_5033_50330601_17_dialog_content = "Parece que no tiene tiempo para explicarme las cosas en este momento.",
  ui_story_5033_50330601_18_dialog_content = "No hay mucho que explicar.",
  ui_story_5033_50330601_19_dialog_content = "La mayoría de estos niños terminaron aquí después de ser abandonados en las calles.",
  ui_story_5033_50330601_20_dialog_content = "Algunos quedaron huérfanos después de que sus padres fueran asesinados por la violencia de las pandillas, y otros fueron rescatados de la clandestinidad criminal.",
  ui_story_5033_50330601_21_dialog_content = "Hasta que se encuentre un hogar seguro y adecuado para ellos, estos niños están bajo la protección de Raven's Blood. Esos somos nosotros.",
  ui_story_5033_50330601_22_dialog_content = "Debes ser la Casta que mencionó Nekoyashiki.",
  ui_story_5033_50330601_23_dialog_content = "Fueron-",
  ui_story_5033_50330601_24_dialog_content = "No hay necesidad de presentaciones; Sabemos exactamente por qué está aquí y qué está investigando. Esperemos a que Pollux regrese antes de hablar.",
  ui_story_5033_50330601_25_dialog_content = "Todavía necesito alimentar a estos sinvergüenzas.",
  ui_story_5033_50330601_26_dialog_content = "Está bien. No nos importa esperar.",
  ui_story_5033_50330601_27_dialog_content = "¡Muy bien, todos! Es casi la hora de la siesta, ¡así que termina de comer tu pan y vete directo a la cama!",
  ui_story_5033_50330601_28_dialog_content = "¡De acuerdo!",
  ui_story_5033_50330601_29_dialog_content = "*Haciendo una mueca* Finalmente soltaron mi cabello... Estos niños son otra cosa.",
  ui_story_5033_50330601_30_dialog_content = "Si ha terminado, continuemos nuestra conversación.",
  ui_story_5033_50330601_31_dialog_content = "Como soy el miembro de Odd Jobs, pondré a todos al tanto de la situación.",
  ui_story_5033_50330601_32_dialog_content = "Con respecto a nuestros dos invitados aquí, entiendo que Taki te señaló en mi dirección.",
  ui_story_5033_50330601_33_dialog_content = "Sin embargo, Raven's Blood sabe mucho más sobre Euphoria y puede ayudarte mucho más que yo.",
  ui_story_5033_50330601_34_dialog_content = "En cuanto a las damas de Raven's Blood, les he traído a las personas que pidieron, así que ahora les dejaré el resto a ustedes.",
  ui_story_5033_50330601_35_dialog_content = "Me iré ahora, ya que todavía tengo otros asuntos que atender.",
  ui_story_5033_50330601_36_dialog_content = "Sólo vete, no vengas a molestarnos con tu molesta presencia. Te llamaremos si te necesitamos.",
  ui_story_5033_50330601_37_dialog_content = "Uy, eso duele. ¿Dejarme a un lado una vez que termines de usarme?",
  ui_story_5033_50330601_38_dialog_content = "Tú eres el que dijo que te ibas, así que vete ya. Todavía tengo pan para servir.",
  ui_story_5033_50330601_39_dialog_content = "¡Déjame ayudarte, Casta!",
  ui_story_5033_50330601_40_dialog_content = "¡Yo también puedo ayudar! ¡Yo también puedo ayudar!",
  ui_story_5033_50330601_41_dialog_content = "Bien entonces. Latan, puedes repartir este pan entre los niños más pequeños. Schewe, puedes repartir la mantequilla y asegurarte de que los pequeños reciban más.",
  ui_story_5033_50330601_42_dialog_content = "¡Entendido!",
  ui_story_5033_50330601_43_dialog_content = "Claro, sé dónde está la mantequilla. ¡Iré a buscarlo!",
  ui_story_5033_50330601_44_dialog_content = "Lo siento, pero tengo que preguntar... ¿Cómo se lastimaron los niños?",
  ui_story_5033_50330601_45_dialog_content = "¿Creías que los huérfanos sin hogar lo tendrían fácil en las calles de Euphoria?",
  ui_story_5033_50330601_46_dialog_content = "Fueron heridos por otras personas, así que les vendamos las heridas... Así de simple.",
  ui_story_5033_50330601_47_dialog_content = "¿Te importaría si echo un vistazo a sus heridas? Fui médico una vez.",
  ui_story_5033_50330601_48_dialog_content = "Un médico, ¿eh?",
  ui_story_5033_50330601_49_dialog_content = "Puedo ver que sus heridas han sido vendadas con mucho cuidado y que los vendajes están bastante limpios.",
  ui_story_5033_50330601_50_dialog_content = "Pero algunos de los niños se ven un poco peor por el desgaste. Requerirán un poco de atención adicional.",
  ui_story_5033_50330601_51_dialog_content = "Je, debe ser nuestro día de suerte. Sin embargo, tendrás que esperar hasta que terminen de comer.",
  ui_story_5033_50330601_52_dialog_content = "(¿Hmm? ¿Alguien está tirando de mi mano?)",
  ui_story_5033_50330601_53_dialog_content = "¿Sí? ¿Pasa algo, niña?",
  ui_story_5033_50330601_54_dialog_content = "Um... N-Nekoyashiki dijo que dejó algunos dulces en tu bolsillo...",
  ui_story_5033_50330601_55_dialog_content = "A-Y que debería preguntarte si quiero un poco.",
  ui_story_5033_50330601_56_dialog_content = "¿Cuándo puso Nekoyashiki caramelos en mi bolsillo? ¿Por qué no me di cuenta de esto...?",
  ui_story_5033_50330601_57_dialog_content = "¿Eh? Mira eso. ¡Realmente hay dulces en mi bolsillo!",
  ui_story_5033_50330601_58_dialog_content = "E-entonces... ¿Puedo tener un poco?",
  ui_story_5033_50330601_59_dialog_content = "¡Por supuesto que puede! Aquí tienes. Lamento haberte hecho esperar.",
  ui_story_5033_50330601_60_dialog_content = "¡Gracias!",
  ui_story_5033_50330601_61_dialog_content = "¡Oye! ¡No comas tantos dulces justo antes de una comida!",
  ui_story_5033_50330601_62_dialog_content = "Ah, okey.",
  ui_story_5033_50330601_63_dialog_content = "<color=#e8d9bb>Gruñido...</color>",
  ui_story_5033_50330601_64_dialog_content = "¿Hambriento?",
  ui_story_5033_50330601_65_dialog_content = "L-Lo siento. Todo ese correteo me abrió el apetito. Desafortunadamente, no puedo hacer nada con el gruñido de mi estómago.",
  ui_story_5033_50330601_66_dialog_content = "Aunque te prometo que no estoy aquí para robarles el pan a los niños.",
  ui_story_5033_50330601_67_dialog_content = "Hah, ustedes dos son un dúo bastante interesante. Un médico convertido en asesino y un niño en el cuerpo de un adolescente.",
  ui_story_5033_50330601_68_dialog_content = "Después de todo, tal vez Pólux tenía razón al invitarte aquí.",
  ui_story_5033_50330601_69_dialog_content = "De acuerdo, siempre es más inteligente trabajar con la gente de Umbraton que contra ellos.",
  ui_story_5033_50330601_70_dialog_content = "Ese olor, ¡son croissants!",
  ui_story_5033_50330601_71_dialog_content = "Así es, y traje suficiente para todos, así que todos ustedes pueden comer hasta saciarse hoy.",
  ui_story_5033_50330601_72_dialog_content = "Ve a saludar a nuestros invitados, Pollux. Puedo entregarlos yo mismo. Muy bien, el que quiera un croissant, ¡venga conmigo!",
  ui_story_5033_50330601_73_dialog_content = "¡De acuerdo!",
  ui_story_5033_50330601_74_dialog_content = "Ustedes dos son más que bienvenidos a tener algo también.",
  ui_story_5033_50330601_75_dialog_content = "Gracias, nos ayudaremos a nosotros mismos entonces.",
  ui_story_5033_50330601_76_dialog_content = "Aquí, PlayerName.",
  ui_story_5033_50330601_77_dialog_content = "G-Gracias...",
  ui_story_5033_50330601_78_dialog_content = "Lo siento, se supone que debo ayudar, pero todo lo que hice fue complicar las cosas.",
  ui_story_5033_50330601_79_dialog_content = "No seas tan duro contigo mismo.",
  ui_story_5033_50330601_80_dialog_content = "Después de todo, hemos encontrado a alguien con quien podemos trabajar aquí en quien podemos confiar. Eso es mucho mejor de lo que esperaba.",
  ui_story_5033_50330601_81_dialog_content = "Mm. Alguien que administraría un refugio en Euphoria solo para niños...",
  ui_story_5033_50330601_82_dialog_content = "Apuesto a que no solo son súper fuertes. También deben ser muy amables.",
  ui_story_5033_50330601_83_dialog_content = "Nos halagas. Pero verdaderamente, cuidar de todos estos niños no es tarea fácil.",
  ui_story_5033_50330601_84_dialog_content = "¿No has considerado enviarlos a un lugar mejor?",
  ui_story_5033_50330601_85_dialog_content = "Umbraton tiene muchos orfanatos con todas las comodidades que puedan necesitar.",
  ui_story_5033_50330601_86_dialog_content = "Por supuesto que lo hemos pensado. Es la razón por la que hemos decidido trabajar con usted.",
  ui_story_5033_50330601_87_dialog_content = "Pero no todo el mundo es capaz de ver a los huérfanos de Euphoria como cualquier otro niño. Necesito encontrar un lugar dispuesto a aceptarlos.",
  ui_story_5033_50330601_88_dialog_content = "Comprendo.",
  ui_story_5033_50330601_89_dialog_content = "No todos los niños están dispuestos a dejar este lugar tampoco. Además de eso, Euphoria y Umbraton no han estado en los mejores términos últimamente...",
  ui_story_5033_50330601_90_dialog_content = "Me gustaría esperar hasta que las cosas se calmen antes de encontrar soluciones a más largo plazo.",
  ui_story_5033_50330601_91_dialog_content = "Entiendo. En cuanto a los niños, puedo garantizar que Umbraton los recibirá con los brazos abiertos.",
  ui_story_5033_50330601_92_dialog_content = "Y dado que estaremos investigando cosas por un tiempo, ¿tal vez podamos echar una mano aquí también?",
  ui_story_5033_50330601_93_dialog_content = "¡Correcto! Cuando llegue la monja, tal vez pueda ayudar con los niños.",
  ui_story_5033_50330601_94_dialog_content = "¿Monja? ¿Estás diciendo que la iglesia envió una monja a nuestra iglesia?",
  ui_story_5033_50330601_95_dialog_content = "Creo que sí. Mientras estábamos en el dirigible a Euphoria, nos encontramos con una monja que dijo que vendría aquí.",
  ui_story_5033_50330601_96_dialog_content = "Honestamente, pensé que ella estaría aquí ahora...",
  ui_story_5033_50330601_97_dialog_content = "Euphoria no ha visto a una monja en mucho tiempo. Tal vez simplemente no deseen venir.",
  ui_story_5033_50330601_98_dialog_content = "Pero esta iglesia sigue en pie. Incluso si es algo decrépito, no creo que eso los detenga de querer venir aquí.",
  ui_story_5033_50330601_99_dialog_content = "Sabes, fue una monja la que me dio mi nombre cuando me encontró vagando por las calles de Euphoria hace mucho tiempo.",
  ui_story_5033_50330601_100_dialog_content = "Pero después de que me fui de la iglesia, perdí el contacto con ella.",
  ui_story_5033_50330601_101_dialog_content = "Luego, hace unos ocho o nueve años, escuché que rescató a un grupo de niños del caos. Había ido a Umbraton con la esperanza de ahorrar más, solo para morir en un accidente en el camino.",
  ui_story_5033_50330601_102_dialog_content = "Como resultado, esta iglesia se deterioró e incluso sufrió vandalismo.",
  ui_story_5033_50330601_103_dialog_content = "Y ahí es cuando ustedes dos...",
  ui_story_5033_50330601_104_dialog_content = "Correcto. Fue entonces cuando Casta y yo fundamos Raven's Blood y decidimos arreglar este lugar para que pudiera albergar a niños errantes una vez más.",
  ui_story_5033_50330601_105_dialog_content = "Pero si la iglesia ha enviado a una nueva monja para que se haga cargo, entonces tal vez sea mucho mejor.",
  ui_story_5033_50330601_106_dialog_content = "\"Todo lo mejor\"? No puedes decir eso en serio, ¿verdad, Pólux?",
  ui_story_5033_50330601_107_dialog_content = "Pensé... Pensé que dirías que por nosotros, nadie jamás ocuparía el lugar de <color=#FFB400>la hermana Matilda</color>.",
  ui_story_5033_50330601_108_dialog_content = "Nadie la reemplaza, Casta.",
  ui_story_5033_50330601_109_dialog_content = "Parece que ustedes dos tienen un vínculo emocional muy fuerte con esta hermana Matilda.",
  ui_story_5033_50330601_110_dialog_content = "Yo mismo soy un huérfano eufórico. La hermana Matilda fue quien me acogió.",
  ui_story_5033_50330601_111_dialog_content = "Si no fuera por ella, no se sabe lo que las pandillas de aquí me habrían hecho. En cuanto a Pólux...",
  ui_story_5033_50330601_112_dialog_content = "Basta de recordar por un día, Casta. Es nuestro turno de escuchar al Sr. Corax y conocer su investigación.",
  ui_story_5033_50330601_113_dialog_content = "Ya sé la esencia de lo que está pasando, gracias a Nekoyashiki.",
  ui_story_5033_50330601_114_dialog_content = "Una serie de misteriosos asesinatos han tenido lugar en Umbraton y sospechas que el asesino está relacionado de alguna manera con Euphoria.",
  ui_story_5033_50330601_115_dialog_content = "Creo que ustedes dos estarán más que dispuestos a ayudarme una vez que escuchen más detalles sobre mi investigación.",
  ui_story_5033_50330601_116_dialog_content = "¿Porqué crees?",
  ui_story_5033_50330601_117_dialog_content = "Me duele decírtelo... Pero la hermana Matilda no murió en un accidente.",
  ui_story_5033_50330601_118_dialog_content = "Supimos por la iglesia local que las misteriosas heridas en su cuerpo eran exactamente las mismas que las de las otras víctimas en el caso.",
  ui_story_5033_50330601_119_dialog_content = "¡¿Qué?!",
  ui_story_5033_50330601_120_dialog_content = "<color=#e8d9bb>*Destrozar*</color>",
  ui_story_5033_50330601_121_dialog_content = "<size=45>¡¿Qué acabas de decir?! ¡Dilo de nuevo!</size>",
  ui_story_5033_50330601_122_dialog_content = "Cálmate, estás asustando a los niños.",
  ui_story_5033_50330601_123_dialog_content = "...",
  ui_story_5033_50330601_124_dialog_content = "E-Está bien todos, no tengan miedo... Casta se puso un poco nervioso, eso es todo.",
  ui_story_5033_50330601_125_dialog_content = "Disculpas, niños. Acabamos de recibir una noticia muy impactante.",
  ui_story_5033_50330601_126_dialog_content = "Nosotros, los adultos, vamos a salir para continuar nuestra conversación. Ven a buscarnos si necesitas algo, y asegúrate de comer toda tu comida, ¿de acuerdo?",
  ui_story_5033_50330601_127_dialog_content = "Bien...",
  ui_story_5033_50330601_128_dialog_content = "Los niños todavía se ven un poco conmocionados. Me quedaré y les haré compañía.",
  ui_story_5033_50330601_129_dialog_content = "Gracias, PlayerName.",
  ui_story_5033_50330601_130_dialog_content = "Vamos. Todavía tenemos <size=45>mucho de qué hablar</size>.",
  ui_story_5033_50330701_1_dialog_content = "Munch, munch, munch...",
  ui_story_5033_50330701_2_dialog_content = "...",
  ui_story_5033_50330701_3_dialog_content = "¿Por qué no comes, Latan?",
  ui_story_5033_50330701_4_dialog_content = "Sigues mirando hacia afuera. ¿Estás preocupado por ellos?",
  ui_story_5033_50330701_5_dialog_content = "Sí... Casi nunca vemos a Casta enfadarse tanto.",
  ui_story_5033_50330701_6_dialog_content = "O Pollux... A pesar de que se veía mucho más tranquila que Casta, me di cuenta de que estaba furiosa.",
  ui_story_5033_50330701_7_dialog_content = "Algo muy, muy malo debe haber sucedido.",
  ui_story_5033_50330701_8_dialog_content = "Te diste cuenta de todo eso por ti mismo, ¿eh?",
  ui_story_5033_50330701_9_dialog_content = "(Qué niña tan perspicaz es ella).",
  ui_story_5033_50330701_10_dialog_content = "Si, lo hice.",
  ui_story_5033_50330701_11_dialog_content = "Por lo general, no importa lo que suceda o qué tipo de noticias les traiga Nekoyashiki,",
  ui_story_5033_50330701_12_dialog_content = "nunca muestran signos de estar molestos. No delante de nosotros, al menos.",
  ui_story_5033_50330701_13_dialog_content = "Esa fue la primera vez que los vimos tan enojados, o los escuchamos gritar así.",
  ui_story_5033_50330701_14_dialog_content = "No te preocupes demasiado por eso, ¿de acuerdo? Una vez que averigüemos todo, estoy seguro de que ya no estarán enojados.",
  ui_story_5033_50330701_15_dialog_content = "¿Tiene... algo que ver con la hermana <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330701_16_dialog_content = "¿También escuchaste eso?",
  ui_story_5033_50330701_17_dialog_content = "Uh-huh, estuve escuchándolos todo el tiempo.",
  ui_story_5033_50330701_18_dialog_content = "Bueno, te puedo decir que sí, tiene algo que ver con la hermana Matilda.",
  ui_story_5033_50330701_19_dialog_content = "En cuanto al resto de los detalles, todavía tenemos mucho que investigar.",
  ui_story_5033_50330701_20_dialog_content = "Pero una vez que terminemos nuestro trabajo, estoy seguro de que Pollux y Casta compartirán el resto contigo.",
  ui_story_5033_50330701_21_dialog_content = "Ah, okey.",
  ui_story_5033_50330701_22_dialog_content = "¿Mmm?",
  ui_story_5033_50330701_23_dialog_content = "¿Pasa algo?",
  ui_story_5033_50330701_24_dialog_content = "Creí ver a alguien afuera hace un momento... Detrás de ti, por allá.",
  ui_story_5033_50330701_25_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_5033_50330701_26_dialog_content = "no veo a nadie",
  ui_story_5033_50330701_27_dialog_content = "Raro... ¿quizás me lo imaginé? Hubiera jurado que vi pasar a alguien...",
  ui_story_5033_50330701_28_dialog_content = "¿Quizás se están escondiendo? Intentaré sentir su presencia...",
  ui_story_5033_50330701_29_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5033_50330701_30_dialog_content = "Er... En pocas palabras, tengo un poder especial que me permite encontrar personas sin verlas. Es algo mío.",
  ui_story_5033_50330701_31_dialog_content = "Soy muy sensible a Lumina, así como a Darkflow.",
  ui_story_5033_50330701_32_dialog_content = "¡Eso suena genial!",
  ui_story_5033_50330701_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330701_34_dialog_content = "Puedo sentir a tres personas muy poderosas en ese corredor afuera. Deberían ser Corax, Casta y Pollux.",
  ui_story_5033_50330701_35_dialog_content = "También hay algunos Eclipsites deambulando por la zona, pero todavía están bastante lejos de la iglesia.",
  ui_story_5033_50330701_36_dialog_content = "Y más allá de eso... todo lo que siento es gente común.",
  ui_story_5033_50330701_37_dialog_content = "Oh... Tal vez solo estaba viendo cosas, después de todo.",
  ui_story_5033_50330701_38_dialog_content = "No, creo que solo estás un poco ansioso. Volvamos a la iglesia y esperemos a Pólux y los demás, ¿de acuerdo?",
  ui_story_5033_50330701_39_dialog_content = "No queremos que esos eclipses nos vean aquí.",
  ui_story_5033_50330701_40_dialog_content = "Está bien...",
  ui_story_5033_50330701_41_dialog_content = "Buena chica, anda y termina de comer.",
  ui_story_5033_50330701_42_dialog_content = "Espero que todo vaya bien por parte de Corax...",
  ui_story_5033_50330701_43_dialog_content = "Me asignaron este caso hace aproximadamente un mes.",
  ui_story_5033_50330701_44_dialog_content = "El Señor de las Sombras necesitaba que alguien examinara los cadáveres, y fue precisamente cuando descubrí signos del método preferido de matar del asesino.",
  ui_story_5033_50330701_45_dialog_content = "<color=#e8d9bb>Hace un mes...</color>",
  ui_story_5033_50330701_46_dialog_content = "¿Está diciendo que vio este tipo de heridas en un paciente que murió hace unos días?",
  ui_story_5033_50330701_47_dialog_content = "De hecho, y un paciente extraño, además. Su condición estaba lejos de ser crítica, pero murió de todos modos.",
  ui_story_5033_50330701_48_dialog_content = "Empiezo a pensar que no murió a causa de su enfermedad...",
  ui_story_5033_50330701_49_dialog_content = "Creo que un asesino en serie está detrás de estas muertes.",
  ui_story_5033_50330701_50_dialog_content = "¿Ha habido informes recientes de muertes extrañas como esta?",
  ui_story_5033_50330701_51_dialog_content = "Sí, pero sus cuerpos ya han sido enterrados... ¿A menos que necesites que los excave?",
  ui_story_5033_50330701_52_dialog_content = "Hago. Necesitamos reevaluar sus causas de muerte.",
  ui_story_5033_50330701_53_dialog_content = "Todos nuestros hallazgos también deben ser informados al Señor de las Sombras.",
  ui_story_5033_50330701_54_dialog_content = "Bien, pero no me gusta esto...",
  ui_story_5033_50330701_55_dialog_content = "¿Y qué hay de este chico? ¿Lo entierro?",
  ui_story_5033_50330701_56_dialog_content = "D-No seas tan apresurado. Todavía respira... Tal vez pueda salvarlo.",
  ui_story_5033_50330701_57_dialog_content = "Ah, haz lo que quieras.",
  ui_story_5033_50330701_58_dialog_content = "Hay extrañas cicatrices en los cuerpos de las víctimas.",
  ui_story_5033_50330701_59_dialog_content = "Además, el culpable ha repetido su crimen varias veces.",
  ui_story_5033_50330701_60_dialog_content = "Si no fuera por el reciente aumento de estos asesinatos casi idénticos, es posible que nunca hubiéramos descubierto que fue obra de un asesino en serie.",
  ui_story_5033_50330701_61_dialog_content = "Aunque hemos determinado un modus operandi, todavía tenemos que encontrar otras pistas útiles.",
  ui_story_5033_50330701_62_dialog_content = "Durante mi investigación, descubrí que el cuerpo de una persona que murió hace años en un supuesto accidente presentaba las mismas cicatrices que las víctimas del asesino en serie.",
  ui_story_5033_50330701_63_dialog_content = "Uno de los consejos que recibimos fue de una iglesia local. Nos dieron el expediente del accidente de sor Matilda.",
  ui_story_5033_50330701_64_dialog_content = "¿Cómo vinculaste al asesino con Euphoria? ¡¿Dónde está el bastardo?!",
  ui_story_5033_50330701_65_dialog_content = "Todavía no sabemos la identidad del asesino. En cuanto a cómo están conectados con Euphoria... Es solo especulación de nuestra parte.",
  ui_story_5033_50330701_66_dialog_content = "Los rumores dicen que Euphoria está obsesionada por un Grim Reaper.",
  ui_story_5033_50330701_67_dialog_content = "Un Grim Reaper que supuestamente solo aparece ante aquellos que se atreven a perturbar la paz en Euphoria o romper sus reglas.",
  ui_story_5033_50330701_68_dialog_content = "Aparece sin hacer ruido, quita la vida a sus víctimas sin dejar ni rastro de su presencia.",
  ui_story_5033_50330701_69_dialog_content = "¿De qué estás hablando exactamente?",
  ui_story_5033_50330701_70_dialog_content = "El asesino usa un arte de asesinato de alto nivel.",
  ui_story_5033_50330701_71_dialog_content = "Uno del que se rumorea que no deja rastros, ni siquiera una sola gota de sangre.",
  ui_story_5033_50330701_72_dialog_content = "No. Definitivamente deja algo atrás.",
  ui_story_5033_50330701_73_dialog_content = "Cicatrices. Por supuesto, solo parecen marcas de arañazos ordinarias.",
  ui_story_5033_50330701_74_dialog_content = "Pólux, ¿conoces esta técnica?",
  ui_story_5033_50330701_75_dialog_content = "Por supuesto que sí... porque <color=#FFB400>también puedo usarlo</color>.",
  ui_story_5033_50330701_76_dialog_content = "¡¿Qué?!",
  ui_story_5033_50330702_1_dialog_content = "Nos acabamos el pan hace mucho... ¿Por qué no ha vuelto Casta para decirnos que nos vayamos a la cama?",
  ui_story_5033_50330702_2_dialog_content = "Escuché a Casta decir que necesita ver al médico después de que termine de comer.",
  ui_story_5033_50330702_3_dialog_content = "¿Entonces ese tipo es médico?",
  ui_story_5033_50330702_4_dialog_content = "Sí, el bronceado es médico.",
  ui_story_5033_50330702_5_dialog_content = "Entonces, ¿cuándo volverán?",
  ui_story_5033_50330702_6_dialog_content = "Vamos a dormir por ahora.",
  ui_story_5033_50330702_7_dialog_content = "Estoy seguro de que volverán después de que nos despertemos.",
  ui_story_5033_50330702_8_dialog_content = "Latan tiene razón, todos. Es hora de la siesta, así que descansa un poco y todo estará arreglado para cuando te despiertes.",
  ui_story_5033_50330702_9_dialog_content = "Hmph... Parece que solo estás diciendo eso.",
  ui_story_5033_50330702_10_dialog_content = "¿Crees que somos un montón de niños de tres años?",
  ui_story_5033_50330702_11_dialog_content = "¡Ah! ¡T-Eres el chico de antes! El que trató de darle esa cucaracha a Nekoyashiki...",
  ui_story_5033_50330702_12_dialog_content = "Jeje, así es.",
  ui_story_5033_50330702_13_dialog_content = "Solo estás tratando de engañarnos para que tomemos nuestras siestas, ¿no es así? Bueno, ¡no lo vamos a comprar!",
  ui_story_5033_50330702_14_dialog_content = "¡Cuéntanos qué haces aquí y no te atrevas a mentir!",
  ui_story_5033_50330702_15_dialog_content = "(Dios... ¡Cuidar niños puede ser un verdadero fastidio!)",
  ui_story_5033_50330702_16_dialog_content = "Vinimos en busca de Raven's Blood... Bueno, más bien, fueron ellos quienes se acercaron a nosotros.",
  ui_story_5033_50330702_17_dialog_content = "Estamos investigando un crimen muy serio juntos.",
  ui_story_5033_50330702_18_dialog_content = "¿Qué tipo de crimen?",
  ui_story_5033_50330702_19_dialog_content = "Oh...",
  ui_story_5033_50330702_20_dialog_content = "(¡Tengo que pensar en una manera de asustarlos, para que no sigan preguntando por eso!)",
  ui_story_5033_50330702_21_dialog_content = "<anim type=Shake><size=45>¡Un caso de asesinato muy aterrador!</size></anim>",
  ui_story_5033_50330702_22_dialog_content = "...",
  ui_story_5033_50330702_23_dialog_content = "¿N-No les suena aterrador a ustedes?",
  ui_story_5033_50330702_24_dialog_content = "Somos de Euphoria... ¿De verdad crees que eso nos asusta?",
  ui_story_5033_50330702_25_dialog_content = "¿Qué? Quiero decir, debería... Lo siento, por un segundo lo olvidé.",
  ui_story_5033_50330702_26_dialog_content = "¡Jajaja! ¡Este tipo piensa que solo somos un grupo de niños y niñas normales! ¡Qué bicho raro!",
  ui_story_5033_50330702_27_dialog_content = "¡Sí! B-Además... Todo el mundo odia a los niños pequeños de Euphoria.",
  ui_story_5033_50330702_28_dialog_content = "¡No tiene nada de raro!",
  ui_story_5033_50330702_29_dialog_content = "No me importa quién eres o de dónde vienes. En mi opinión, ustedes son solo un grupo de niños normales.",
  ui_story_5033_50330702_30_dialog_content = "¡Todo lo que deberían pensar es en comer, dormir y divertirse! No te preocupes por ninguna de estas cosas aterradoras o peligrosas.",
  ui_story_5033_50330702_31_dialog_content = "Pollux y los demás los resolverán.",
  ui_story_5033_50330702_32_dialog_content = "PlayerName tiene un punto... además Pollux y Casta también nos dijeron lo mismo.",
  ui_story_5033_50330702_33_dialog_content = "Bien vale...",
  ui_story_5033_50330702_34_dialog_content = "Eh... Supongo que eres realmente un buen tipo, después de todo.",
  ui_story_5033_50330702_35_dialog_content = "No haremos más preguntas. ¡Duerme la siesta con nosotros!",
  ui_story_5033_50330702_36_dialog_content = "¡Sí! ¡Venga a dormir la siesta con nosotros, Sr. Navegante!",
  ui_story_5033_50330702_37_dialog_content = "¡Sr. Navegante, quiero más dulces!",
  ui_story_5033_50330702_38_dialog_content = "¡H-Oigan, no todos a la vez, muchachos! ¡Estoy a punto de caerme!",
  ui_story_5033_50330702_39_dialog_content = "¿Tienes dulces? Nosotros también queremos algo...",
  ui_story_5033_50330702_40_dialog_content = "Lo hago, lo hago, está justo aquí. Nekoyashiki metió un montón en mi bolsillo.",
  ui_story_5033_50330702_41_dialog_content = "Uno a la vez, muchachos. No hay necesidad de apurarse.",
  ui_story_5033_50330702_42_dialog_content = "Nekoyashiki ese bastardo, seguro que sabe lo que pasa.",
  ui_story_5033_50330702_43_dialog_content = "No creo que un niño pequeño deba hablar así de los adultos...",
  ui_story_5033_50330702_44_dialog_content = "Nekoyashiki es tu superior, después de todo. Deberías mostrarle un poco más de respeto.",
  ui_story_5033_50330702_45_dialog_content = "Oye, ¿qué da? ¡Deja de predicar y dame mi caramelo!",
  ui_story_5033_50330702_46_dialog_content = "Nekoyashiki me dejó este caramelo, ¿sabes? Si no lo respetas, ¿por qué debería compartir algo contigo?",
  ui_story_5033_50330702_47_dialog_content = "¿De qué estás hablando? Me llevo muy bien con Nekoyashiki, ¡y él nunca me diría que lo \"respetara\"!",
  ui_story_5033_50330702_48_dialog_content = "¿Quieres saber algo? Cuando Nekoyashiki llegó por primera vez a Euphoria, tenía una actitud realmente podrida.",
  ui_story_5033_50330702_49_dialog_content = "¡Pero luego un grupo de gángsters lo golpeó hasta la muerte!",
  ui_story_5033_50330702_50_dialog_content = "Apareció aquí, todo ensangrentado y magullado. Fue solo gracias a Pollux y Casta que sobrevivió.",
  ui_story_5033_50330702_51_dialog_content = "¿Por qué estás contando esta historia como si la vieras por ti mismo? ¿Estabas allí cuando sucedió?",
  ui_story_5033_50330702_52_dialog_content = "Espera... ¡¿No me digas que en realidad eres mayor que él?!",
  ui_story_5033_50330702_53_dialog_content = "¿Estás loco? Sí, estuve allí, pero solo tenía cinco años.",
  ui_story_5033_50330702_54_dialog_content = "Entonces, ¿cuál era el punto de contar esa historia?",
  ui_story_5033_50330702_55_dialog_content = "¡Para mostrarte lo cerca que estamos Nekoyashiki y yo! ¡Eh!",
  ui_story_5033_50330702_56_dialog_content = "¡Somos hermanos hasta el final! ¿Por qué tendríamos que ser todos estirados y formales el uno con el otro?",
  ui_story_5033_50330702_57_dialog_content = "S-Claro... No tenía idea de que Nekoyashiki pasó por algo así. Supongo que eso explica por qué parece estar en tan buenos términos con Raven's Blood.",
  ui_story_5033_50330702_58_dialog_content = "En cierto modo, Nekoyashiki se parece mucho a ustedes: otro niño acogido y protegido por Raven's Blood.",
  ui_story_5033_50330702_59_dialog_content = "Jejeje... exacto. Escuché que Nekoyashiki era solo un niño pequeño cuando llegó por primera vez a la iglesia.",
  ui_story_5033_50330702_60_dialog_content = "Pollux dijo que aunque su rostro estaba hinchado y ensangrentado en ese momento, sus ojos estaban llenos de orgullo.",
  ui_story_5033_50330702_61_dialog_content = "Una vez que las heridas de Nekoyashiki mejoraron, se fue sin decir una palabra más.",
  ui_story_5033_50330702_62_dialog_content = "Ahora, cada vez que viene, siempre nos trae mucha comida y otros artículos esenciales.",
  ui_story_5033_50330702_63_dialog_content = "¡Je, y él es nuestro vendedor de dulces confiable!",
  ui_story_5033_50330702_64_dialog_content = "Pase lo que pase, ¡él siempre se asegura de traernos muchos dulces!",
  ui_story_5033_50330702_65_dialog_content = "Muy bien chico, lo entiendo... Solo quieres tus dulces, ¿no? Aquí tomaló.",
  ui_story_5033_50330702_66_dialog_content = "¡Dulce!",
  ui_story_5033_50330702_67_dialog_content = "Oye, espera... Puedes tener tus dulces, pero ¿tienes que contarme más sobre Casta y Pólux?",
  ui_story_5033_50330702_68_dialog_content = "Ya que estaremos trabajando juntos, me gustaría saber un poco más sobre ellos.",
  ui_story_5033_50330702_69_dialog_content = "¡Claro, no hay problema! ¡Latan puede decirte todo lo que quieras saber!",
  ui_story_5033_50330702_70_dialog_content = "Hmm, supongo que empezaré con la misteriosa leyenda sobre Pólux...",
  ui_story_5033_50330702_71_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5033_50330702_72_dialog_content = "¡¿Eso fue un arma hace un momento?! Venía de afuera...",
  ui_story_5033_50330702_73_dialog_content = "Si no puede proporcionarme suficiente evidencia para demostrar su inocencia... Entonces no tengo más remedio que nombrarlo como el principal sospechoso.",
  ui_story_5033_50330702_74_dialog_content = "¡Baja la hoja o te haré comer balas!",
  ui_story_5033_50330702_75_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5033_50330702_76_dialog_content = "¡¿Por qué me dices que suelte mi arma cuando ya me estás disparando?!",
  ui_story_5033_50330702_77_dialog_content = "¡Ese fue un disparo de advertencia! Permítanme repetirme: suelten su arma.",
  ui_story_5033_50330702_78_dialog_content = "¡¿Cómo puedes acusar a Pólux de ser el asesino?!",
  ui_story_5033_50330702_79_dialog_content = "La hermana Matilda significó el mundo para nosotros. ¡Cómo te atreves a insinuar que podríamos matarla!",
  ui_story_5033_50330702_80_dialog_content = "Solo digo que es una posibilidad. Después de todo, todo lo que he escuchado hasta ahora es de su propia cuenta. No tengo forma de saber la verdad detrás de tu relación con la hermana Matilda.",
  ui_story_5033_50330702_81_dialog_content = "Disculpas. Puede ser difícil de aceptar, pero desde un punto de vista racional, no tengo más remedio que tratarte como sospechoso por el momento.",
  ui_story_5033_50330702_82_dialog_content = "La única manera de limpiar su nombre es proporcionarme pruebas suficientes de su inocencia.",
  ui_story_5033_50330702_83_dialog_content = "¡¿Qué diablos está pasando aquí?! ¡¿Por qué están peleando?!",
  ui_story_5033_50330702_84_dialog_content = "PlayerName, Pollux acaba de admitir que puede usar la misma técnica de asesinato que usó el asesino en serie.",
  ui_story_5033_50330702_85_dialog_content = "¡¿Qué?!",
  ui_story_5033_50330702_86_dialog_content = "No... ¡No puede ser! ¡Pólux nunca mataría a nadie!",
  ui_story_5033_50330702_87_dialog_content = "¡Basta ya todos!",
  ui_story_5033_50330702_88_dialog_content = "Ninguno de ustedes debería sacar sus armas frente a los niños.",
  ui_story_5033_50330702_89_dialog_content = "Pólux... ¿Te van a llevar?",
  ui_story_5033_50330702_90_dialog_content = "¡No dejaré que te lleven! ¡Yo te protegere!",
  ui_story_5033_50330801_1_dialog_content = "<color=#e8d9bb>*Retumbar*</color>",
  ui_story_5033_50330801_2_dialog_content = "<color=#e8d9bb>En un bar Euphorian...</color>",
  ui_story_5033_50330801_3_dialog_content = "¿Escuchaste? Raven's Blood se está volviendo todo amigo amigo con un par de idiotas de Umbraton.",
  ui_story_5033_50330801_4_dialog_content = "¿Me pregunto qué están haciendo?",
  ui_story_5033_50330801_5_dialog_content = "Nada bueno, apuesto. Escuché que Umbraton está tratando de hundir sus apestosas garras en Euphoria a continuación.",
  ui_story_5033_50330801_6_dialog_content = "Umbraton ya usa Euphoria como su propio vertedero personal. Tiran toda su basura aquí.",
  ui_story_5033_50330801_7_dialog_content = "¿No es eso suficiente para ellos?",
  ui_story_5033_50330801_8_dialog_content = "Ahora quieren quitarnos la tierra de debajo de nuestros pies...",
  ui_story_5033_50330801_9_dialog_content = "Los garitos de juego y las fábricas de armas que tenían demasiado miedo de hacer negocios en Umbraton vinieron aquí en su lugar.",
  ui_story_5033_50330801_10_dialog_content = "Entonces, ¿no será más de lo mismo?",
  ui_story_5033_50330801_11_dialog_content = "Como el infierno. Al menos antes, esos negocios pertenecían a Euphoria.",
  ui_story_5033_50330801_12_dialog_content = "Ahora, Umbraton quiere control total sobre todo.",
  ui_story_5033_50330801_13_dialog_content = "Bueno... digo que pertenecían a Euphoria, pero en realidad, pertenecían al \"Jefe\".",
  ui_story_5033_50330801_14_dialog_content = "Nuestra liberación no fue fácil de ganar en Euphoria, y me niego a vivir bajo el control de nadie nunca más como en los viejos tiempos...",
  ui_story_5033_50330801_15_dialog_content = "Puede que estemos quebrados, pero al menos ya no vivimos temiendo por nuestras vidas.",
  ui_story_5033_50330801_16_dialog_content = "¡Así es! ¡La euforia pertenece a todas y cada una de las pandillas aquí! Esas son las reglas.",
  ui_story_5033_50330801_17_dialog_content = "¡Abran paso a nuestro jefe!",
  ui_story_5033_50330801_18_dialog_content = "Ah, mi espalda...",
  ui_story_5033_50330801_19_dialog_content = "Escuché que Raven's Blood les dio una paliza. ¿Esa verdad?",
  ui_story_5033_50330801_20_dialog_content = "¡¿Qué clase de pregunta estúpida es esa?! Solo míranos!!",
  ui_story_5033_50330801_21_dialog_content = "Llegaron al punto de pelear con nosotros por esos asquerosos de Umbraton. ¿Me pregunto porque?",
  ui_story_5033_50330801_22_dialog_content = "Quién sabe qué tipo de esquemas están tramando con esos dos forasteros...",
  ui_story_5033_50330801_23_dialog_content = "Puedo responder eso. Mis muchachos me acaban de traer información interesante.",
  ui_story_5033_50330801_24_dialog_content = "Umbraton envió a esos dos aquí en una investigación de asesinato. Aparentemente, el asesino es de Euphoria, así que para eso están aquí.",
  ui_story_5033_50330801_25_dialog_content = "Mi conjetura es que Raven's Blood solo está usando esto como una oportunidad para adular a nuestros potencialmente nuevos maestros.",
  ui_story_5033_50330801_26_dialog_content = "Sin embargo, ¿por qué alguien le pediría a Raven's Blood que lo ayude con una investigación criminal?",
  ui_story_5033_50330801_27_dialog_content = "Además, toda esta \"investigación de asesinato\" podría ser una pésima excusa para que aparezcan y causen problemas.",
  ui_story_5033_50330801_28_dialog_content = "Di algo, ¿quieres, Gustav? ¡Sabes casi todo lo que sucede en Euphoria!",
  ui_story_5033_50330801_29_dialog_content = "¿Qué quieres oírme decir?",
  ui_story_5033_50330801_30_dialog_content = "¿Qué debemos hacer exactamente con todo esto?",
  ui_story_5033_50330801_31_dialog_content = "Decir la palabra \"exactamente\" no necesariamente hace que tu pregunta sea menos vaga.",
  ui_story_5033_50330801_32_dialog_content = "¿Estás preguntando qué debe hacer tu pandilla? ¿O toda Euforia?",
  ui_story_5033_50330801_33_dialog_content = "Ambos, obviamente!!!",
  ui_story_5033_50330801_34_dialog_content = "Por supuesto que mi pandilla es mi principal prioridad, pero también soy eufórico.",
  ui_story_5033_50330801_35_dialog_content = "En Euphoria, lo único que importa es el poder de una pandilla.",
  ui_story_5033_50330801_36_dialog_content = "Si Raven's Blood pudo derrotar a todos tus hombres con solo dos personas, me temo que los demás ya...",
  ui_story_5033_50330801_37_dialog_content = "¡Necesito llegar al fondo de esto!",
  ui_story_5033_50330801_38_dialog_content = "No estábamos agrupados en ese momento, y ninguno de nosotros tenía nuestras armas... ¡Sin mencionar que se agregaron un montón de Eclipsites a la mezcla! Esa es la única forma en que pudieron ganar.",
  ui_story_5033_50330801_39_dialog_content = "Procederemos de acuerdo con las reglas de Euphoria.",
  ui_story_5033_50330801_40_dialog_content = "Si usted y su pandilla quieren recuperar su reputación, deben desafiarlos a una pelea de pandillas formal y ganar.",
  ui_story_5033_50330801_41_dialog_content = "Pero si tienes demasiado miedo...",
  ui_story_5033_50330801_42_dialog_content = "N-no tengo miedo de pelear... ¡Solo espera hasta que mis heridas estén curadas, y voy a derribar a esos cuervos de su árbol!",
  ui_story_5033_50330801_43_dialog_content = "No, jefe. No deberíamos tener que hacer nada nosotros mismos.",
  ui_story_5033_50330801_44_dialog_content = "Después de todo, Raven's Blood fue quien trajo a esos forasteros de Umbraton a Euphoria primero y causó problemas. Ellos son los que rompieron las reglas.",
  ui_story_5033_50330801_45_dialog_content = "Así es, siempre supe que esas chicas Raven's Blood no eran buenas.",
  ui_story_5033_50330801_46_dialog_content = "Incluso jodieron el negocio de nuestra pandilla hace un tiempo.",
  ui_story_5033_50330801_47_dialog_content = "Siempre están merodeando por su preciosa iglesia día y noche, sin dejar que nadie se acerque.",
  ui_story_5033_50330801_48_dialog_content = "Bueno, duh, ese es su territorio. Por supuesto, no te dejarán entrar sin más.",
  ui_story_5033_50330801_49_dialog_content = "A-De todos modos... ¡simplemente me molestan!",
  ui_story_5033_50330801_50_dialog_content = "¡Toda la razón!",
  ui_story_5033_50330801_51_dialog_content = "Gustav, ve y dile a las otras pandillas en Euphoria que finalmente es hora de unirse y acabar con Raven's Blood, ¡de una vez por todas!",
  ui_story_5033_50330801_52_dialog_content = "Muy bien, ahora cálmense, todos ustedes.",
  ui_story_5033_50330801_53_dialog_content = "Sé que todos estáis convencidos de que la única forma de salvar a Euphoria es deshaciéndoos de Raven's Blood.",
  ui_story_5033_50330801_54_dialog_content = "Pero no deberías simplemente cargar imprudentemente.",
  ui_story_5033_50330801_55_dialog_content = "¿O ya has olvidado que Raven's Blood ha hecho nuevos amigos? Atacarlos ahora podría provocar que Umbraton tomara represalias.",
  ui_story_5033_50330801_56_dialog_content = "¡¿Y qué?! ¡¡Euphoria no le teme a Umbraton!!",
  ui_story_5033_50330801_57_dialog_content = "No se trata de si tienes miedo o no.",
  ui_story_5033_50330801_58_dialog_content = "El hecho es que todavía no sabemos exactamente qué trama Umbraton. Digo que averigüemos qué traman antes de hacer nuestro movimiento.",
  ui_story_5033_50331001_1_dialog_content = "No hay necesidad de preocuparse, niños. Tuvimos un pequeño malentendido, eso es todo.",
  ui_story_5033_50331001_2_dialog_content = "Baja tu arma, Casta. No lo dispares nunca más delante de los niños.",
  ui_story_5033_50331001_3_dialog_content = "Lo siento, Pollux... No estaba pensando bien. No pensé que los niños saldrían corriendo.",
  ui_story_5033_50331001_4_dialog_content = "Corax, no creo que el asesino en serie pueda ser alguien tan amado y en quien estos niños confíen tanto como ellos.",
  ui_story_5033_50331001_5_dialog_content = "Ya guardé mis cuchillos... Te dejaré hablar. Lo siento por adelantar el arma.",
  ui_story_5033_50331001_6_dialog_content = "¿E-Está todo realmente bien ahora?",
  ui_story_5033_50331001_7_dialog_content = "Sí, todo está bien ahora. Ahora todos regresen a la iglesia antes de que se resfríen.",
  ui_story_5033_50331001_8_dialog_content = "Así es, parece que va a llover pronto... ¿Por qué no entran primero, niños?",
  ui_story_5033_50331001_9_dialog_content = "Latan, tráelos a todos adentro.",
  ui_story_5033_50331001_10_dialog_content = "Bien...",
  ui_story_5033_50331001_11_dialog_content = "Bueno, soy todo oídos. Puede comenzar explicando por qué es capaz de usar la misma técnica de asesinato de alto nivel que el asesino.",
  ui_story_5033_50331001_12_dialog_content = "Es cierto que soy capaz de usar esa técnica, pero ni mucho menos en el grado en que lo estás describiendo.",
  ui_story_5033_50331001_13_dialog_content = "Además, esta técnica requiere el uso de un tipo de daga muy especial.",
  ui_story_5033_50331001_14_dialog_content = "Ya prometí hace 14 años no volver a usarlo nunca más.",
  ui_story_5033_50331001_15_dialog_content = "Nekoyashiki y yo podemos dar fe de eso.",
  ui_story_5033_50331001_16_dialog_content = "Lo siento, pero tus testimonios no tienen peso.",
  ui_story_5033_50331001_17_dialog_content = "Necesito más si quieres que confíe en ti, Pollux.",
  ui_story_5033_50331001_18_dialog_content = "Solo puedo ofrecerte todo lo que sé... Si confías o no en mí es tu decisión.",
  ui_story_5033_50331001_19_dialog_content = "Entonces dime, ¿cómo lograste aprender este tipo de técnica de asesinato?",
  ui_story_5033_50331001_20_dialog_content = "Lo aprendí del antiguo dueño de Euphoria. Todos lo llamaban <color=#FFB400>Jefe</color>.",
  ui_story_5033_50331001_21_dialog_content = "Su <color=#FFB400>organización</color> una vez tuvo el control de todos los residentes y negocios en Euphoria.",
  ui_story_5033_50331001_22_dialog_content = "En aquel entonces, todos vivían con miedo al Grim Reaper de la organización.",
  ui_story_5033_50331001_23_dialog_content = "Pertenecí a esa organización hace mucho tiempo, donde también me vi obligado a aprender la técnica de matar de Grim Reaper.",
  ui_story_5033_50331001_24_dialog_content = "¿Quién era exactamente este personaje de \"Jefe\"?",
  ui_story_5033_50331001_25_dialog_content = "Siempre que estábamos en su presencia, siempre se sentaba en una silla roja como la sangre de espaldas a nosotros.",
  ui_story_5033_50331001_26_dialog_content = "Nadie sabía su nombre ni siquiera cómo era.",
  ui_story_5033_50331001_27_dialog_content = "¿Por qué te unirías a una organización como esa?",
  ui_story_5033_50331001_28_dialog_content = "Cuando una persona lucha por sobrevivir, no siempre piensa en las consecuencias de sus decisiones.",
  ui_story_5033_50331001_29_dialog_content = "Entonces, cuando alguien me dijo que podía tener mi propia cama y que nunca más tendría que preocuparme por la comida o la ropa...",
  ui_story_5033_50331001_30_dialog_content = "Naturalmente, acepté la oferta.",
  ui_story_5033_50331001_31_dialog_content = "No fue hasta más tarde que descubrí que él era el \"Jefe\" del que todos hablaban.",
  ui_story_5033_50331001_32_dialog_content = "Entonces es seguro asumir que el asesino en serie era parte de esta organización, como tú, ¿correcto?",
  ui_story_5033_50331001_33_dialog_content = "Pero la organización fue aniquilada por completo hace diez años.",
  ui_story_5033_50331001_34_dialog_content = "Pensé que era el único sobreviviente.",
  ui_story_5033_50331001_35_dialog_content = "Es posible que hubiera más sobrevivientes, excepto que no los conocías.",
  ui_story_5033_50331001_36_dialog_content = "Ahora que ha revisado estos informes de autopsia, ¿alguien en particular le viene a la mente?",
  ui_story_5033_50331001_37_dialog_content = "Hay una persona...",
  ui_story_5033_50331001_38_dialog_content = "Ella sería la única lo suficientemente hábil para realizar estos asesinatos. Pero esa persona está muerta.",
  ui_story_5033_50331001_39_dialog_content = "¿Cómo estás tan seguro?",
  ui_story_5033_50331001_40_dialog_content = "Porque fui yo quien la mató... Mi mejor amiga.",
  ui_story_5033_50331001_41_dialog_content = "<color=#e8d9bb>Hace 14 años...</color>",
  ui_story_5033_50331001_42_dialog_content = "¿Es esta... mi propia cama?",
  ui_story_5033_50331001_43_dialog_content = "Oh...",
  ui_story_5033_50331001_44_dialog_content = "¡Ah! ¡¿Quién eres?! ¡¿Qué haces escondiéndote ahí?!",
  ui_story_5033_50331001_45_dialog_content = "¡P-Por favor, no te hagas una idea equivocada! ¡No quise asustarte siendo tan callado!",
  ui_story_5033_50331001_46_dialog_content = "Es solo... Estabas acariciando tu almohada hace un momento, y fue demasiado lindo para interrumpir...",
  ui_story_5033_50331001_47_dialog_content = "¡¿Te estás burlando de mí?!",
  ui_story_5033_50331001_48_dialog_content = "... No importa. Ríete si quieres, no me importa.",
  ui_story_5033_50331001_49_dialog_content = "Solo he visto almohadas en escaparates antes. Son tan suaves al tacto...",
  ui_story_5033_50331001_50_dialog_content = "Parece que eres mi nuevo compañero de cuarto.",
  ui_story_5033_50331001_51_dialog_content = "Me duele un poco la espalda de estar tanto tiempo parada. ¿Te importa si nos sentamos en tu cama y charlamos?",
  ui_story_5033_50331001_52_dialog_content = "¡S-Sí, por supuesto! ¡Aquí, ponte cómodo!",
  ui_story_5033_50331001_53_dialog_content = "Mi nombre es Antares. ¿Lo que es tuyo?",
  ui_story_5033_50331001_54_dialog_content = "Yo... Realmente no tengo mi propio nombre. He estado usando el nombre que me dio una monja cuando me encontró vagando por Euphoria.",
  ui_story_5033_50331001_55_dialog_content = "¿Qué estarías haciendo en un lugar como este? Sabes dónde estamos, ¿no?",
  ui_story_5033_50331001_56_dialog_content = "B-Bueno, alguien me dijo que podría ser elegido si me inscribía en esto.",
  ui_story_5033_50331001_57_dialog_content = "Y si me eligieran, nunca más tendría que preocuparme por la comida o la ropa. ¡Hasta tendría mi propia cama!",
  ui_story_5033_50331001_58_dialog_content = "¡Así que me inscribí, me seleccionaron y luego te conocí!",
  ui_story_5033_50331001_59_dialog_content = "Así que realmente no tienes idea de lo que hacen por aquí, eh...",
  ui_story_5033_50331001_60_dialog_content = "Supongo que no... ¿Qué te pasa, Antares? Tus manos están tan frías.",
  ui_story_5033_50331001_61_dialog_content = "¡Iré a cerrar la ventana!",
  ui_story_5033_50331001_62_dialog_content = "Estoy bien...",
  ui_story_5033_50331001_63_dialog_content = "Vale, pero si tienes frío, házmelo saber.",
  ui_story_5033_50331001_64_dialog_content = "Entonces, ¿has estado aquí por mucho tiempo? ¿Qué tipo de lugar es este, de todos modos?",
  ui_story_5033_50331001_65_dialog_content = "Sí, he estado viviendo en esta habitación desde que tengo memoria. Este lugar...",
  ui_story_5033_50331001_66_dialog_content = "Es una instalación de entrenamiento subterránea privada para mercenarios Euforianos.",
  ui_story_5033_50331001_67_dialog_content = "Pólux... Creo que debemos tener una conversación seria ahora mismo.",
  ui_story_5033_50331001_68_dialog_content = "Uh... ¡Yo sé lo que quieres decir, Antares! Te prometo que prestaré más atención la próxima vez, ¿de acuerdo?",
  ui_story_5033_50331001_69_dialog_content = "Dices eso cada vez... ¿Cuándo vas a cumplir tu promesa?",
  ui_story_5033_50331001_70_dialog_content = "Cada vez que vuelvo de una misión, tienes un montón de heridas nuevas en tu cuerpo antes de que las antiguas hayan terminado de sanar...",
  ui_story_5033_50331001_71_dialog_content = "¿Tienes idea de cuánto duele verte así? ¿Para vendarte, solo para encontrar nuevas heridas al día siguiente?",
  ui_story_5033_50331001_72_dialog_content = "Mis sentimientos no deben importarte, en absoluto...",
  ui_story_5033_50331001_73_dialog_content = "Lo siento, Antares... No sé qué me pasa.",
  ui_story_5033_50331001_74_dialog_content = "Cuando llegué aquí por primera vez, ya salías en misiones. En ese momento, sabía que había una gran brecha en nuestras fortalezas...",
  ui_story_5033_50331001_75_dialog_content = "Así que estudié lo más que pude, día y noche... Incluso me obligué a entrenar con mercenarios que eran mucho más fuertes y de mayor rango que yo.",
  ui_story_5033_50331001_76_dialog_content = "Pero para ellos, no soy tan bueno como tú... ¡Incluso los reclutas que llegaron un año o dos después de mí son más prometedores!",
  ui_story_5033_50331001_77_dialog_content = "Quiero ser como tú, Antares... ¡Yo también quiero ser un mercenario fuerte!",
  ui_story_5033_50331001_78_dialog_content = "No es así, Pólux. Escuchar...",
  ui_story_5033_50331001_79_dialog_content = "Todo el mundo sabe lo buenas que son tus notas, ¿verdad? ¡Incluso nos llaman Géminis por lo cerca que somos!",
  ui_story_5033_50331001_80_dialog_content = "Ya eres asombroso, Pólux. No hay necesidad de esforzarse tanto...",
  ui_story_5033_50331001_81_dialog_content = "Entonces, ¿por qué sigo atrapado aquí, mientras tú y los demás salís en misiones?",
  ui_story_5033_50331001_82_dialog_content = "Lo siento... Antares... Sé que estoy siendo terco y que solo estás cuidando de mí...",
  ui_story_5033_50331001_83_dialog_content = "No necesitas disculparte conmigo, Pollux. No soy yo a quien estás lastimando... Tú lo eres.",
  ui_story_5033_50331001_84_dialog_content = "Si pudiera hacer las cosas de nuevo, elegiría mi propia vida.",
  ui_story_5033_50331001_85_dialog_content = "Una vida sin culpas constantes... O pesadillas que me despierten todas las noches.",
  ui_story_5033_50331001_86_dialog_content = "Una vida... Sin \"misiones\".",
  ui_story_5033_50331001_87_dialog_content = "¿Eh? Pero tengo muchas ganas de salir en una misión, Antares...",
  ui_story_5033_50331001_88_dialog_content = "Quiero luchar a tu lado, para que podamos apoyarnos mutuamente todo el tiempo.",
  ui_story_5033_50331001_89_dialog_content = "Después de que me dijeron, finalmente podría salir en una misión...",
  ui_story_5033_50331001_90_dialog_content = "¿Qué haces ahí, Pólux? ¿Es un secreto?",
  ui_story_5033_50331001_91_dialog_content = "H-Oye! ¡Cierra tus ojos! Sin mirar, ¿oíste?",
  ui_story_5033_50331001_92_dialog_content = "Uf, bien... ¿Ves? Están cerrados.",
  ui_story_5033_50331001_93_dialog_content = "¡Y hecho! ¡Ya puedes abrir los ojos!",
  ui_story_5033_50331001_94_dialog_content = "¿Este <color=#FFB400>broche</color>... es para mí?",
  ui_story_5033_50331001_94X1_dialog_content = "Sí, la tienda me dijo que es hortensia, y creo que te queda perfecto.",
  ui_story_5033_50331001_95_dialog_content = "¡Sí! Solo recibo un pequeño estipendio en este momento, así que esto es todo lo que puedo pagar.",
  ui_story_5033_50331001_96_dialog_content = "Pero una vez que termine mi misión y cobre mi paga, ¡te conseguiré algo aún mejor! ¡Algo que seguro te encantará!",
  ui_story_5033_50331001_97_dialog_content = "¿M-Misión...?",
  ui_story_5033_50331001_98_dialog_content = "¡Sí! ¡Conocí al Jefe hace unos días y me dijo que tendría una misión para mí muy pronto!",
  ui_story_5033_50331001_99_dialog_content = "Así que te compré esto para celebrar que mi deseo se hizo realidad y para agradecerte por estar siempre ahí para mí.",
  ui_story_5033_50331001_100_dialog_content = "Ahora, ¿qué debo traerte a continuación...?",
  ui_story_5033_50331001_101_dialog_content = "...",
  ui_story_5033_50331001_102_dialog_content = "¿Qué te pasa, Antares? ¿No te gusta?",
  ui_story_5033_50331001_103_dialog_content = "No eso no es. Me encanta lo bonitas que se ven las flores moradas.",
  ui_story_5033_50331001_104_dialog_content = "Pólux...",
  ui_story_5033_50331001_105_dialog_content = "¿Sí?",
  ui_story_5033_50331001_106_dialog_content = "Gracias por ser mi amigo. El tiempo que hemos pasado juntos ha sido el momento más feliz de mi vida.",
  ui_story_5033_50331001_107_dialog_content = "No serías Antares si no salieras con algo cursi.",
  ui_story_5033_50331001_108_dialog_content = "yo también lo hago",
  ui_story_5033_50331001_109_dialog_content = "Gracias por ser mi amigo, Antares.",
  ui_story_5033_50331001_110_dialog_content = "Nunca podría haber esperado que la búsqueda fuera así.",
  ui_story_5033_50331001_111_dialog_content = "Yo, en una arena, enfrentándome a mi mejor amigo...",
  ui_story_5033_50331001_112_dialog_content = "P-Por qué...",
  ui_story_5033_50331001_113_dialog_content = "¿Por qué eres mi oponente...?",
  ui_story_5033_50331001_114_dialog_content = "Uno es un droide de combate, criado en combate real.",
  ui_story_5033_50331001_115_dialog_content = "El otro era un prometedor recién llegado y un talento cuidadosamente perfeccionado en el campo de entrenamiento.",
  ui_story_5033_50331001_116_dialog_content = "¡Este dúo de dinamita se conoce como Géminis! Pero hoy, solo uno de ellos saldrá del ring.",
  ui_story_5033_50331001_117_dialog_content = "¿Euphoria ha presenciado alguna vez, o presenciará alguna vez, un partido tan excitante y excitante como este?",
  ui_story_5033_50331001_118_dialog_content = "Antarés, tú...",
  ui_story_5033_50331001_119_dialog_content = "Levanta tu daga y ven a mí.",
  ui_story_5033_50331001_120_dialog_content = "¿No es la misión que estabas esperando?",
  ui_story_5033_50331001_121_dialog_content = "Sé que has estado entrenando duro para esto.",
  ui_story_5033_50331001_122_dialog_content = "Pero yo...",
  ui_story_5033_50331001_123_dialog_content = "¿Que estas esperando?",
  ui_story_5033_50331001_124_dialog_content = "Si esto fuera una pelea real, ya estarías muerto una docena de veces.",
  ui_story_5033_50331001_125_dialog_content = "No puedo levantar mi mano contra ti...",
  ui_story_5033_50331001_126_dialog_content = "¿Qué pasaría si te dijera que la única razón por la que estás aquí, ahora mismo, es por mí?",
  ui_story_5033_50331001_127_dialog_content = "No... ¡No, eso no puede ser verdad!",
  ui_story_5033_50331001_128_dialog_content = "¿Por qué hacernos pelear entre nosotros? ¿No crees que es un poco extraño?",
  ui_story_5033_50331001_129_dialog_content = "¿Extraño? Nada es extraño en Euphoria, y guarda muchos secretos que ni siquiera puedes comenzar a adivinar.",
  ui_story_5033_50331001_130_dialog_content = "Obviamente... te he persuadido muchas veces en el pasado.",
  ui_story_5033_50331001_131_dialog_content = "No hay forma de que pueda hacer concesiones por ti.",
  ui_story_5033_50331001_132_dialog_content = "¿De verdad levantarías una mano contra mí...?",
  ui_story_5033_50331001_133_dialog_content = "Correcto. Nací para la batalla, y lo primero que aprendí fue—",
  ui_story_5033_50331001_134_dialog_content = "No muestres piedad a nadie.",
  ui_story_5033_50331001_135_dialog_content = "No... <size=45>¡No quiero pelear contigo, Antares!</size>",
  ui_story_5033_50331001_136_dialog_content = "<size=45>¡¡O te defiendes o mueres!!</size>",
  ui_story_5033_50331001_137_dialog_content = "Cuando llegué a...",
  ui_story_5033_50331001_138_dialog_content = "Fue muy tarde.",
  ui_story_5033_50331001_139_dialog_content = "¡Urgh...!",
  ui_story_5033_50331001_140_dialog_content = "Yo... yo... ¿Qué he hecho?",
  ui_story_5033_50331001_141_dialog_content = "Antares... ¿Por qué no corriste?",
  ui_story_5033_50331001_142_dialog_content = "<anim type=Shake>Gracias... Gracias... Pólux...</anim>",
  ui_story_5033_50331001_143_dialog_content = "Antarés! ¡NO! No me dejes... Lo siento... Lo siento mucho...",
  ui_story_5033_50331001_144_dialog_content = "¿Por qué...? ¿Por qué no te escapaste?",
  ui_story_5033_50331001_145_dialog_content = "<anim type=Shake>Así puedo... ser libre...</anim>",
  ui_story_5033_50331001_146_dialog_content = "<anim type=Shake>Finalmente libre...</anim>",
  ui_story_5033_50331001_147_dialog_content = "Lo hice. La muerte de Antares está sobre mí... Maté a mi único amigo en todo el mundo con mis propias manos.",
  ui_story_5033_50331001_148_dialog_content = "No entendí hasta que la daga en mi mano ya había penetrado el pecho de Antares.",
  ui_story_5033_50331001_149_dialog_content = "Qué terrible fue aquello por lo que una vez anhelé verdaderamente.",
  ui_story_5033_50331001_150_dialog_content = "Es por eso que ya no empuñas dagas...",
  ui_story_5033_50331001_151_dialog_content = "Sí. Los eventos del día siguen repitiéndose en mi cabeza, tan reales que es como si estuviera de vuelta en la arena.",
  ui_story_5033_50331001_152_dialog_content = "Perdí el conocimiento después de la pelea y me quemé con fiebre alta durante más de una semana.",
  ui_story_5033_50331001_153_dialog_content = "Cuando finalmente me desperté, estaba solo en la habitación.",
  ui_story_5033_50331001_154_dialog_content = "La ropa de Antares, el cuaderno... Todos sus rastros habían desaparecido por completo dentro de esas cuatro paredes cuadradas.",
  ui_story_5033_50331001_155_dialog_content = "Era tan limpio, tan estéril... Como si ella nunca hubiera existido en este mundo.",
  ui_story_5033_50331001_156_dialog_content = "Rápidamente salí de esa habitación también. En menos de un mes, sus dos habitantes se habían ido.",
  ui_story_5033_50331001_157_dialog_content = "¿Dejaste esa organización?",
  ui_story_5033_50331001_158_dialog_content = "Bueno, no fue tanto saltar del barco como ser empujado.",
  ui_story_5033_50331001_159_dialog_content = "Después de esa pelea, comencé a tener miedo y me resultó difícil incluso sostener una daga.",
  ui_story_5033_50331001_160_dialog_content = "Para un mercenario, perder la capacidad de combate significa perder todo su valor.",
  ui_story_5033_50331001_161_dialog_content = "Así que es natural que me echaran del equipo y me mantuvieran cautivo en el sótano.",
  ui_story_5033_50331001_162_dialog_content = "Justo hasta que llegaron los Eclipsites y arrasaron el lugar hasta los cimientos.",
  ui_story_5033_50331001_163_dialog_content = "¿Tienes alguna otra información?",
  ui_story_5033_50331001_164_dialog_content = "No, lo siento. Eso es todo lo que sé...",
  ui_story_5033_50331001_165_dialog_content = "Sin embargo, te prometo que te ayudaré a llegar al fondo de esto.",
  ui_story_5033_50331001_166_dialog_content = "<color=#e8d9bb>papá...</color>",
  ui_story_5033_50331001_167_dialog_content = "¡Sostener! ¡Siento que mucha gente se dirige hacia aquí!",
  ui_story_5033_50331001_168_dialog_content = "¿Quién?",
  ui_story_5033_50331001_169_dialog_content = "No sé, pero creo que quieren... ¡¿rodear la iglesia?!",
  ui_story_5033_50331101_1_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5033_50331101_2_dialog_content = "¡Muévanse, muchachos! ¡Apresúrate!",
  ui_story_5033_50331101_3_dialog_content = "Armas listas, prepárense para atacar. ¡Raven's Blood no es fácil de engañar!",
  ui_story_5033_50331101_4_dialog_content = "¡Lista!",
  ui_story_5033_50331101_5_dialog_content = "En el down-low hasta que estemos en posición. Daré la señal de fuego, ¿entendido?",
  ui_story_5033_50331101_6_dialog_content = "¡Entendido!",
  ui_story_5033_50331101_7_dialog_content = "¿Están todos nuestros muchachos presentes y correctos?",
  ui_story_5033_50331101_8_dialog_content = "¡Todos están aquí, jefe! Raven's Blood está listo por esta vez!",
  ui_story_5033_50331101_9_dialog_content = "Jaja, excelente! Esperé mucho tiempo este día.",
  ui_story_5033_50331101_10_dialog_content = "Oye, espera un minuto... ¿No nos dijo Gustav que no nos apresuráramos?",
  ui_story_5033_50331101_11_dialog_content = "<size=45>¿Qué sabes?!</size>",
  ui_story_5033_50331101_12_dialog_content = "Esta es una oportunidad perfecta para encontrar pruebas de colusión entre Raven's Blood y Umbraton.",
  ui_story_5033_50331101_13_dialog_content = "¿Qué haremos si los dejamos escapar, hmm?",
  ui_story_5033_50331101_14_dialog_content = "Negativo. Debo informar a Gustav.",
  ui_story_5033_50331101_15_dialog_content = "¿Cuándo te convertiste en la marioneta de Gustav?",
  ui_story_5033_50331101_16_dialog_content = "Bien entonces, sal de aquí. Dije ¡VAMOS! ¡No me molestes!",
  ui_story_5033_50331101_17_dialog_content = "Quienesquiera que sean, definitivamente se dirigen hacia aquí.",
  ui_story_5033_50331101_18_dialog_content = "¿Quién se atreve a buscar problemas con Raven's Blood?",
  ui_story_5033_50331101_19_dialog_content = "Me temo que no es tan simple esta vez.",
  ui_story_5033_50331101_20_dialog_content = "Nadie se habría acercado tan precipitadamente a la iglesia antes.",
  ui_story_5033_50331101_21_dialog_content = "Es un grupo grande esta vez. Me preocupa que se hayan unido para lanzar un ataque.",
  ui_story_5033_50331101_22_dialog_content = "¿Porqué ahora?",
  ui_story_5033_50331101_23_dialog_content = "Parece que realmente tienen algo contra la gente de Umbraton que ingresa a Euphoria.",
  ui_story_5033_50331101_24_dialog_content = "¿Es porque vinimos aquí?",
  ui_story_5033_50331101_25_dialog_content = "Lo siento Corax.",
  ui_story_5033_50331101_26_dialog_content = "Tal vez nuestra forma de hacer las cosas irritó a las pandillas locales.",
  ui_story_5033_50331101_27_dialog_content = "Me temo que primero tenemos que ocuparnos de esta pelea de pandillas locales.",
  ui_story_5033_50331101_28_dialog_content = "Son simplemente cobardes, intimidando a los débiles pero temiendo a los fuertes. ¿De verdad creen que pueden vencer a nuestra Raven's Blood, incluso uniéndose?",
  ui_story_5033_50331101_29_dialog_content = "¡Digo que los traigan, no importa cuántos!",
  ui_story_5033_50331101_30_dialog_content = "Ríndalo un poco. No hay ningún beneficio para nosotros en empeorar las cosas.",
  ui_story_5033_50331101_31_dialog_content = "Casta, Corax, lleven a los niños a Nekoyashiki para que se refugien.",
  ui_story_5033_50331101_32_dialog_content = "Van tras Raven's Blood y la iglesia. Trataré de detenerlos aquí.",
  ui_story_5033_50331101_33_dialog_content = "Bueno. Mantendré a los niños a salvo, lo prometo.",
  ui_story_5033_50331101_34_dialog_content = "¿Y usted? Nadie puede manejar tantos solo, ni siquiera tú.",
  ui_story_5033_50331101_35_dialog_content = "Haré todo lo posible para ganar tiempo. Ahora ve, toma a los niños y sal de aquí.",
  ui_story_5033_50331101_36_dialog_content = "... Comprendido. ¡Será mejor que aguantes hasta que vuelva!",
  ui_story_5033_50331101_37_dialog_content = "Ayudaré. Algunos de los niños están heridos, por lo que debemos cuidarlos durante la mudanza.",
  ui_story_5033_50331101_38_dialog_content = "PlayerName.",
  ui_story_5033_50331101_39_dialog_content = "¿Eh? ¡Aquí!",
  ui_story_5033_50331101_40_dialog_content = "Si bien es posible que no sepa mucho sobre ti, creo que puedes encontrar una ruta segura para sacar a todos de aquí.",
  ui_story_5033_50331101_41_dialog_content = "¿Puedo dejar que tú guíes el camino?",
  ui_story_5033_50331101_42_dialog_content = "¡No hay problema!",
  ui_story_5033_50331101_43_dialog_content = "Nekoyashiki suele estar en su cabaña. ¿Recuerdas dónde está?",
  ui_story_5033_50331101_44_option_content = "Si",
  ui_story_5033_50331101_45_dialog_content = "Nekoyashiki vive en una cabaña con graffiti en forma de cicatriz.",
  ui_story_5033_50331101_46_dialog_content = "Cruce el callejón al sur de la iglesia, avance un par de cuadras más y luego baje por el camino angosto.",
  ui_story_5033_50331101_47_dialog_content = "Debería haber unas cinco o seis vueltas...",
  ui_story_5033_50331101_48_dialog_content = "Tendrás que hacer seis vueltas.",
  ui_story_5033_50331101_49_dialog_content = "Bien, lo tengo. Déjame pensar en la mejor manera de hacerlo.",
  ui_story_5033_50331101_50_dialog_content = "Bueno. Pregúntale a Casta si tienes más preguntas. Me temo que ella y Corax tendrán que encargarse de cualquier pelea.",
  ui_story_5033_50331101_51_dialog_content = "Si es necesario, también puede preguntar a Latan. Puede que sea joven, pero es confiable.",
  ui_story_5033_50331101_52_option_content = "No",
  ui_story_5033_50331101_53_dialog_content = "Es esa pequeña cabaña en la que has estado antes. El que tiene el graffiti en forma de cicatriz afuera.",
  ui_story_5033_50331101_54_dialog_content = "Cuando salga, primero cruce el callejón al sur de la iglesia, luego avance un par de cuadras más.",
  ui_story_5033_50331101_55_dialog_content = "Si alguien está en la calle, avance un poco más y busque un callejón con pegatinas de osos en la pared.",
  ui_story_5033_50331101_56_dialog_content = "Esas son las obras de los niños. Los reconocerán, también Casta.",
  ui_story_5033_50331101_57_dialog_content = "Me temo que Casta y Corax tendrán que encargarse de cualquier pelea. Dependerá de ti seguir adelante con los niños.",
  ui_story_5033_50331101_58_dialog_content = "Cuando llegues allí, cuéntale todo a Nekoyashiki. Él podrá llevarte a un lugar seguro. ¿Tienes todo eso?",
  ui_story_5033_50331101_59_dialog_content = "Entiendo.",
  ui_story_5033_50331101_60_dialog_content = "Excelente. Eres un buen chico.",
  ui_story_5033_50331101_61_option_content = "No soy un niño.",
  ui_story_5033_50331101_62_dialog_content = "Me has dado el trabajo de llevarnos allí, y lo haré sin problemas.",
  ui_story_5033_50331101_63_dialog_content = "También puedo ayudar a Casta y Corax a luchar, para que los niños no sufran ningún daño. Puedes relajarte.",
  ui_story_5033_50331101_64_dialog_content = "Eso es maravilloso. Veo que mi fe en ti no estaba fuera de lugar...",
  ui_story_5033_50331101_65_dialog_content = "Eres mucho más maduro de lo que pensaba. Cuando todo esto se calme, me encantaría escuchar tu historia.",
  ui_story_5033_50331101_66_dialog_content = "Muy bien, eso es un trato.",
  ui_story_5033_50331101_67_option_content = "Seré un buen chico.",
  ui_story_5033_50331101_68_dialog_content = "Esos también son buenos niños. Estoy seguro de que cooperarán.",
  ui_story_5033_50331101_69_dialog_content = "No hay necesidad de preocuparse. Regresaremos inmediatamente, una vez que los tengamos en algún lugar seguro.",
  ui_story_5033_50331101_70_dialog_content = "Bien. Escuchar eso me tranquiliza más.",
  ui_story_5033_50331101_71_dialog_content = "¡Será mejor que esperes hasta que volvamos para ayudarte, Pollux!",
  ui_story_5033_50331101_72_dialog_content = "Lo sé. Lo haré lo mejor que pueda. Gracias.",
  ui_story_5033_50331101_73_dialog_content = "Ya vienen Casta y los niños. Usted tiene que ir.",
  ui_story_5033_50331101_74_dialog_content = "Pollux, Casta dijo que tenemos que ir a un lugar seguro. ¿Y usted? ¿No vienes con nosotros?",
  ui_story_5033_50331101_75_dialog_content = "Pólux...! Pólux... ¡Ven con nosotros!",
  ui_story_5033_50331101_76_dialog_content = "Ahora, todos, no molestemos más a Pólux. ¿No acordamos escuchar el plan?",
  ui_story_5033_50331101_77_dialog_content = "Pero...",
  ui_story_5033_50331101_78_dialog_content = "No se preocupen por mí, niños.",
  ui_story_5033_50331101_79_dialog_content = "Necesito quedarme aquí por un tiempo, ya que hay algo de lo que debo ocuparme.",
  ui_story_5033_50331101_80_dialog_content = "Chicos, tenéis que ir a un lugar seguro ahora. Intenta alejarte de aquí.",
  ui_story_5033_50331101_81_dialog_content = "Uh... Pero hay montones de eclipses fuera de la iglesia. Si no vienes con nosotros...",
  ui_story_5033_50331101_82_dialog_content = "Casta y el Dr. Corax te atenderán, no te preocupes.",
  ui_story_5033_50331101_83_dialog_content = "PlayerName y Nekoyashiki también estará allí.",
  ui_story_5033_50331101_84_dialog_content = "¿Cuándo podemos volver a la iglesia?",
  ui_story_5033_50331101_85_dialog_content = "Está bien incluso si no podemos volver a la iglesia. Buscaremos otro refugio.",
  ui_story_5033_50331101_86_dialog_content = "Lo más importante es que todos estén seguros y felices juntos.",
  ui_story_5033_50331101_87_dialog_content = "Pero, pero tú... Seguirás estando con nosotros, ¿verdad?",
  ui_story_5033_50331101_88_dialog_content = "¡Sí, por supuesto!",
  ui_story_5033_50331101_89_dialog_content = "Iré a buscarte, tan pronto como me ocupe de esto.",
  ui_story_5033_50331101_90_dialog_content = "Váyanse ahora, niños.",
  ui_story_5033_50331202_1_dialog_content = "¡Sal de aquí, Sangre de Cuervo!",
  ui_story_5033_50331202_2_dialog_content = "¡Sal de aquí y muere!",
  ui_story_5033_50331202_3_dialog_content = "No creas que puedes simplemente caminar sobre Euphoria. ¡Sal de aquí AHORA!",
  ui_story_5033_50331202_4_dialog_content = "¡Será mejor que presten atención, todos en la iglesia, pero especialmente esos dos de Umbraton!",
  ui_story_5033_50331202_5_dialog_content = "No me importa por qué estás aquí, pero en Euphoria, juegas según las reglas de Euphoria.",
  ui_story_5033_50331202_6_dialog_content = "Si te atreves a conspirar con Raven's Blood, entonces eres el enemigo de Euphoria.",
  ui_story_5033_50331202_7_dialog_content = "Si hay algo que quieras discutir, entonces puedes venir a la iglesia.",
  ui_story_5033_50331202_8_dialog_content = "Daremos la bienvenida a todos, y estoy seguro de que estará satisfecho con su recepción, ya sea con una pistola o un cuchillo.",
  ui_story_5033_50331202_9_dialog_content = "¡Oiga jefe, esa es la voz de Pólux!",
  ui_story_5033_50331202_10_dialog_content = "¡¿Qué están haciendo ahí dentro?!",
  ui_story_5033_50331202_11_dialog_content = "Yo... no sé...",
  ui_story_5033_50331202_12_dialog_content = "¿Qué hacemos ahora?",
  ui_story_5033_50331202_13_dialog_content = "¿Qué tal si... Jefe, usted entra primero?",
  ui_story_5033_50331202_14_dialog_content = "¡¿Eres estúpido, idiota?!",
  ui_story_5033_50331202_15_dialog_content = "¡Definitivamente no puedo entrar solo! Tiene que ser una trampa.",
  ui_story_5033_50331202_16_dialog_content = "¡El jefe tiene razón! Si vamos a entrar, deberíamos entrar todos juntos.",
  ui_story_5033_50331202_17_dialog_content = "¿Apresurarte en qué, estúpido? ¡Llama a alguien para que traiga los explosivos!",
  ui_story_5033_50331202_18_dialog_content = "Uh-oh... Sí, por supuesto.",
  ui_story_5033_50331202_19_dialog_content = "Los demás están esperando aquí. Haz que rodeen el lugar y asegúrate de que nadie se escape.",
  ui_story_5033_50331202_20_dialog_content = "¡Buena idea!",
  ui_story_5033_50331202_21_dialog_content = "¿Cómo es que todavía no hay noticias de Gustav? se esta desesperando...",
  ui_story_5033_50331202_22_dialog_content = "Miau...",
  ui_story_5033_50331202_23_dialog_content = "¡Esa es la señal! Finalmente...",
  ui_story_5033_50331202_24_dialog_content = "Um... ¿Lo tienes?",
  ui_story_5033_50331202_25_dialog_content = "Oh, querida, ¿estás esperando este papelito?",
  ui_story_5033_50331202_26_dialog_content = "¿Quién... quién eres tú? ¿Cuánto tiempo has estado detrás de mí?",
  ui_story_5033_50331202_27_dialog_content = "Desde que llegaste aquí.",
  ui_story_5033_50331202_28_dialog_content = "¡¿La n-monja?! he terminado por...",
  ui_story_5033_50331202_29_dialog_content = "Así es. Puedes llamarme Hermana Ana, o <color=#FFB400>Antares</color>.",
  ui_story_5033_50331202_30_dialog_content = "Pero, de nuevo... No tendrás oportunidad de decírselo a nadie.",
  ui_story_5033_50331202_31_dialog_content = "¡No! Por favor no me mates... Yo... Yo solo hago mandados... No sé nada.",
  ui_story_5033_50331202_32_dialog_content = "Tal vez no te mate, pero, de nuevo, ¿tal vez podrías decirme quién es Gustav?",
  ui_story_5033_50331202_33_dialog_content = "Sospecho... que te dio este papel, ¿verdad?",
  ui_story_5033_50331202_34_dialog_content = "No puedo creer que sea tan fácil.",
  ui_story_5033_50331202_35_dialog_content = "Dime, ¿es esto algún tipo de trampa para atraerme?",
  ui_story_5033_50331202_36_dialog_content = "De qué estás hablando...? ¡Ni siquiera entiendo lo que dices!",
  ui_story_5033_50331202_37_dialog_content = "Oh no... Tal vez la situación era tan volátil que no tuvo tiempo de cubrir sus huellas...",
  ui_story_5033_50331202_38_dialog_content = "¿Qué estás tratando de decir? Esto es Loco...",
  ui_story_5033_50331202_39_dialog_content = "¡No te hagas el tonto conmigo! Supe que me reconociste en el primer segundo que me viste.",
  ui_story_5033_50331202_40_dialog_content = "Además, sabes lo que estoy aquí para hacer, o más bien... lo que podría estar aquí para hacer.",
  ui_story_5033_50331202_41_dialog_content = "La gente no miente cuando mira a la muerte a la cara.",
  ui_story_5033_50331202_42_dialog_content = "Urgh...",
  ui_story_5033_50331202_43_dialog_content = "Antares... No te diré nada.",
  ui_story_5033_50331202_44_dialog_content = "Ni siquiera lo necesito más.",
  ui_story_5033_50331202_45_dialog_content = "<color=#e8d9bb>¡Whoosh—!</color>",
  ui_story_5033_50331202_46_dialog_content = "Urgh... Tú...",
  ui_story_5033_50331202_47_dialog_content = "Así que... Así es como se siente... ser asesinado por Grim Reaper...",
  ui_story_5033_50331202_48_dialog_content = "A modo de agradecimiento por proporcionarme esta pista, haré todo lo posible para que no sufra indebidamente.",
  ui_story_5033_50331202_49_dialog_content = "Tienes mi agradecimiento.",
  ui_story_5033_50331202_50_dialog_content = "Y ahora... Finalmente, puedo ir a buscar a Pollux.",
  ui_story_5033_50331202_51_dialog_content = "¡Jefe! ¡Hola jefe! ¡Tenemos los explosivos!",
  ui_story_5033_50331202_52_dialog_content = "Puede que no sea mucho, pero seguro que hará volar esa iglesia por los aires.",
  ui_story_5033_50331202_53_dialog_content = "¡Excelente! Bien hecho.",
  ui_story_5033_50331202_54_dialog_content = "Colócalos en un círculo alrededor de la iglesia.",
  ui_story_5033_50331202_55_dialog_content = "Tenga cuidado al colocarlos, especialmente si disparan desde el interior de la iglesia.",
  ui_story_5033_50331202_56_dialog_content = "¡No hay problema!",
  ui_story_5033_50331202_57_dialog_content = "Disculpe, perdone, necesito llegar al frente.",
  ui_story_5033_50331202_58_dialog_content = "¿De dónde salió la monja? Sal del camino, a menos que estés buscando un ataúd...",
  ui_story_5033_50331202_59_dialog_content = "<color=#e8d9bb>¡Whoosh—!</color>",
  ui_story_5033_50331202_60_dialog_content = "<size=45>¡¡ARGH!! ¡¡Asesinato!!</tamaño>",
  ui_story_5033_50331202_61_dialog_content = "¡¿Qué?! ¿Qué está pasando allá atrás?",
  ui_story_5033_50331202_62_dialog_content = "No te preocupes, no pasó nada... Después de todo, la gente muere en las guerras de pandillas.",
  ui_story_5033_50331202_63_dialog_content = "¡¿De donde vienes?!",
  ui_story_5033_50331202_64_dialog_content = "<color=#e8d9bb>¡Whoosh—!</color>",
  ui_story_5033_50331202_65_dialog_content = "Argh-! Mi mano... ¡Mi mano!",
  ui_story_5033_50331202_66_dialog_content = "¡Jefe! ¡Esta monja, tiene un cuchillo...!",
  ui_story_5033_50331202_67_dialog_content = "¡SÉ! ¡Ella es la que me cortó! ¡Ve tras ella y derríbala!",
  ui_story_5033_50331202_68_dialog_content = "Te aconsejo que no uses explosivos para tratar de destruir la iglesia, o te enfrentarás a la ira del cielo.",
  ui_story_5033_50331202_69_dialog_content = "<color=#e8d9bb>¡Whoosh—!</color>",
  ui_story_5033_50331202_70_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5033_50331202_71_dialog_content = "¿Explosiones? ¡Rápido, esparcios!",
  ui_story_5033_50331202_72_dialog_content = "Esa monja cortó el cartucho explosivo. ¡Está loca!",
  ui_story_5033_50331202_73_dialog_content = "¡Mira eso! La monja sigue viva... ¿Cómo se las arregló para eso?",
  ui_story_5033_50331202_74_dialog_content = "Si todos pudieran guardar silencio por un minuto, por favor. Estoy aquí porque tengo algo que hacer en la iglesia. Una vez que termine, dejaré a todos en paz.",
  ui_story_5033_50331202_75_dialog_content = "Aconsejaría no tomar ninguna medida precipitada antes de esa fecha.",
  ui_story_5033_50331202_76_dialog_content = "A menos que quieras conocer al <color=#FFB400>Grim Reaper</color>...",
  ui_story_5033_50331301_1_dialog_content = "Q-ahora qué... ¿Deberíamos escuchar a esa monja?",
  ui_story_5033_50331301_2_dialog_content = "Varias personas ya estaban muertas, ¿no viste?",
  ui_story_5033_50331301_3_dialog_content = "Si quieres subir, siéntete libre... No tengo prisa.",
  ui_story_5033_50331301_4_dialog_content = "¿Ella... acaba de mencionar al Segador? ¿Significa eso que esas leyendas son realmente ciertas?",
  ui_story_5033_50331301_5_dialog_content = "Shh... Bueno, si es cierto, ese es un nombre que nunca debemos mencionar.",
  ui_story_5033_50331301_6_dialog_content = "Gracias por su cooperación.",
  ui_story_5033_50331301_7_dialog_content = "<color=#e8d9bb>Dentro de la iglesia</color>",
  ui_story_5033_50331301_8_dialog_content = "... ¿Qué está pasando exactamente ahí fuera?",
  ui_story_5033_50331301_9_dialog_content = "<color=#e8d9bb>Pa, pa...</color>",
  ui_story_5033_50331301_10_dialog_content = "Hola.",
  ui_story_5033_50331301_11_dialog_content = "El perímetro está muy bien vigilado... ¿Cómo entraste aquí?",
  ui_story_5033_50331301_12_dialog_content = "Hablé con la gente de afuera y accedieron a dejarme pasar.",
  ui_story_5033_50331301_13_dialog_content = "No me importa quién eres, o por qué estás aquí.",
  ui_story_5033_50331301_14_dialog_content = "Pero, por favor, váyase... No hay ningún dios de la luz aquí, hermana.",
  ui_story_5033_50331301_15_dialog_content = "... ¿No me reconoces? Pólux.",
  ui_story_5033_50331301_16_dialog_content = "<size=45>¡Tú...!</size>",
  ui_story_5033_50331301_17_dialog_content = "Ha sido un largo tiempo.",
  ui_story_5033_50331301_18_dialog_content = "<color=#FFB400>Antares</color>, eres... No... ¿Cómo es posible?",
  ui_story_5033_50331301_19_dialog_content = "Lo siento, Pólux. Esta es la única forma en que podría encontrarte de nuevo.",
  ui_story_5033_50331301_20_dialog_content = "Para ser honesto, pensé que me habrías olvidado.",
  ui_story_5033_50331301_21_dialog_content = "¡¿Cómo podría olvidarlo?! Yo era el responsable en ese entonces...",
  ui_story_5033_50331301_22_dialog_content = "No me des esa mirada culpable, Pólux. Te lo ruego.",
  ui_story_5033_50331301_23_dialog_content = "Seguía jugando en mi cabeza: lo que debería decirte si alguna vez nos volviéramos a encontrar, cómo debería enfrentarte.",
  ui_story_5033_50331301_24_dialog_content = "Pero ahora que estás aquí, parado frente a mí, no puedo recordar ni una sola palabra.",
  ui_story_5033_50331301_25_dialog_content = "Qué estás tratando de decir...?",
  ui_story_5033_50331301_26_dialog_content = "Tus ojos siguen siendo los mismos de hace tantos años. No han cambiado.",
  ui_story_5033_50331301_27_dialog_content = "Tan brillante como las estrellas.",
  ui_story_5033_50331301_28_dialog_content = "Anne... ¿Estás detrás de todo? ¿Pero por qué?",
  ui_story_5033_50331301_29_dialog_content = "Pero, ¿cómo podría ser esto? ¿Cómo sobreviviste?",
  ui_story_5033_50331301_30_dialog_content = "¿Y por qué estás... vestida como una monja?",
  ui_story_5033_50331301_31_dialog_content = "No te preocupes, Pólux, te lo diré. Te lo diré todo.",
  ui_story_5033_50331301_32_dialog_content = "Te daré la versión corta ahora... No tenemos mucho tiempo.",
  ui_story_5033_50331301_33_dialog_content = "<color=#e8d9bb>Hace 14 años...</color>",
  ui_story_5033_50331301_34_dialog_content = "Sí, solo aquí. Ahora a tirarlo al río.",
  ui_story_5033_50331301_35_dialog_content = "¡Una pena! Como una de las Géminis, acaba de morir así.",
  ui_story_5033_50331301_36_dialog_content = "El jefe tampoco pensó que ella tomaría esa decisión...",
  ui_story_5033_50331301_37_dialog_content = "<color=#e8d9bb>Chapoteo—</color>",
  ui_story_5033_50331301_38_dialog_content = "¡Ay, cielos! ¡Mirar! En el rio...",
  ui_story_5033_50331301_39_dialog_content = "Ayúdame... ¡Aquí hay un niño!",
  ui_story_5033_50331301_40_dialog_content = "¡Enciende el fuego, rápido! ¡Sigue viva! Alguien llame al doctor!",
  ui_story_5033_50331301_41_dialog_content = "Ay... duele...",
  ui_story_5033_50331301_42_dialog_content = "¿Que todavía estoy vivo?",
  ui_story_5033_50331301_43_dialog_content = "¿Quién es ese fuera de la puerta?",
  ui_story_5033_50331301_44_dialog_content = "Es simplemente monstruoso. ¿Quién podría hacerle esto a un niño?",
  ui_story_5033_50331301_45_dialog_content = "Seguro que es resistente para sobrevivir incluso a una lesión como esa.",
  ui_story_5033_50331301_46_dialog_content = "Hay más en esto. Llévala a la abadía de Umbraton. Prefiero no meterme en más problemas...",
  ui_story_5033_50331301_47_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_5033_50331301_48_dialog_content = "Aquí está el periódico de hoy, Anne.",
  ui_story_5033_50331301_49_dialog_content = "También hay una carta... Aunque no tienes a nadie llamado <color=#FFB400>Antares</color> aquí, ¿verdad?",
  ui_story_5033_50331301_50_dialog_content = "¿Qué?",
  ui_story_5033_50331301_51_dialog_content = "... No. No hay nadie aquí con ese nombre.",
  ui_story_5033_50331301_52_dialog_content = "Tal vez sea el nombre equivocado. ¿Podrías averiguar para quién es?",
  ui_story_5033_50331301_53_dialog_content = "A Antarés.",
  ui_story_5033_50331301_54_dialog_content = "Soy un devoto discípulo del dios de la luz. Deseo arrepentirme en nombre de alguien que cometió un pecado imperdonable.",
  ui_story_5033_50331301_55_dialog_content = "Fingió su propia muerte y engañó a su familia, todo con el fin de obtener una falsa libertad.",
  ui_story_5033_50331301_56_dialog_content = "Se aprovecha de las amistades, dejando que quienes la aman lleven la carga de la vida por ella y se hundan en un mar de miseria.",
  ui_story_5033_50331301_57_dialog_content = "Ella debe arrepentirse hasta que llegue la próxima carta de confesión.",
  ui_story_5033_50331301_58_dialog_content = "¿Quién envió esto...?",
  ui_story_5033_50331301_59_dialog_content = "¿Estás bien, Ana? Te has puesto pálido.",
  ui_story_5033_50331301_60_dialog_content = "Permítanme mantener esta carta aquí por ahora.",
  ui_story_5033_50331301_61_dialog_content = "Tal vez alguien llamado Antares... vendría a reclamarlo.",
  ui_story_5033_50331301_62_dialog_content = "Así que durante todos estos años, ¿has estado viviendo como monja?",
  ui_story_5033_50331301_63_dialog_content = "Así es.",
  ui_story_5033_50331301_64_dialog_content = "No tengo idea de cómo quien envió la carta sabía mi verdadera identidad...",
  ui_story_5033_50331301_65_dialog_content = "Pero independientemente, \"él\" me tenía firmemente bajo su control. No me atrevía a desobedecer ninguna orden.",
  ui_story_5033_50331301_66_dialog_content = "¡Pero ni siquiera temes a la muerte! ¿Cómo puede alguien controlarte? Entonces, ¿los fantasmas tienen debilidades?",
  ui_story_5033_50331301_67_dialog_content = "Sí... Mi única debilidad era mi único amigo.",
  ui_story_5033_50331301_68_dialog_content = "¿Estás diciendo que es por mi culpa?",
  ui_story_5033_50331301_69_dialog_content = "Sí. Dijo que el incidente casi te destruye, pero que Géminis debe continuar...",
  ui_story_5033_50331301_70_dialog_content = "\"Pollux no vale nada si ya no puede manejar un cuchillo\".",
  ui_story_5033_50331301_71_dialog_content = "Si no cumplo mis órdenes, serás...",
  ui_story_5033_50331301_72_dialog_content = "Siempre pensé que la organización no persiguió mi fracaso porque los Eclipsites invadieron y no tenían tiempo de sobra...",
  ui_story_5033_50331301_73_dialog_content = "Pero la organización no nos dejará ir tan fácilmente.",
  ui_story_5033_50331301_74_dialog_content = "Incluso si todo Euphoria fuera destruido, aún habría personas en la organización que continuarían manipulándonos.",
  ui_story_5033_50331301_75_dialog_content = "Entonces, ¿realmente hiciste todas esas cosas, Anne?",
  ui_story_5033_50331301_76_dialog_content = "No tuve elección, Pólux.",
  ui_story_5033_50331301_77_dialog_content = "No solo sobreviviste a esa pelea, sino que incluso lograste escapar de ese lugar.",
  ui_story_5033_50331301_78_dialog_content = "Quiero proteger tu libertad.",
  ui_story_5033_50331301_79_dialog_content = "Aunque no hayas dejado Euphoria, tienes a alguien a quien proteger, en quien confiar, ¿no es así?",
  ui_story_5033_50331301_80_dialog_content = "¿Estás hablando de los niños?",
  ui_story_5033_50331301_81_dialog_content = "Y esa joven con el arma. Ella parece bastante confiable.",
  ui_story_5033_50331301_82_dialog_content = "Con gente así de tu lado, no tienes nada que temer.",
  ui_story_5033_50331301_83_dialog_content = "Mientras que yo no soy más que un vil no-muerto desaparecido hace mucho tiempo.",
  ui_story_5033_50331301_84_dialog_content = "¡¿También mataste a la hermana Matilda?!",
  ui_story_5033_50331301_85_dialog_content = "...",
  ui_story_5033_50331301_86_dialog_content = "¡Respóndeme, Ana!",
  ui_story_5033_50331301_87_dialog_content = "Sí.",
  ui_story_5033_50331301_88_dialog_content = "¿Por qué?",
  ui_story_5033_50331301_89_dialog_content = "Matarla era solo una orden de muchas. Ni siquiera sé por qué la organización la atacó.",
  ui_story_5033_50331301_90_dialog_content = "Lo siento, Pólux.",
  ui_story_5033_50331301_91_dialog_content = "Sabes lo importante que era ella para mí.",
  ui_story_5033_50331301_92_dialog_content = "No tuve elección...",
  ui_story_5033_50331301_93_dialog_content = "Viniste desarmado.",
  ui_story_5033_50331301_94_dialog_content = "¿Qué?",
  ui_story_5033_50331301_95_dialog_content = "Tu arma, Antares. Vienes ante mí, me dices todo esto, pero estás desarmado...",
  ui_story_5033_50331301_96_dialog_content = "¿Estás apostando a que no levantaré la mano contra ti?",
  ui_story_5033_50331301_97_dialog_content = "Se siente como si hubiéramos estado aquí antes... Aunque, Pollux, ESTOY armado.",
  ui_story_5033_50331301_98_dialog_content = "Porque mi última misión... es <color=#FFB400>matarte</color>.",
  ui_story_5033_50331301_99_dialog_content = "¿Entonces que estás esperando?",
  ui_story_5033_50331301_100_dialog_content = "Tú me conoces, Pólux. Sabes que nunca podría hacer eso.",
  ui_story_5033_50331301_101_dialog_content = "No vine aquí solo para contarte estas viejas historias...",
  ui_story_5033_50331301_102_dialog_content = "Voy a encargarme de esa escoria que me ha estado usando durante tantos años, y eliminaré la amenaza más peligrosa para ti en el proceso.",
  ui_story_5033_50331301_103_dialog_content = "¿Esperas que te lo agradezca?",
  ui_story_5033_50331301_104_dialog_content = "En lo mas minimo. Vine solo a verte una última vez, antes de despedirnos una vez más.",
  ui_story_5033_50331301_105_dialog_content = "Mi queridísimo Pólux... Espero que cuando todo esto termine, sepas lo que hay que hacer.",
  ui_story_5033_50331301_106_dialog_content = "Er...",
  ui_story_5033_50331301_107_dialog_content = "Realmente eres egoísta.",
  ui_story_5033_50331301_108_dialog_content = "Abriéndote paso en mi amistad y mi cuchillo en tu cuerpo... Incluso \"muerto\", de alguna manera te las arreglaste para controlar mi destino...",
  ui_story_5033_50331301_109_dialog_content = "Y ahora te paras ante mí tan grandioso, tus palabras arrogantes.",
  ui_story_5033_50331301_110_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5033_50331301_111_dialog_content = "Parece que se acabó el tiempo.",
  ui_story_5033_50331301_112_dialog_content = "Gente... No, Eclipsites, entrando por la parte de atrás.",
  ui_story_5033_50331301_113_dialog_content = "Eres listo ahora, Pollux, muy listo. Casi como una persona totalmente diferente a la de entonces.",
  ui_story_5033_50331301_114_dialog_content = "El cabello largo también te queda bien. Pero, ¿qué pasó con tus ojos?",
  ui_story_5033_50331301_115_dialog_content = "... No tengo nada que desee compartir contigo.",
  ui_story_5033_50331301_116_dialog_content = "Pero lo hago...",
  ui_story_5033_50331301_117_dialog_content = "Y lo compartiré contigo, tan pronto como termine con la primera parte de mi expiación.",
  ui_story_5033_50331302_1_dialog_content = "Latán, Schewe...",
  ui_story_5033_50331302_2_dialog_content = "Bien, tenemos a todos.",
  ui_story_5033_50331302_3_dialog_content = "Todo el mundo tiene que quedarse aquí y no salir corriendo. ¿Comprendido?",
  ui_story_5033_50331302_4_dialog_content = "¡Puedo ayudar! ¡Pólux me enseñó a luchar!",
  ui_story_5033_50331302_5_dialog_content = "¡Yo también!",
  ui_story_5033_50331302_6_dialog_content = "Establecerse. No es...",
  ui_story_5033_50331302_7_dialog_content = "Da la casualidad de que necesito algunos guardias entrenados aquí mismo. Dios sabe si esa pandilla de matones aparecerá.",
  ui_story_5033_50331302_8_dialog_content = "Si pudieran quedarse aquí y vigilar las entradas y salidas, sería de gran ayuda.",
  ui_story_5033_50331302_9_dialog_content = "¡Impresionante! ¡¡Voy a reunir un grupo de trabajo especial de inmediato!!",
  ui_story_5033_50331302_10_dialog_content = "Algunas tablas más para clavar sobre las ventanas también serían maravillosas.",
  ui_story_5033_50331302_11_dialog_content = "roger ¡Vamos, Latán!",
  ui_story_5033_50331302_12_dialog_content = "¡Entendido!",
  ui_story_5033_50331302_13_dialog_content = "¿Seguro que está bien que los niños se queden aquí?",
  ui_story_5033_50331302_14_dialog_content = "De todos modos, es demasiado peligroso enviarlos a cualquier otro lugar ahora.",
  ui_story_5033_50331302_15_dialog_content = "Sin embargo, nunca he tenido tanta gente aquí a la vez, y no sé cuánto tiempo durarán nuestras provisiones.",
  ui_story_5033_50331302_16_dialog_content = "No te preocupes. Este asunto no debería llevar mucho tiempo.",
  ui_story_5033_50331302_17_dialog_content = "Gustavo. Estás aquí.",
  ui_story_5033_50331302_18_dialog_content = "Piense en algo, rápidamente, antes de que todo comience en la iglesia. Sabes todo sobre Euphoria, ¿verdad?",
  ui_story_5033_50331302_19_dialog_content = "Por lo que escuché, la situación es crítica.",
  ui_story_5033_50331302_20_dialog_content = "Muchos de los que rodean la iglesia son de una pandilla u otra. Todo lo que necesito hacer es ponerme en contacto con sus líderes, y debería poder resolver esto.",
  ui_story_5033_50331302_21_dialog_content = "Pero la pregunta clave es qué hacer con los civiles comunes.",
  ui_story_5033_50331302_22_dialog_content = "Ahora todos saben que Pollux está albergando a la gente de Umbraton en la iglesia. Me temo que eso requerirá más que unas pocas palabras bonitas para resolverlo.",
  ui_story_5033_50331302_23_dialog_content = "...",
  ui_story_5033_50331302_24_dialog_content = "Debes ser ese muchacho de Umbraton, ¿verdad?",
  ui_story_5033_50331302_25_dialog_content = "Supongo que Taki nunca te mencionó.",
  ui_story_5033_50331302_26_dialog_content = "Me dijo que vendrías, pero nunca mencionó el enorme dolor de cabeza que traerías contigo.",
  ui_story_5033_50331302_27_dialog_content = "Ahora toda Euphoria piensa que Shadowlord los envió aquí para destruir el lugar.",
  ui_story_5033_50331302_28_dialog_content = "¡Pero no hemos hecho nada!",
  ui_story_5033_50331302_29_dialog_content = "¡Hmph! Es un poco tarde para que digas eso ahora.",
  ui_story_5033_50331302_30_dialog_content = "Investigar es investigar, pero ¿realmente tenías que provocar a los lugareños e involucrarte con Raven's Blood?",
  ui_story_5033_50331302_31_dialog_content = "¿Tienes alguna idea de cuán antagonista suele ser Raven's Blood?",
  ui_story_5033_50331302_32_dialog_content = "El estatus de pandilla siempre se ha definido por la fuerza en Euphoria. No hicimos nada contra la norma.",
  ui_story_5033_50331302_33_dialog_content = "Te advertí hace mucho que no ofendieras a mucha gente, o te ganarás enemigos rencorosos. ¿Pero escuchaste?",
  ui_story_5033_50331302_34_dialog_content = "¡Y mira lo que ha pasado! Ahora todas las pandillas se han unido para acabar con ustedes, y no puedo detenerlos.",
  ui_story_5033_50331302_35_dialog_content = "Pollux es bastante inteligente, de alguna manera te saca mucho de allí. Hablando de eso, ¿dónde está ella?",
  ui_story_5033_50331302_36_dialog_content = "Se quedó en la iglesia para ganar algo de tiempo. De hecho, ¡tenemos que volver por ella ahora mismo!",
  ui_story_5033_50331302_37_dialog_content = "¡Vamos! ¡Puede que incluso ya estén peleando!",
  ui_story_5033_50331302_38_dialog_content = "Cálmate, Casta. Hay algo que necesito decirte primero...",
  ui_story_5033_50331302_39_dialog_content = "Un individuo muy peligroso está aquí en Euphoria.",
  ui_story_5033_50331302_40_dialog_content = "Sospecho que ella es la que ustedes dos vinieron a buscar aquí.",
  ui_story_5033_50331302_41_dialog_content = "¿Te refieres a esos casos...?",
  ui_story_5033_50331302_42_dialog_content = "¿Había una monja entre tus compañeros?",
  ui_story_5033_50331302_43_dialog_content = "Bueno, sí, pero ella se despidió hace un tiempo.",
  ui_story_5033_50331302_44_dialog_content = "No me digas...",
  ui_story_5033_50331302_45_dialog_content = "Ella mató a uno de mis vigías, en la iglesia. Ella está allí ahora mismo.",
  ui_story_5033_50331302_46_dialog_content = "¡¿Qué?!",
  ui_story_5033_50331302_47_dialog_content = "¡¿Me estás diciendo que ese asqueroso, el que mató a Matilda, está en la iglesia ahora mismo?!",
  ui_story_5033_50331302_48_dialog_content = "Sí. Tiene todas las mismas características que el caso Umbraton. Tiene que ser ella.",
  ui_story_5033_50331302_49_dialog_content = "Espera un segundo, ¿cómo sabes todo esto?",
  ui_story_5033_50331302_50_dialog_content = "La inteligencia es mi pan y mantequilla, muchacho.",
  ui_story_5033_50331302_51_dialog_content = "Eso no es todo lo que sé, tampoco. También sé un pequeño secreto que estoy seguro de que Pollux estaría muy interesado en...",
  ui_story_5033_50331302_52_dialog_content = "Esa \"monja\" no es sierva del dios de la luz.",
  ui_story_5033_50331302_53_dialog_content = "Ella y Pollux solían llamarse Géminis como miembros de la organización, y su nombre es <color=#FFB400>Antares</color>.",
  ui_story_5033_50331302_54_dialog_content = "¡¿Qué dijiste?!",
  ui_story_5033_50331302_55_dialog_content = "¡Esperar! ¿La persona de la que hablas no está muerta?",
  ui_story_5033_50331302_56_dialog_content = "¡Así es! Esto es imposible. Pólux tiene claramente...",
  ui_story_5033_50331302_57_dialog_content = "Estaba tan escéptico como usted cuando esta información llegó por primera vez a mis oídos. Pero te aseguro que es verdad.",
  ui_story_5033_50331302_58_dialog_content = "No solo sobrevivió, sino que ha estado reuniendo fuerzas durante años. Y ahora, ha decidido vengarse de Euphoria.",
  ui_story_5033_50331302_59_dialog_content = "¿Qué estamos esperando? ¡Pólux está destinado a estar en problemas!",
  ui_story_5033_50331302_60_dialog_content = "Sí... Si puede matar gente sin pestañear, no puedo pensar de qué más podría ser capaz...",
  ui_story_5033_50331302_61_dialog_content = "No podemos permitir que siga provocando problemas.",
  ui_story_5033_50331302_62_dialog_content = "¿Estás seguro de esto, Gustavo?",
  ui_story_5033_50331302_63_dialog_content = "Escucha, muchacho, te he dicho dónde encontrar a la persona que buscas. Si puedes atraparla o no, depende de ti.",
  ui_story_5033_50331302_64_dialog_content = "Eso explotó...",
  ui_story_5033_50331302_65_dialog_content = "¿Por qué no te vas con ellos, Gustav? Es posible que deba controlar la situación, ya que es difícil para ellos luchar contra Antares...",
  ui_story_5033_50331302_66_dialog_content = "Jajaja, no tienes que preocuparte de que me haga cargo de la situación. Déjamelo a mí.",
  ui_story_5033_50331302_67_dialog_content = "Solo enfócate en encontrar al asesino y revelar la verdad a todos.",
  ui_story_5033_50331302_68_dialog_content = "Intentaré ayudar a calmar el enfado que Euphoria siente hacia ti...",
  ui_story_5033_50331401_1_dialog_content = "<color=#e8d9bb>*Retumbar...*</color>",
  ui_story_5033_50331401_2_dialog_content = "¿Fue eso una explosión? ¿O un trueno?",
  ui_story_5033_50331401_3_dialog_content = "Acelera el paso, Caelestite. ¿Cómo eres más lento que estos viejos huesos?",
  ui_story_5033_50331401_4_dialog_content = "Lo siento mucho.",
  ui_story_5033_50331401_5_dialog_content = "Necesito hablar contigo, Casta.",
  ui_story_5033_50331401_6_dialog_content = "Sé lo que quieres decir.",
  ui_story_5033_50331401_7_dialog_content = "Ella tiene que morir.",
  ui_story_5033_50331401_8_dialog_content = "Tú...",
  ui_story_5033_50331401_9_dialog_content = "Casta, sé que tú y Pólux están furiosos por lo de Matilda.",
  ui_story_5033_50331401_10_dialog_content = "Pero no creo que esta sea una situación tan simple. ¿Alguna vez has pensado por qué ella está haciendo todo esto?",
  ui_story_5033_50331401_11_dialog_content = "Porque quiere vengarse de Pólux y de toda Euforia por su \"muerte\".",
  ui_story_5033_50331401_12_dialog_content = "Eso es posible. Pero ¿por qué ahora, después de tantos años?",
  ui_story_5033_50331401_13_dialog_content = "no puedo decir",
  ui_story_5033_50331401_14_dialog_content = "¿Por qué cometer tantos crímenes de alto perfil y luego ir a buscar a Pólux?",
  ui_story_5033_50331401_15_dialog_content = "No lo sé.",
  ui_story_5033_50331401_16_dialog_content = "Y por qué...",
  ui_story_5033_50331401_17_dialog_content = "<size=45>¡No lo sé y no quiero saberlo!</size>",
  ui_story_5033_50331401_18_dialog_content = "Pollux la había matado una vez, por lo que mató a la hermana Matilda, que había salvado a Pollux.",
  ui_story_5033_50331401_19_dialog_content = "Trae todas las sospechas a Pollux y luego regresa a Euphoria mientras sigues pistas.",
  ui_story_5033_50331401_20_dialog_content = "¿Es difícil entender que todo esto es para vengarse de Pólux?",
  ui_story_5033_50331401_21_dialog_content = "¡Cálmate primero y piensa en lo que haría Pólux!",
  ui_story_5033_50331401_22_dialog_content = "¡Pólux no cubriría a Antares!",
  ui_story_5033_50331401_23_dialog_content = "Ella haría exactamente lo que yo haría: ¡cortarla en pedazos!",
  ui_story_5033_50331401_24_dialog_content = "Casta!",
  ui_story_5033_50331401_25_dialog_content = "¡Oye, no comas eso! Escúpelo...",
  ui_story_5033_50331401_26_dialog_content = "<color=#e8d9bb>Ding-dong, Ding-dong—</color>",
  ui_story_5033_50331401_27_dialog_content = "Escucha, no debes comer esto, ¿entendido? Ahora corre y juega en otro lugar.",
  ui_story_5033_50331401_28_dialog_content = "Uf... Finalmente llegué a acomodar a los pequeños.",
  ui_story_5033_50331401_29_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_5033_50331401_30_dialog_content = "¿Quién es?",
  ui_story_5033_50331401_31_dialog_content = "¡Abre la puerta, rápido! ¡Soy Eho, agente especial de Umbraton Courier Union!",
  ui_story_5033_50331401_32_dialog_content = "¡Me has dado un susto de muerte! ¿Qué estás haciendo aquí? ¿Tienes mi paquete?",
  ui_story_5033_50331401_33_dialog_content = "Um, ¡entrega súper acelerada de Umbraton!",
  ui_story_5033_50331401_34_dialog_content = "Mantenlo bajo, ¿quieres? Dale aquí.",
  ui_story_5033_50331401_35_dialog_content = "<color=#e8d9bb>*Papel desplegado*</color>",
  ui_story_5033_50331401_36_dialog_content = "\"Este es Taki. No puedo contactar a Corax, así que estoy probando suerte contigo\".",
  ui_story_5033_50331401_37_dialog_content = "\"Una víctima sobrevivió al asesino en serie y está despierto. Tienes que decirle a Corax de inmediato...\"",
  ui_story_5033_50331401_38_dialog_content = "\"La sospechosa es una monja, con cabello y ojos grises. Las fotos están abajo...\"",
  ui_story_5033_50331401_39_dialog_content = "\"¡Pero ella no es la mente maestra! ¡Todavía hay alguien detrás de ella moviendo los hilos!\"",
  ui_story_5033_50331401_40_dialog_content = "¿Qué?",
  ui_story_5033_50331401_41_dialog_content = "<size=42>\"¡Es <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_42_dialog_content = "<size=42>\"¡Detrás de escena, todo es <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_43_dialog_content = "¿Expiación? ¿Cuota? ¿Qué haces exactamente aquí...?",
  ui_story_5033_50331401_44_dialog_content = "Solo estoy aquí porque quería decirte que descubrí quién está moviendo los hilos detrás de todo esto.",
  ui_story_5033_50331401_45_dialog_content = "Espera a que termine con él y te devolveré la vida.",
  ui_story_5033_50331401_46_dialog_content = "Te debo esto.",
  ui_story_5033_50331401_47_dialog_content = "¡No lo necesito! Te entregaré a Umbraton.",
  ui_story_5033_50331401_48_dialog_content = "Me temo que eso no servirá... No quiero morir a manos de nadie más que de las tuyas.",
  ui_story_5033_50331401_49_dialog_content = "¿Estás loco?",
  ui_story_5033_50331401_50_dialog_content = "¡Porque?, si! He estado loco durante mucho tiempo.",
  ui_story_5033_50331401_51_dialog_content = "Desde que nací hijo de Euphoria... Desde que me uní a esa organización...",
  ui_story_5033_50331401_52_dialog_content = "En lo que a mí respecta, matar es tan natural como respirar.",
  ui_story_5033_50331401_53_dialog_content = "Nunca había estado realmente despierto.",
  ui_story_5033_50331401_54_dialog_content = "Hasta que encontré a mi primer amigo... Fuiste como mi estrella guía, mostrándome el camino...",
  ui_story_5033_50331401_55_dialog_content = "¡Ciérralo! En el momento en que mataste a la hermana Matilda, perdimos cualquier oportunidad de ser amigos.",
  ui_story_5033_50331401_56_dialog_content = "No... En el momento en que levanté mi cuchillo hacia ti, no eras mi amigo.",
  ui_story_5033_50331401_57_dialog_content = "¡No, Pólux, eso fue culpa de la organización! Gustav tiene la culpa de todo...",
  ui_story_5033_50331401_58_dialog_content = "Todo habrá terminado, mientras ellos se hayan ido.",
  ui_story_5033_50331401_59_dialog_content = "<size=45>¿Gustav?!</size>",
  ui_story_5033_50331401_60_dialog_content = "Sí. Como dije, finalmente descubrí quién está moviendo los hilos detrás de escena.",
  ui_story_5033_50331401_61_dialog_content = "Gustav... Era parte de la organización y una vez fue la mano derecha del Jefe.",
  ui_story_5033_50331401_62_dialog_content = "¿Él es realmente un miembro?",
  ui_story_5033_50331401_63_dialog_content = "¿Tienes alguna prueba?",
  ui_story_5033_50331401_64_dialog_content = "Lamento decir que no.",
  ui_story_5033_50331401_65_dialog_content = "Todo es testimonio oído de boca de hombres moribundos.",
  ui_story_5033_50331401_66_dialog_content = "<color=#e8d9bb>Choque—</color>",
  ui_story_5033_50331401_67_dialog_content = "<size=45>¡¡De verdad estás aquí, Antares!!</size>",
  ui_story_5033_50331401_68_dialog_content = "Oh...",
  ui_story_5033_50331401_69_dialog_content = "Pólux, ¿estás bien?",
  ui_story_5033_50331401_70_dialog_content = "Estoy bien. ¿Qué pasa con los niños? ¿Los conseguiste a salvo?",
  ui_story_5033_50331401_71_dialog_content = "¡Esta mujer no es una monja! ¡Ella asesinó a la hermana Matilda!",
  ui_story_5033_50331401_72_dialog_content = "¡Si no la vengas tú, lo haré yo!",
  ui_story_5033_50331401_73_dialog_content = "*Tose*",
  ui_story_5033_50331401_74_dialog_content = "<size=45>¡¡Mataste a Matilda...!!</size>",
  ui_story_5033_50331401_75_dialog_content = "Casta, tú...",
  ui_story_5033_50331401_76_dialog_content = "Está bien, Pólux. Ella es realmente una niña muy prometedora...",
  ui_story_5033_50331401_77_dialog_content = "<size=45>¿Dónde está tu arma? ¡Dibujalo ahora!</size>",
  ui_story_5033_50331401_78_dialog_content = "<size=45>¡Te haré pagar... por Matilda!</size>",
  ui_story_5033_50331401_79_dialog_content = "¿Viste... viste eso? ¡Fue tan rápido que se estrelló contra la pared!",
  ui_story_5033_50331401_80_dialog_content = "¡Mirar! ¡Gustavo está aquí!",
  ui_story_5033_50331401_81_dialog_content = "Siento llegar tarde, todos.",
  ui_story_5033_50331401_82_dialog_content = "¡Gustavo, señor! ¡Díganos qué hacer, por favor! Pollux tiene esa escoria de Umbraton...",
  ui_story_5033_50331401_83_dialog_content = "Todos, cálmense. Te lo explicaré todo en un rato.",
  ui_story_5033_50331401_84_dialog_content = "Pero antes de eso, deja pasar a estos tipos.",
  ui_story_5033_50331401_85_dialog_content = "...",
  ui_story_5033_50331401_86_dialog_content = "¿Eh? ¡¿EH?!",
  ui_story_5033_50331401_87_dialog_content = "¿Qué estás haciendo aquí? ¿Cuándo apareciste?",
  ui_story_5033_50331401_88_dialog_content = "Tenemos que llegar a la iglesia, PlayerName! ¡Casta está perdiendo el control!",
  ui_story_5033_50331401_89_dialog_content = "<color=#e8d9bb>¡Bang, Bang!</color>",
  ui_story_5033_50331401_90_dialog_content = "Casta... Ese es tu nombre, ¿verdad?",
  ui_story_5033_50331401_91_dialog_content = "<size=45>¡Lucha! ¿A quién crees que estás menospreciando? ¡Contraataque!</size>",
  ui_story_5033_50331401_92_dialog_content = "Todavía necesito tiempo para terminar las cosas, así que me temo que no puedo perecer aquí. Pero nunca levantaré mi mano contra ti...",
  ui_story_5033_50331401_93_dialog_content = "Ya que eres importante para Pollux...",
  ui_story_5033_50331401_94_dialog_content = "...",
  ui_story_5033_50331401_95_dialog_content = "¡NO puedes pronunciar ese nombre, asesino!",
  ui_story_5033_50331401_96_dialog_content = "¡PARA, Casta!",
  ui_story_5033_50331401_97_dialog_content = "<size=45>¡Fuera de aquí!</size>",
  ui_story_5033_50331401_98_dialog_content = "No dejaré que saboteéis mi misión... ¡Éste es el decreto supremo del Señor de las Sombras!",
  ui_story_5033_50331401_99_dialog_content = "¡Debe ser devuelta con vida!",
  ui_story_5033_50331401_100_dialog_content = "<size=45>¡¡Dije FUERA DE AQUÍ!!</size>",
  ui_story_5033_50331401_101_dialog_content = "Ayúdame a tenerla bajo control, PlayerName!",
  ui_story_5033_50331402_1_dialog_content = "<color=#e8d9bb>¡Zumbido! ¡Pum!</color>",
  ui_story_5033_50331402_2_dialog_content = "Canalla...",
  ui_story_5033_50331402_3_dialog_content = "Lo siento. Tuve que luchar seriamente para detenerte.",
  ui_story_5033_50331402_4_dialog_content = "¡Asesino! ¡Aqui! ¡El asesino está aquí!",
  ui_story_5033_50331402_5_dialog_content = "Ya es suficiente, Casta.",
  ui_story_5033_50331402_6_dialog_content = "¿Calmado?",
  ui_story_5033_50331402_7_dialog_content = "Pólux, ella mató a Matilda...",
  ui_story_5033_50331402_8_dialog_content = "Lo se.",
  ui_story_5033_50331402_9_dialog_content = "Ella mató a Matilde...",
  ui_story_5033_50331402_10_dialog_content = "Y la vengaré, pero no hoy.",
  ui_story_5033_50331402_11_dialog_content = "Sí, expiaré... Una vez que todo esto termine.",
  ui_story_5033_50331402_12_dialog_content = "Si alguien va a quitarle la vida a Anne, seré yo. ¿Lo entiendes?",
  ui_story_5033_50331402_13_dialog_content = "Nos entendemos, ella y yo.",
  ui_story_5033_50331402_14_dialog_content = "Pólux...",
  ui_story_5033_50331402_15_dialog_content = "Ana, no, Antares.",
  ui_story_5033_50331402_16_dialog_content = "Nos encontremos de nuevo, PlayerName, Corax.",
  ui_story_5033_50331402_17_dialog_content = "¿Todas esas cosas fueron obra tuya, Antares?",
  ui_story_5033_50331402_18_dialog_content = "¿Eres responsable de la muerte de la hermana Matilda?",
  ui_story_5033_50331402_19_dialog_content = "Parece que lo tienes todo resuelto.",
  ui_story_5033_50331402_20_dialog_content = "Así es, yo soy el que estás buscando.",
  ui_story_5033_50331402_21_dialog_content = "Odio decírtelo, pero tampoco soy una monja. Mis disculpas por engañarte.",
  ui_story_5033_50331402_22_dialog_content = "Por qué... ¿Por qué mataste a esa gente? ¿Y por qué viniste aquí?",
  ui_story_5033_50331402_23_dialog_content = "<tamaño=42>¡¿Qué?! ¿En serio?</tamaño>",
  ui_story_5033_50331402_24_dialog_content = "¿Por qué esa gente está haciendo un alboroto de nuevo? ¿No estaba destinado Gustav a tener el control?",
  ui_story_5033_50331402_25_dialog_content = "Espera, ¿lo has visto?",
  ui_story_5033_50331402_26_dialog_content = "Sí, vino con nosotros.",
  ui_story_5033_50331402_27_dialog_content = "Entonces, ¿dónde está él ahora?",
  ui_story_5033_50331402_28_dialog_content = "No sé. No entró con nosotros.",
  ui_story_5033_50331402_29_dialog_content = "¡Es peligroso! ¡Él es el cerebro detrás de todo esto!",
  ui_story_5033_50331402_30_dialog_content = "¿Qué? ¿Cerebro?",
  ui_story_5033_50331402_31_dialog_content = "Puedo explicarlo, Pólux.",
  ui_story_5033_50331402_32_dialog_content = "¿Lo que dices es en serio, Gustav?",
  ui_story_5033_50331402_33_dialog_content = "Así es. Ella es la amiga más cercana de Pollux... Antares.",
  ui_story_5033_50331402_34_dialog_content = "Debe ser horrible, asociarse con alguien así... ¿Por qué haría esto, de todos modos?",
  ui_story_5033_50331402_35_dialog_content = "¡¿Por qué provocar deliberadamente problemas con Umbraton?!",
  ui_story_5033_50331402_36_dialog_content = "Debe estar usándolo como pretexto para hacerse cargo de las cadenas de ganancias de Euphoria y Umbraton.",
  ui_story_5033_50331402_37_dialog_content = "Incluyendo a esos investigadores de Umbraton, probablemente solo estén haciendo una demostración.",
  ui_story_5033_50331402_38_dialog_content = "No me sorprendería si todo en Euphoria ya tiene un precio y está disponible.",
  ui_story_5033_50331402_39_dialog_content = "Pero, ¿cómo es que están peleando aquí? ¿Es algún tipo de lucha interna?",
  ui_story_5033_50331402_40_dialog_content = "Disculpen, todos. Lo siento, pero debo hablar con el Sr. Gustav.",
  ui_story_5033_50331402_41_dialog_content = "¿Entonces?",
  ui_story_5033_50331402_42_dialog_content = "Ni Pollux ni Casta han podido hacerse cargo de Antares.",
  ui_story_5033_50331402_43_dialog_content = "¿Son incapaces de hacerlo? O solo retrasado?",
  ui_story_5033_50331402_44_dialog_content = "Lo siento, no puedo decirlo con certeza.",
  ui_story_5033_50331402_45_dialog_content = "Imposible... Ese nivel de odio y animosidad... ¿Cómo podría ser... Estás seguro de esto?",
  ui_story_5033_50331402_46_dialog_content = "Por lo menos, Antares sigue vivo y...",
  ui_story_5033_50331402_47_dialog_content = "Seguir.",
  ui_story_5033_50331402_48_dialog_content = "Ella parece haberles contado todo.",
  ui_story_5033_50331402_49_dialog_content = "Parece que las cosas no pueden empeorar mucho...",
  ui_story_5033_50331402_50_dialog_content = "Entonces, ¿cuál es nuestro próximo movimiento?",
  ui_story_5033_50331402_51_dialog_content = "Próximo movimiento...",
  ui_story_5033_50331402_52_dialog_content = "<color=#e8d9bb>*Retumbar—*</color>",
  ui_story_5033_50331402_53_dialog_content = "Solo sé cuál será nuestro último movimiento.",
  ui_story_5033_50331402_54_dialog_content = "Dígales a todos que es hora de hacer esto.",
  ui_story_5033_50331402_55_dialog_content = "Si no nos ocupamos de Raven's Blood aquí y ahora, entonces Euphoria nunca verá un día de paz.",
  ui_story_5033_50331501_1_dialog_content = "¡Pólux! ¡Ven aquí! ¡Traidor de Euforia!",
  ui_story_5033_50331501_2_dialog_content = "¡Pólux! ¡PÓLUX!",
  ui_story_5033_50331501_3_dialog_content = "Correos...",
  ui_story_5033_50331501_4_dialog_content = "¡Guau! Ella... Ella realmente salió...",
  ui_story_5033_50331501_5_dialog_content = "¿Quién me llama?",
  ui_story_5033_50331501_6_dialog_content = "...",
  ui_story_5033_50331501_7_dialog_content = "¿Qué, finalmente te atreves a mostrar tu cara?",
  ui_story_5033_50331501_8_dialog_content = "Tienes buen aspecto, Gustav. Supongo que tus gin-tonics diarios son de agradecer.",
  ui_story_5033_50331501_9_dialog_content = "Realmente no. Son solo para adormecerme, ya que este Euphoria ya ofrece muchas decepciones, ¿no?",
  ui_story_5033_50331501_10_dialog_content = "No corriste. Más bien admiro eso.",
  ui_story_5033_50331501_11_dialog_content = "¿Y por qué iba a correr? Estoy aquí para encargarme de todo. Después de todo, Euphoria necesita a alguien que pueda hacerse cargo.",
  ui_story_5033_50331501_12_dialog_content = "<color=#e8d9bb>Papá, pa—</color>",
  ui_story_5033_50331501_13_dialog_content = "Oye, ¿es la monja?",
  ui_story_5033_50331501_14_dialog_content = "G-Vuelve, Gustav dice que es una maníaca...",
  ui_story_5033_50331501_15_dialog_content = "Todos, permítanme presentarles a alguien.",
  ui_story_5033_50331501_16_dialog_content = "Asesino en serie de Umbraton, pecador de Euphoria y ex miembro de la organización, Gemini—Antares.",
  ui_story_5033_50331501_17_dialog_content = "...",
  ui_story_5033_50331501_18_dialog_content = "¿Qué? ¿Fácilmente confesado?",
  ui_story_5033_50331501_19_dialog_content = "Eso es Pollux para ti, comportándose admirablemente incluso en una situación tan desesperada.",
  ui_story_5033_50331501_20_dialog_content = "¿Y usted? Como el cerebro detrás de todo esto, será más fácil si lo confiesas también.",
  ui_story_5033_50331501_21_dialog_content = "Parece que tienes toda la historia escrita, Gustav.",
  ui_story_5033_50331501_22_dialog_content = "Es una pena entonces que mi prisionero aquí tenga una confesión diferente. ¿Te gustaría escuchar?",
  ui_story_5033_50331501_23_dialog_content = "¡Honorable pueblo de Euforia! ¿Quieres saber la verdad?",
  ui_story_5033_50331501_24_dialog_content = "Este caballero que tienes delante, Gustav, no es solo el sabelotodo de Euphoria...",
  ui_story_5033_50331501_25_dialog_content = "También es un ex funcionario de alto rango en la organización.",
  ui_story_5033_50331501_26_dialog_content = "¿Organización? ¿Significa eso la... organización que el Jefe manejó hace más de una década?",
  ui_story_5033_50331501_27_dialog_content = "¿No era ese un grupo para criar asesinos? Gustav es solo un agente de inteligencia normal, ¿verdad?",
  ui_story_5033_50331501_28_dialog_content = "La organización se vino abajo hace doce años, gracias a la invasión de Eclipsite. Pero para Gustav aquí presente, esta era una oportunidad de oro.",
  ui_story_5033_50331501_29_dialog_content = "Usando su identidad de Casa de Inteligencia, comenzó a cortejar y ganarse a las pandillas, y a restablecer el orden, en un intento de apoderarse gradualmente de Euphoria.",
  ui_story_5033_50331501_30_dialog_content = "Pero lo más importante, también tenía en sus manos un arma letal...",
  ui_story_5033_50331501_31_dialog_content = "<color=#FFB400>Antares</color>.",
  ui_story_5033_50331501_32_dialog_content = "¿Qué? ¿La monja trabaja para Gustav?",
  ui_story_5033_50331501_33_dialog_content = "Durante los últimos años, Antares ha estado ejecutando sus órdenes, eliminando a cualquiera que todavía tuviera el control de las cadenas de ganancias de Euphoria.",
  ui_story_5033_50331501_34_dialog_content = "La ira de Umbraton necesitaba un chivo expiatorio, por lo que su orden final fue que Anne volviera aquí para matarme...",
  ui_story_5033_50331501_35_dialog_content = "O más bien, que nos matemos unos a otros.",
  ui_story_5033_50331501_36_dialog_content = "Hmm... Puedo ver un poco cómo eso tiene sentido.",
  ui_story_5033_50331501_37_dialog_content = "¡No no! ¡Solo tenemos su palabra!",
  ui_story_5033_50331501_38_dialog_content = "Pero Gustav es el mismo, ¿no? Tampoco deberíamos creerle ciegamente, solo porque dirige la Casa de Inteligencia...",
  ui_story_5033_50331501_39_dialog_content = "Joder... ¿Realmente nos han engañado a todos?",
  ui_story_5033_50331501_40_dialog_content = "<size=45>¡Pólux! ¡Suficiente!</tamaño>",
  ui_story_5033_50331501_41_dialog_content = "¡Estas buenas personas no son tontas! No serán engañados por tus mentiras.",
  ui_story_5033_50331501_42_dialog_content = "Solo quieres tirarme debajo del autobús y hacerme asumir la culpa de haber sido el autor intelectual de todo esto.",
  ui_story_5033_50331501_43_dialog_content = "Usted sabe completamente lo que ha hecho y pagará por ello, ¡incluso sin pruebas contundentes!",
  ui_story_5033_50331501_44_dialog_content = "Escuche lo que está diciendo, hermana. Me siento avergonzado por ti.",
  ui_story_5033_50331501_45_dialog_content = "Si tienes la espalda contra la pared y al final quieres matarme a mí, un anciano, ¡entonces ven a por mí!",
  ui_story_5033_50331501_46_dialog_content = "Pero no huiré si puedes presentar aunque sea una pizca de prueba.",
  ui_story_5033_50331501_47_dialog_content = "<size=45>¡Tengo pruebas!</size>",
  ui_story_5033_50331501_48_dialog_content = "¡Tengo pruebas! ¡Aquí mismo!",
  ui_story_5033_50331501_49_dialog_content = "¿Nekoyashiki?",
  ui_story_5033_50331501_50_dialog_content = "¡¿...?!",
  ui_story_5033_50331501_51_dialog_content = "¡Hazte a un lado! ¡Todos ustedes, fuera de mi camino!",
  ui_story_5033_50331501_52_dialog_content = "¿Quieres pruebas, Gustav? ¡Tengo tu prueba aquí mismo!",
  ui_story_5033_50331501_53_dialog_content = "¡Esto acaba de llegar de Umbraton, el testimonio de un sobreviviente!",
  ui_story_5033_50331501_54_dialog_content = "¡¿Un sobreviviente?!",
  ui_story_5033_50331501_55_dialog_content = "...",
  ui_story_5033_50331501_56_dialog_content = "La asesina era una monja, ¡ella! Y el que lo arregló todo, lo planeó todo—",
  ui_story_5033_50331501_57_dialog_content = "<size=45>¡Nada más que tú, Gustav!</size>",
  ui_story_5033_50331501_58_dialog_content = "De ninguna manera... Imposible... ¡No hay forma de que alguien pueda sobrevivir a eso!",
  ui_story_5033_50331501_59_dialog_content = "¡Esta es una evidencia falsa!",
  ui_story_5033_50331501_60_dialog_content = "¡Esta es información falsa! ¡¿Todos se están juntando para vencerme, verdad?!",
  ui_story_5033_50331501_61_dialog_content = "\"Jimmy Odenkirk, 47 años, despertó de un coma grave...\"",
  ui_story_5033_50331501_62_dialog_content = "\"... Según su descripción, la sospechosa estaba vestida de monja, con cabello gris...\"",
  ui_story_5033_50331501_63_dialog_content = "Suficiente...",
  ui_story_5033_50331501_64_dialog_content = "\"Fui invitado allí ese día por Gustav de Euforia... Entramos en una trampa, y ninguno de mis hombres logró salir...\"",
  ui_story_5033_50331501_65_dialog_content = "¡¡SUFICIENTE!! ¡¡No necesito escuchar estas tonterías calumniosas!!",
  ui_story_5033_50331501_66_dialog_content = "Si todavía no lo admites, ¡presentemos nuestros casos ante el Señor de las Sombras!",
  ui_story_5033_50331501_67_dialog_content = "¡Veamos qué excusas se les ocurren a ustedes dos villanos entonces!",
  ui_story_5033_50331501_68_dialog_content = "¡No tengo tiempo para complacer tus tonterías! ¡No te quedes ahí parado, agarra a Nekoyashiki y a los otros traidores!",
  ui_story_5033_50331501_69_dialog_content = "Uhh...",
  ui_story_5033_50331501_70_dialog_content = "¿Escuchaste lo que dije?",
  ui_story_5033_50331501_71_dialog_content = "¿Lo que estás diciendo es en serio, Nekoyashiki?",
  ui_story_5033_50331501_72_dialog_content = "Tal vez sea mejor esperar y ver, no ser tan rápido para sacar conclusiones precipitadas... Las cosas son demasiado fluidas...",
  ui_story_5033_50331501_73_dialog_content = "Rápido, mira la horrible expresión de Gustav...",
  ui_story_5033_50331501_74_dialog_content = "Cuál es el significado de este...",
  ui_story_5033_50331501_75_dialog_content = "¡Maldito inútil de inútiles! ¿Has olvidado quién es tu jefe?",
  ui_story_5033_50331501_76_dialog_content = "¿Olvidaste el daño que Umbraton infligió en este lugar?",
  ui_story_5033_50331501_77_dialog_content = "¿Qué está diciendo este tipo? ¡No hay manera de que él sea el jefe de nosotros!",
  ui_story_5033_50331501_78_dialog_content = "¡Oye, Gustavo! ¡Será mejor que nos des una buena explicación! ¿Qué está pasando?",
  ui_story_5033_50331501_79_dialog_content = "Y todos sus pequeños secuaces también, ¿están todos juntos en esto?",
  ui_story_5033_50331501_80_dialog_content = "¡No no! No es asunto mío... ¡No tengo nada que ver con él!",
  ui_story_5033_50331501_81_dialog_content = "Jeje... ¡Jajaja!",
  ui_story_5033_50331501_82_dialog_content = "Muy bien. Ustedes se han buscado esto.",
  ui_story_5033_50331501_83_dialog_content = "¡Me has obligado a hacer esto!",
  ui_story_5033_50331501_84_dialog_content = "<color=#e8d9bb>Clang... Tintineo...</color>",
  ui_story_5033_50331501_85_dialog_content = "¿Eh? ¿Ese es Darkflow...?",
  ui_story_5033_50331501_86_dialog_content = "<anim type=Shake><size=45>¡Graaaagh!</size></anim>",
  ui_story_5033_50331501_87_dialog_content = "¡Oh, no! ¡Eclipsitos!",
  ui_story_5033_50331501_88_dialog_content = "¡Vamos! Corre como quieras... ¡Llama a tus amigos y haz algunas travesuras!",
  ui_story_5033_50331501_89_dialog_content = "<anim type=Shake><size=45>¡Graaaagh—!</size></anim>",
  ui_story_5033_50331501_90_dialog_content = "¡Eclipsitos! ¡Eclipsitos por todas partes!",
  ui_story_5033_50331501_91_dialog_content = "¡Maldiciones! ¿Cómo lograron rodearnos? ¡No hay manera de salir!",
  ui_story_5033_50331501_92_dialog_content = "Tú... ¡Alimañas! ¿Dejaste salir a los Eclipsites? ¡Simplemente van a atraer más!",
  ui_story_5033_50331501_93_dialog_content = "¡N-No te acerques más! Uraaaagh!!",
  ui_story_5033_50331501_94_dialog_content = "Gustavo! ¡Salvanos!",
  ui_story_5033_50331501_95_dialog_content = "Lo siento mucho, todos. Deja que Euforia...",
  ui_story_5033_50331501_96_dialog_content = "Sé limpio.",
  ui_story_5033_50331502_1_dialog_content = "¡Argh! ¡Ayuda! ¡¡Sálvame!!",
  ui_story_5033_50331502_2_dialog_content = "¡Mis piernas! ¡No puedo moverme!",
  ui_story_5033_50331502_3_dialog_content = "Deja de gritar. Es solo una herida superficial.",
  ui_story_5033_50331502_4_dialog_content = "No hay eclipses por aquí. Sólo ve a buscar a tu compañero.",
  ui_story_5033_50331502_5_dialog_content = "Vale, vale... Gracias...",
  ui_story_5033_50331502_6_dialog_content = "Si quieres agradecer a alguien, agradece a Pollux. Casi quemaste la iglesia y aún así ella está dispuesta a tomarse la molestia de salvarte.",
  ui_story_5033_50331502_7_dialog_content = "Corax! ¡A tu izquierda!",
  ui_story_5033_50331502_8_dialog_content = "¡Maldita sea! ¡¿Cómo siguen viniendo?!",
  ui_story_5033_50331502_9_dialog_content = "No sé. ¿Quizás algunos eclipses locales también se sientan atraídos?",
  ui_story_5033_50331502_10_dialog_content = "¿Y Antarés? ¿La has visto?",
  ui_story_5033_50331502_11_dialog_content = "¡Déjame buscarla con mi habilidad psíquica! ¡Es un caos total por aquí!",
  ui_story_5033_50331502_12_dialog_content = "¡Oye! ¿Has visto a Pólux?",
  ui_story_5033_50331502_13_dialog_content = "No... También estamos buscando...",
  ui_story_5033_50331502_14_dialog_content = "¡La acabo de ver al otro lado de la iglesia! ¡Por ahí!",
  ui_story_5033_50331502_15_dialog_content = "¿Y Gustavo? No podría haber escapado, ¿verdad?",
  ui_story_5033_50331502_16_dialog_content = "¡Hola, Gustavo! ¡Espera!",
  ui_story_5033_50331502_17_dialog_content = "¡Mover! Fuera de mi camino...",
  ui_story_5033_50331502_18_dialog_content = "<anim type=Shake><size=45>¡Graaaagh...!</size></anim>",
  ui_story_5033_50331502_19_dialog_content = "¡Urgh!",
  ui_story_5033_50331502_20_dialog_content = "Antarés.",
  ui_story_5033_50331502_21_dialog_content = "¿Dejaste salir estos eclipses, Gustav?",
  ui_story_5033_50331502_22_dialog_content = "¿Quieres que todos mueran contigo?",
  ui_story_5033_50331502_23_dialog_content = "¿Qué, me estás diciendo que te compadeces de estos tipos?",
  ui_story_5033_50331502_24_dialog_content = "¿Lástima? Lo siento, pero no podría importarme menos sus vidas.",
  ui_story_5033_50331502_25_dialog_content = "Eres realmente despiadado, Antares. Y verdaderamente digno de ser uno de los Géminis...",
  ui_story_5033_50331502_26_dialog_content = "Pero estoy particularmente desconcertado por tus acciones en este momento.",
  ui_story_5033_50331502_27_dialog_content = "¿Realmente todavía tienes esperanza de redención?",
  ui_story_5033_50331502_28_dialog_content = "¿No puedes pensar que puedes ser perdonado por nombrarme públicamente y predicar lo que sea que llames justicia?",
  ui_story_5033_50331502_29_dialog_content = "... Oh, no. Por supuesto que no.",
  ui_story_5033_50331502_30_dialog_content = "¡Vas a pagar por esto! ¡Y tú solo!",
  ui_story_5033_50331502_31_dialog_content = "TODO lo que he hecho ha sido por Euphoria... ¡No entiendes, no puedes comprender!",
  ui_story_5033_50331502_32_dialog_content = "¡Todo lo que tienes son esas tediosas y triviales amistades y vínculos! ¡No puedes ver lo que yo veo!",
  ui_story_5033_50331502_33_dialog_content = "¡La euforia ha sido un desastre total durante doce años, Antares!",
  ui_story_5033_50331502_34_dialog_content = "¡A esos muchachos de Umbraton no les importa si vivimos o morimos, mientras que los lugareños ni siquiera tienen el coraje o la fuerza para reconstruir!",
  ui_story_5033_50331502_35_dialog_content = "¡Solo estoy yo! ¡Sabes, soy el único que puede dar un paso al frente!",
  ui_story_5033_50331502_36_dialog_content = "Para restaurar una extremidad enferma, uno debe extirpar la carne podrida y sacar los gusanos...",
  ui_story_5033_50331502_37_dialog_content = "Y tú, Antares, eres mi bisturí. Una excelente herramienta para extirpar...",
  ui_story_5033_50331502_38_dialog_content = "Después de hoy, Euphoria también puede renacer.",
  ui_story_5033_50331502_39_dialog_content = "Es solo que ninguno de nosotros puede verlo.",
  ui_story_5033_50331502_40_dialog_content = "...",
  ui_story_5033_50331502_41_dialog_content = "<color=#e8d9bb>Clink—</color>",
  ui_story_5033_50331502_42_dialog_content = "Baja tu arma, Gustav. Tal como están las cosas, no tienes oportunidad.",
  ui_story_5033_50331502_43_dialog_content = "Aquí estás por fin, Pólux. Este es realmente un... desarrollo afortunado.",
  ui_story_5033_50331502_44_dialog_content = "Ya es hora de que salgas de tu pequeña y acogedora iglesia a las calles cubiertas de cadáveres.",
  ui_story_5033_50331502_45_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_5033_50331502_46_dialog_content = "Jajaja...",
  ui_story_5033_50331502_47_dialog_content = "No vendas este lugar, Pollux, no lo vendas.",
  ui_story_5033_50331502_48_dialog_content = "Si de verdad quieres...",
  ui_story_5033_50331502_49_dialog_content = "Al menos conseguir un buen precio por ello.",
  ui_story_5033_50331502_50_dialog_content = "¿Qué estás planeando, Gustavo?",
  ui_story_5033_50331502_51_dialog_content = "No quisiera molestarte... ¡Puedo acabar con esto yo mismo!",
  ui_story_5033_50331502_52_dialog_content = "No moriré en la ignominia como el Jefe... Nunca...",
  ui_story_5033_50331502_53_dialog_content = "¡Urgh!",
  ui_story_5033_50331502_54_dialog_content = "Se mató.",
  ui_story_5033_50331502_55_dialog_content = "Tenía otros planes para él. Se bajó a la ligera.",
  ui_story_5033_50331502_56_dialog_content = "Mantenga esos planes en su bolsillo por ahora. Guárdalos para <color=#FFB400>otros</color>.",
  ui_story_5033_50331502_57_dialog_content = "¿Otros?",
  ui_story_5033_50331502_58_dialog_content = "Pólux, ¿ves a esa gente de ahí abajo sosteniendo antorchas y cargando molotovs?",
  ui_story_5033_50331502_59_dialog_content = "No puedo ver sus caras claramente. Para mí, todos se ven iguales: horribles, tontos y sin esperanza.",
  ui_story_5033_50331502_60_dialog_content = "Ana, se acabó. Está terminado. Solo necesitas volver a Umbraton y enfrentar tu destino, entonces...",
  ui_story_5033_50331502_61_dialog_content = "Una cosa que dijo Gustav tenía sentido.",
  ui_story_5033_50331502_62_dialog_content = "Todos somos partes supurantes de Euphoria, heridas sucias que nunca sanarán por completo.",
  ui_story_5033_50331502_63_dialog_content = "Solo eliminando estas partes podridas puede renacer realmente.",
  ui_story_5033_50331502_64_dialog_content = "¿Qué es lo que quieres hacer?",
  ui_story_5033_50331502_65_dialog_content = "Cumplir mi misión como Grim Reaper.",
  ui_story_5033_50331502_66_dialog_content = "Oh no, entonces nosotros... ¡Sálvanos! ¡Correr!",
  ui_story_5033_50331502_67_dialog_content = "Antarés!",
  ui_story_5033_50331502_68_dialog_content = "Tu corazón es tan suave como siempre, Pólux. Por eso digo que no has cambiado, incluso después de todos estos años.",
  ui_story_5033_50331502_69_dialog_content = "Pero una enfermedad grave necesita una medicina potente.",
  ui_story_5033_50331502_70_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5033_50331502_71_dialog_content = "¡¿Qué es eso de volar bien para nosotros?! Ponerse a cubierto-!",
  ui_story_5033_50331502_72_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5033_50331502_73_dialog_content = "Loca... ¡¿Cómo puedes involucrar a civiles inocentes?!",
  ui_story_5033_50331502_74_dialog_content = "Casta! ¡Ayuda! ¡Detén a esta monja, rápido!",
  ui_story_5033_50331502_75_dialog_content = "¡Pólux! ¡Hacer algo!",
  ui_story_5033_50331502_76_dialog_content = "Yo...",
  ui_story_5033_50331502_77_dialog_content = "Ana, sé lo que estás haciendo. Pero esto no... No hay necesidad de esto.",
  ui_story_5033_50331502_78_dialog_content = "Teniamos un trato.",
  ui_story_5033_50331502_79_dialog_content = "También escuchó la evidencia férrea que ese caballero presentó públicamente hace un momento...",
  ui_story_5033_50331502_80_dialog_content = "Incluso si no tuviera interés en limpiar Euphoria, todavía no podría dejar que estos testigos vivieran.",
  ui_story_5033_50331502_81_dialog_content = "Cállate, Anne... Solo detente...",
  ui_story_5033_50331502_82_dialog_content = "Y voy a empezar con la persona más cercana a mí.",
  ui_story_5033_50331502_83_dialog_content = "¡Argh! ¡Atrás! ¡Volver!",
  ui_story_5033_50331502_84_dialog_content = "También eres el único que puede detenerme.",
  ui_story_5033_50331502_85_dialog_content = "¿Listo?",
  ui_story_5033_50331502_86_dialog_content = "¡¿Realmente tienes que hacer esto?!",
  ui_story_5033_50331502_87_dialog_content = "<size=30>No dejaré que me lleves, Pólux. Deseo quedarme en Euphoria, aunque a mi manera.</size>",
  ui_story_5033_50331502_88_dialog_content = "<size=30>En el único camino que me queda, para expiar mis pecados.</size>",
  ui_story_5033_50331502_89_dialog_content = "...",
  ui_story_5033_50331502_90_dialog_content = "¡Eso es suficiente!",
  ui_story_5033_50331502_91_dialog_content = "No tengo nada parecido a grandes ideales, Anne.",
  ui_story_5033_50331502_92_dialog_content = "Esto es solo para Matilda.",
  ui_story_5033_50331502_93_dialog_content = "Por supuesto, esto también es para Matilda.",
  ui_story_5033_50331502_94_dialog_content = "¡Golpéala, Pólux! ¡Por Euforia!",
  ui_story_5033_50331502_95_dialog_content = "¡Por Euforia! ¡Euforia!",
  ui_story_5033_50331502_96_dialog_content = "Empecemos. Espero que todavía lo tengas.",
  ui_story_5033_50331502_97_dialog_content = "No te preocupes, recuerdo lo esencial. Esos que nunca olvidaré...",
  ui_story_5033_50331502_98_dialog_content = "Todavía tengo una pregunta final, Anne.",
  ui_story_5033_50331502_99_dialog_content = "je. Pedir.",
  ui_story_5033_50331502_100_dialog_content = "Si tuvieras una segunda oportunidad, ¿la seguirías haciendo?",
  ui_story_5033_50331502_101_dialog_content = "¿Quieres decir con Gustav...",
  ui_story_5033_50331502_102_dialog_content = "No. Me refiero a esa vez, hace 14 años...",
  ui_story_5033_50331502_103_dialog_content = "¿Todavía serías apuñalado por mí?",
  ui_story_5033_50331502_104_dialog_content = "Sí. Si tuviera una segunda oportunidad, correría hacia ti de la misma manera.",
  ui_story_5033_50331502_105_dialog_content = "Y luego te abrazaría fuerte y me despediría.",
  ui_story_5033_50331502_106_dialog_content = "Justo como ahora...",
  ui_story_5033_50331502_107_dialog_content = "<color=#e8d9bb>*Puñalada—*</color>",
  ui_story_5033_50331502_108_dialog_content = "...",
  ui_story_5033_50331502_109_dialog_content = "Tus ojos son mucho más resueltos que entonces.",
  ui_story_5033_50331502_110_dialog_content = "Has cambiado, Pólux. Es bueno ver",
  ui_story_5033_50331502_111_dialog_content = "Y... De hecho guardaste... esa daga...",
  ui_story_5033_50331502_112_dialog_content = "Ya no. Voy a enterrarlo después de hoy.",
  ui_story_5033_50331502_113_dialog_content = "Adiós, mi Pólux.",
  ui_story_5033_50331502_114_dialog_content = "Adiós... Antares, llena de pecado.",
  ui_story_5033_50331502_115_dialog_content = "Ahora, por fin, soy igual que tú.",
  ui_story_5033_50331502_116_dialog_content = "Correos-",
  ui_story_5033_50331502_117_dialog_content = "¡¿?!",
  ui_story_5033_50331502_118_dialog_content = "Esto... ¡¿Antares y Gustav?!",
  ui_story_5033_50331502_119_dialog_content = "...",
  ui_story_5033_50331502_120_dialog_content = "¡Pólux! ¿Estás bien?",
  ui_story_5033_50331502_121_dialog_content = "...",
  ui_story_5033_50331502_122_dialog_content = "Corax, ¿puedes ayudarme a verificar?",
  ui_story_5033_50331502_123_dialog_content = "Gustavo está muerto. Déjame ver cómo está Anne...",
  ui_story_5033_50331502_124_dialog_content = "No hay necesidad.",
  ui_story_5033_50331502_125_dialog_content = "¿Qué?",
  ui_story_5033_50331502_126_dialog_content = "No hay necesidad, doctor.",
  ui_story_5033_50331502_127_dialog_content = "Tu misión... <color=#FFB400>ha fallado</color>.",
  ui_story_5033_50331502_128_dialog_content = "<color=#e8d9bb>*Retumbar*</color>",
  ui_story_5033_50331601_1_dialog_content = "<color=#e8d9bb>Varias horas después</color>",
  ui_story_5033_50331601_2_dialog_content = "... Entonces, realmente fue Gustav quien tiró de los hilos.",
  ui_story_5033_50331601_3_dialog_content = "He estado diciendo durante mucho tiempo que estaba usando a todos, pero nadie escuchó. Hmph.",
  ui_story_5033_50331601_4_dialog_content = "Parece que la monja asesina está muerta. Eliminado por la propia Pólux.",
  ui_story_5033_50331601_5_dialog_content = "No esperaba menos de Pollux... Tenemos suerte de tenerla...",
  ui_story_5033_50331601_6_dialog_content = "Escuché que crecieron juntos. ¿Supongo que era algo que no podía pasar por alto?",
  ui_story_5033_50331601_7_dialog_content = "Nada de chismes a espaldas de la gente.",
  ui_story_5033_50331601_8_dialog_content = "Si realmente no tienes nada más que hacer, entonces puedes ayudarme a reparar las paredes y las ventanas de la iglesia. Los niños todavía necesitan un lugar donde vivir.",
  ui_story_5033_50331601_9_dialog_content = "Tienes la edad suficiente para asumir parte de la responsabilidad.",
  ui_story_5033_50331601_10_dialog_content = "Sí, sí...",
  ui_story_5033_50331601_11_dialog_content = "Nekoyashiki, por el momento, todos han regresado a la iglesia.",
  ui_story_5033_50331601_12_dialog_content = "Bien hecho, Latán.",
  ui_story_5033_50331601_13_dialog_content = "Entonces, ¿qué hay de Pólux? Todos estamos muy preocupados...",
  ui_story_5033_50331601_14_dialog_content = "Ella... Ella está atando algunos cabos sueltos con Casta.",
  ui_story_5033_50331601_15_dialog_content = "Están en esas colinas detrás de nosotros y deberían regresar pronto. Entras, sigue lloviendo.",
  ui_story_5033_50331601_16_dialog_content = "La lluvia paró hace años, Nekoyashiki.",
  ui_story_5033_50331601_17_dialog_content = "\"... Su difícil camino ha llegado a su fin y, sin embargo, le espera un nuevo viaje\".",
  ui_story_5033_50331601_18_dialog_content = "\"Regresará a la tierra y se fusionará con los lagos...\"",
  ui_story_5033_50331601_19_dialog_content = "\"Y finalmente, volver al polvo de estrellas\".",
  ui_story_5033_50331601_20_dialog_content = "...",
  ui_story_5033_50331601_21_dialog_content = "El cielo se está despejando, Pólux.",
  ui_story_5033_50331601_22_dialog_content = "Ah, es tan brillante. ¿El sol siempre ha sido así de deslumbrante...?",
  ui_story_5033_50331601_23_dialog_content = "¿Ves que la niebla también se ha ido? Así es como realmente es Euphoria.",
  ui_story_5033_50331601_24_dialog_content = "Gracias, PlayerName, por ofrecerse a leer el elogio de Anne.",
  ui_story_5033_50331601_25_dialog_content = "Me avergüenza admitir que ni siquiera puedo hacer esto, a pesar de vivir en la iglesia durante tantos años.",
  ui_story_5033_50331601_26_dialog_content = "Oh, tal vez no puedas encontrar una manera de expresarte.",
  ui_story_5033_50331601_27_dialog_content = "Quizás el elogio ordinario, dado a tanta gente todos los días, no es adecuado para Antares.",
  ui_story_5033_50331601_28_dialog_content = "De todos modos, lamento tu pérdida.",
  ui_story_5033_50331601_29_dialog_content = "no estoy de duelo Al contrario, estoy bastante aliviado.",
  ui_story_5033_50331601_30_dialog_content = "Es como despertar de un sueño caótico, haber visto gente que nunca volverás a ver.",
  ui_story_5033_50331601_31_dialog_content = "Pero ahora me he despertado del sueño, el cielo está brillante y debo seguir mi propio camino.",
  ui_story_5033_50331601_32_dialog_content = "¿Qué es lo siguiente?",
  ui_story_5033_50331601_33_dialog_content = "Creo que me quedaré aquí por un tiempo.",
  ui_story_5033_50331601_34_dialog_content = "No solo por los niños en la iglesia, sino también porque es raro ver a Euphoria tan claramente.",
  ui_story_5033_50331601_35_dialog_content = "Esto es probablemente lo que Antares también deseaba ver.",
  ui_story_5033_50331601_36_dialog_content = "Quizás. O tal vez ella quería expiar sus pecados por mi mano.",
  ui_story_5033_50331601_37_dialog_content = "Ella era realmente complicada.",
  ui_story_5033_50331601_38_dialog_content = "Si realmente hubiera muerto hace catorce años, y nadie la hubiera utilizado...",
  ui_story_5033_50331601_39_dialog_content = "O si no hubiéramos sido hechos para matarnos, y Géminis hubiera seguido...",
  ui_story_5033_50331601_40_dialog_content = "¿O si nunca nos hubiésemos conocido?",
  ui_story_5033_50331601_41_dialog_content = "Antares y Pollux, solo dos completos extraños, haciendo sus vidas.",
  ui_story_5033_50331601_42_dialog_content = "¿Sería diferente la historia?",
  ui_story_5033_50331601_43_dialog_content = "¿Cuál sería el nuevo destino de Euphoria?",
  ui_story_5033_50331601_44_dialog_content = "Vamos, Pólux. No es propio de ti ser tan nostálgico.",
  ui_story_5033_50331601_45_dialog_content = "Estás bien. Estoy listo para decir adiós al pasado.",
  ui_story_5033_50331601_46_dialog_content = "Ese cuchillo, y el broche de hortensias...",
  ui_story_5033_50331601_47_dialog_content = "Que descansen en paz junto con Antares.",
  ui_story_5033_50331601_48_dialog_content = "Eso me recuerda que no le hemos presentado nuestros respetos a Matilda este año.",
  ui_story_5033_50331601_49_dialog_content = "Oh, es cierto. Déjame encargarme de todo aquí, luego deberíamos encontrar un momento para visitar Umbraton.",
  ui_story_5033_50331601_50_dialog_content = "Está bien, no te molestaré más. Adiós, Pólux, Casta.",
  ui_story_5033_50331601_51_dialog_content = "¿Vas solo al dirigible Shuttle Hub?",
  ui_story_5033_50331601_52_dialog_content = "Con todos corriendo como pollos sin cabeza, el camino podría ser aún más difícil.",
  ui_story_5033_50331601_53_dialog_content = "Pero Corax volvió a Umbraton solo otra vez, dijo algo sobre hacer un informe...",
  ui_story_5033_50331601_54_dialog_content = "Iré contigo.",
  ui_story_5033_50331601_55_dialog_content = "Sí, deja que Casta te acompañe.",
  ui_story_5033_50331601_56_dialog_content = "Todavía tengo algunos... otros asuntos que atender. Chicos, adelante.",
  ui_story_5033_50331601_57_dialog_content = "Creo que nos encontraremos de nuevo, PlayerName. Solo espera a que Euphoria se convierta en un verdadero país de las maravillas.",
  ui_story_5033_50331601_58_dialog_content = "Por supuesto, Pólux. Espero ese día.",
  ui_story_5033_50331601_59_dialog_content = "<color=#e8d9bb>Umbraton, dos días después</color>",
  ui_story_5033_50331601_60_dialog_content = "¡Lee todos los detalles! ¡Criminal en asesinatos en serie de Umbraton muerto durante la captura!",
  ui_story_5033_50331601_61_dialog_content = "¿Quiere un periódico, Sr. Corax?",
  ui_story_5033_50331601_62_dialog_content = "¿Cómo me reconociste...?",
  ui_story_5033_50331601_63_dialog_content = "Aléjate de mí, sigue.",
  ui_story_5033_50331601_64_dialog_content = "Muy bien, no hay necesidad de ser tan malo. ¡Lee todos los detalles!",
  ui_story_5033_50331601_65_dialog_content = "...",
  ui_story_5033_50331601_66_dialog_content = "Llegas tarde.",
  ui_story_5033_50331601_67_dialog_content = "Casta no es un gran piloto de dirigible.",
  ui_story_5033_50331601_67X1_dialog_content = "Sígueme.",
  ui_story_5033_50331601_68_dialog_content = "<color=#e8d9bb>*Paso de página*</color>",
  ui_story_5033_50331601_69_dialog_content = "Qué es esto...?",
  ui_story_5033_50331601_70_dialog_content = "Caso cerrado. Shadowlord ha visto el archivo y el asunto se resuelve más o menos como se describe.",
  ui_story_5033_50331601_71_dialog_content = "Bien. Gracias Corax.",
  ui_story_5033_50331601_72_dialog_content = "¡Realmente deberías estar agradeciéndome!",
  ui_story_5033_50331601_73_dialog_content = "Claramente estaba allí en una misión, pero no logré traer de vuelta a ninguno de los dos sospechosos, lo siento, dos criminales.",
  ui_story_5033_50331601_74_dialog_content = "Jaja, eso realmente es desafortunado.",
  ui_story_5033_50331601_75_dialog_content = "Yo...",
  ui_story_5033_50331601_76_dialog_content = "[Error null-The operation has timed out]",
  ui_story_5033_50331601_77_dialog_content = "El plan de Shadowlord es reconstruir Euphoria contigo. Vea si hay algún problema.",
  ui_story_5033_50331601_78_dialog_content = "Con Gustav muerto, debe ser una locura allí.",
  ui_story_5033_50331601_79_dialog_content = "Hay muchas pandillas de Umbraton que dependen de Euphoria para ganarse la vida. Tendremos que pensar en algunas ideas nuevas.",
  ui_story_5033_50331601_80_dialog_content = "Shadowlord no quiere seguir el mismo camino de siempre. De lo contrario, no hay diferencia con esos miserables. ¿Tú entiendes?",
  ui_story_5033_50331601_81_dialog_content = "Estoy de acuerdo. Eso es lo que estaba pensando yo también.",
  ui_story_5033_50331601_82_dialog_content = "La carne podrida ya ha sido extirpada. Es hora de empezar de nuevo.",
  ui_story_5033_50331601_83_dialog_content = "Esa es una buena analogía. Euphoria fue el paciente gravemente enfermo al que finalmente se le extirparon las partes necróticas...",
  ui_story_5033_50331601_84_dialog_content = "Es hora de un nuevo tratamiento que conducirá a un tejido sano.",
  ui_story_5033_50331601_85_dialog_content = "Sí, y el nuevo tratamiento es el plan de reconstrucción de Umbraton.",
  ui_story_5033_50331601_86_dialog_content = "Esos niños finalmente pueden crecer como el tejido sano de Euphoria.",
  ui_story_5033_50331601_87_dialog_content = "¿Qué más hay en el plan, Corax? ¿Aparte de la reestructuración industrial?",
  ui_story_5033_50331601_88_dialog_content = "¿Algo así como bienestar social?",
  ui_story_5033_50331601_89_dialog_content = "¿Estás pensando en un orfanato?",
  ui_story_5033_50331601_90_dialog_content = "¡Relax! Siéntete libre de mencionar lo que quieras. No creo que Shadowlord rechace estas sugerencias.",
  ui_story_5033_50331601_91_dialog_content = "Después de todo, es un gran fanático de acoger niños... Ejem.",
  ui_story_5033_50331601_92_dialog_content = "Parece que tengo algo en común con él después de todo: ambos somos pesimistas optimistas.",
  ui_story_5033_50331601_93_dialog_content = "Creo que entiendo eso.",
  ui_story_5033_50331601_94_dialog_content = "Ambos pueden creer que el mundo está más allá de la ayuda y aún así tener esperanza para la próxima generación.",
  ui_story_5033_50331601_95_dialog_content = "Los ojos de los niños no mienten, Corax. Sólo tienes que ir a un orfanato oa una escuela y podrás comprobarlo por ti mismo.",
  ui_story_5033_50331601_96_dialog_content = "Esos son los únicos lugares puros y buenos que quedan.",
  ui_story_5033_50331601_97_dialog_content = "Creo que tenemos que confiar en esos niños si Euphoria quiere volver a estar soleada alguna vez.",
  ui_story_5033_50331601_98_dialog_content = "Al igual que Matilda creyó en nosotros, hace tantos años.",
  ui_story_5033_50331601_99_dialog_content = "...",
  ui_story_5033_50331601_100_dialog_content = "Ya es suficiente charla. Revisaremos los planes nuevamente y nos pondremos en contacto con usted.",
  ui_story_5033_50331601_101_dialog_content = "Si no hay nada más, me despediré.",
  ui_story_5033_50331601_102_dialog_content = "Déjame verte en el Shuttle Hub.",
  ui_story_5033_50331601_103_dialog_content = "No es necesario, pero gracias. Quiero visitar el cementerio.",
  ui_story_5033_50331601_104_dialog_content = "¿Para presentar sus respetos a Matilda? Creo que a mí también me gustaría eso, ¿está bien?",
  ui_story_5033_50331601_105_dialog_content = "Por supuesto. Gracias Corax.",
  ui_story_5033_50331601_106_dialog_content = "Vamos, ¿qué pasa con todos los \"gracias\" hoy? No estoy acostumbrado a que seas tan formal.",
  ui_story_5033_50331601_107_dialog_content = "<color=#e8d9bb>Coloso, Puente</color>",
  ui_story_5033_50331601_108_dialog_content = "Tamaño adecuado para cortinas. Podría ser una falda, con unos metros más.",
  ui_story_5033_50331601_109_dialog_content = "*Suspiro*",
  ui_story_5033_50331601_110_dialog_content = "Mesa de comedor, lámpara de pie, alfombra... ¿Hay alguna aberración cromática con la alfombra?",
  ui_story_5033_50331601_111_dialog_content = "*Suspiro*",
  ui_story_5033_50331601_112_dialog_content = "Estante, mira... ¿Dónde está la tabla de cortar de dibujos animados? Ah, aquí está.",
  ui_story_5033_50331601_113_dialog_content = "*Suspiro...*",
  ui_story_5033_50331601_114_dialog_content = "Estás bien, PlayerName? ¿Todo esto te está cansando?",
  ui_story_5033_50331601_115_dialog_content = "Me siento un poco deprimido, Vice.",
  ui_story_5033_50331601_116_dialog_content = "Lo que sucedió estos últimos días parece un sueño.",
  ui_story_5033_50331601_117_dialog_content = "¿Por qué siempre te embarcas en estas extrañas aventuras cuando no estoy, hmm?",
  ui_story_5033_50331601_118_dialog_content = "¿Cuál es la historia esta vez?",
  ui_story_5033_50331601_119_dialog_content = "Déjame organizar mis pensamientos. Ni siquiera sé por dónde empezar.",
  ui_story_5033_50331601_120_dialog_content = "Bien. De todos modos, ¿qué pasa con esto... \"Hortensia saludable\"?",
  ui_story_5033_50331601_121_dialog_content = "Una compra impulsiva de la que me arrepentí inmediatamente. Atrae un montón de bichos.",
  ui_story_5033_50331601_122_dialog_content = "Aún así, déjalo ahí. Me gusta mirarlo.",
  ui_story_5033_50331601_123_dialog_content = "Oh tu. Parece que tienes el mundo sobre tus hombros.",
  ui_story_5033_50331601_124_dialog_content = "Tienes que decirme qué pasó esta vez.",
  ui_story_5033_50331601_125_dialog_content = "Multa. ¿Has oído hablar de la euforia?",
  ui_story_5033_50331601_126_dialog_content = "Hmm... Suena una campana.",
  ui_story_5033_50331601_127_dialog_content = "Bueno, todo comienza con este lugar llamado Euforia..."
}
return config
